pub const AdapterNoopDdlReason = enum {
    schema_namespace,
    extension,
    transaction_control,
    session_setting,
};

pub const AdapterNoopDdlPlan = struct {
    reason: AdapterNoopDdlReason,
};

pub const SessionCatalogPlan = union(enum) {
    set_search_path: SetSearchPathPlan,
    set_setting: SetSessionSettingPlan,
    reset_setting: ResetSessionSettingPlan,
    reset_search_path,
    show_search_path,
    discard_all,

    pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        switch (self.*) {
            .set_search_path => |*plan| plan.deinit(alloc),
            .set_setting => |*plan| plan.deinit(alloc),
            .reset_setting => |*plan| plan.deinit(alloc),
            else => {},
        }
        self.* = undefined;
    }
};

pub const SetSearchPathPlan = struct {
    namespaces: []const []const u8 = &.{},
    local: bool = false,

    pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        freeStringSlice(alloc, self.namespaces);
        self.* = undefined;
    }
};

pub fn parseSetSearchPathPlanTailAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
) !SetSearchPathPlan {
    var syntax = try grammar.parseSetSearchPathTailAlloc(alloc, tokens, pos);
    errdefer syntax.deinit(alloc);
    const namespaces = syntax.namespaces;
    syntax.namespaces = &.{};
    return .{ .namespaces = namespaces, .local = syntax.local };
}

pub const SessionSettingKind = enum {
    app,
    antfly,
    runtime,
};

pub const SetSessionSettingPlan = struct {
    name: []const u8,
    value: []const u8,
    kind: SessionSettingKind = .app,
    local: bool = false,

    pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        alloc.free(self.name);
        alloc.free(self.value);
        self.* = undefined;
    }
};

pub const ResetSessionSettingPlan = struct {
    name: []const u8,
    kind: SessionSettingKind = .app,

    pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        alloc.free(self.name);
        self.* = undefined;
    }
};

pub const EnumTypeCatalogPlan = union(enum) {
    create: CreateEnumTypePlan,
    add_value: AddEnumValuePlan,
    drop: DropEnumTypePlan,

    pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        switch (self.*) {
            .create => |*plan| plan.deinit(alloc),
            .add_value => |*plan| plan.deinit(alloc),
            .drop => |*plan| plan.deinit(alloc),
        }
        self.* = undefined;
    }
};

pub const CreateEnumTypePlan = struct {
    type_name: []const u8,
    values: []const []const u8 = &.{},

    pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        alloc.free(self.type_name);
        freeStringSlice(alloc, self.values);
        self.* = undefined;
    }
};

pub const AddEnumValuePlan = struct {
    type_name: []const u8,
    value: []const u8,
    if_not_exists: bool = false,
    position: EnumValuePosition = .none,
    neighbor_value: ?[]const u8 = null,

    pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        alloc.free(self.type_name);
        alloc.free(self.value);
        if (self.neighbor_value) |value| alloc.free(value);
        self.* = undefined;
    }
};

pub const EnumValuePosition = enum {
    none,
    before,
    after,
};

pub const DropEnumTypePlan = struct {
    type_name: []const u8,
    if_exists: bool = false,
    cascade: bool = false,

    pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        alloc.free(self.type_name);
        self.* = undefined;
    }
};

pub const DomainCatalogPlan = union(enum) {
    create: CreateDomainPlan,
    alter: AlterDomainPlan,
    drop: DropDomainPlan,

    pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        switch (self.*) {
            .create => |*plan| plan.deinit(alloc),
            .alter => |*plan| plan.deinit(alloc),
            .drop => |*plan| plan.deinit(alloc),
        }
        self.* = undefined;
    }
};

pub const CreateDomainPlan = struct {
    domain_name: []const u8,
    field_type: runtime_schema.AntflyType,
    array_item_type: ?runtime_schema.AntflyType = null,
    not_null: bool = false,
    default_value: ?runtime_schema.RelationalDefaultValue = null,
    checks: []const runtime_schema.RelationalCheck = &.{},

    pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        alloc.free(self.domain_name);
        if (self.default_value) |default| alloc.free(default.value_json);
        freeDdlRelationalChecks(alloc, self.checks);
        self.* = undefined;
    }
};

pub const AlterDomainPlan = struct {
    domain_name: []const u8,
    operations: []const DomainAlterOperation = &.{},

    pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        alloc.free(self.domain_name);
        freeDomainAlterOperations(alloc, self.operations);
        self.* = undefined;
    }
};

pub const DomainAlterOperation = union(enum) {
    set_not_null,
    drop_not_null,
    set_default: runtime_schema.RelationalDefaultValue,
    drop_default,

    pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        switch (self.*) {
            .set_default => |default| alloc.free(default.value_json),
            else => {},
        }
        self.* = undefined;
    }
};

pub const DropDomainPlan = struct {
    domain_name: []const u8,
    if_exists: bool = false,
    cascade: bool = false,

    pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        alloc.free(self.domain_name);
        self.* = undefined;
    }
};

pub const IdentityAllocatorPlan = struct {
    table_name: []const u8,
    column: runtime_schema.RelationalColumn,
    kind: IdentityAllocatorKind,
    options: SequenceOptions = .{},
    primary_key: bool = false,
    additional_columns: []const runtime_schema.RelationalColumn = &.{},

    pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        alloc.free(self.table_name);
        freeDdlRelationalColumn(alloc, self.column);
        self.options.deinit(alloc);
        clearDdlRelationalColumns(alloc, self.additional_columns);
        if (self.additional_columns.len > 0) alloc.free(self.additional_columns);
        self.* = undefined;
    }
};

pub const IdentityAllocatorKind = enum {
    serial,
    bigserial,
    generated_by_default,
    generated_always,
};

pub const IdentityAllocatorSpec = struct {
    kind: IdentityAllocatorKind,
    options: SequenceOptions = .{},

    pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        self.options.deinit(alloc);
        self.* = undefined;
    }
};

const LegacyDdlParserPlan = union(enum) {
    adapter_noop: AdapterNoopDdlPlan,
    session_catalog: SessionCatalogPlan,
    create_table: CreateTablePlan,
    table_clone: TableClonePlan,
    view_catalog: ViewCatalogPlan,
    materialized_view_catalog: MaterializedViewCatalogPlan,
    relation_lifetime: RelationLifetimePlan,
    enum_type_catalog: EnumTypeCatalogPlan,
    domain_catalog: DomainCatalogPlan,
    sequence_catalog: SequenceCatalogPlan,
    identity_allocator_catalog: IdentityAllocatorPlan,
    schema_namespace_catalog: SchemaNamespaceCatalogPlan,
    extension_catalog: ExtensionCatalogPlan,
    function_catalog: FunctionCatalogPlan,
    trigger_catalog: TriggerCatalogPlan,
    procedure_call: ProcedureCallPlan,
    authorization_catalog: AuthorizationCatalogPlan,
    bulk_io: BulkIoPlan,
    table_partition_catalog: TablePartitionCatalogPlan,
    row_security_catalog: RowSecurityCatalogPlan,
    database_catalog: DatabaseCatalogPlan,
    tablespace_catalog: TablespaceCatalogPlan,
    notification_channel: NotificationChannelPlan,
    logical_replication: LogicalReplicationPlan,
    type_system_catalog: TypeSystemCatalogPlan,
    maintenance_job: MaintenanceJobPlan,
    prepared_statement: PreparedStatementPlan,
    prepared_transaction: PreparedTransactionPlan,
    cursor_portal: CursorPortalPlan,
    savepoint_transaction: SavepointTransactionPlan,
    comment_metadata: CommentMetadataPlan,
    transaction_control: TransactionControlPlan,
    create_index: CreateIndexPlan,
    drop_index: DropIndexPlan,
    drop_table: DropTablePlan,
    alter_table: AlterTablePlan,
    create_update_policy: CreateUpdatePolicyPlan,

    pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        switch (self.*) {
            .adapter_noop => {},
            .session_catalog => |*plan| plan.deinit(alloc),
            .create_table => |*plan| plan.deinit(alloc),
            .table_clone => |*plan| plan.deinit(alloc),
            .view_catalog => |*plan| plan.deinit(alloc),
            .materialized_view_catalog => |*plan| plan.deinit(alloc),
            .relation_lifetime => |*plan| plan.deinit(alloc),
            .enum_type_catalog => |*plan| plan.deinit(alloc),
            .domain_catalog => |*plan| plan.deinit(alloc),
            .sequence_catalog => |*plan| plan.deinit(alloc),
            .identity_allocator_catalog => |*plan| plan.deinit(alloc),
            .schema_namespace_catalog => |*plan| plan.deinit(alloc),
            .extension_catalog => |*plan| plan.deinit(alloc),
            .function_catalog => |*plan| plan.deinit(alloc),
            .trigger_catalog => |*plan| plan.deinit(alloc),
            .procedure_call => |*plan| plan.deinit(alloc),
            .authorization_catalog => |*plan| plan.deinit(alloc),
            .bulk_io => |*plan| plan.deinit(alloc),
            .table_partition_catalog => |*plan| plan.deinit(alloc),
            .row_security_catalog => |*plan| plan.deinit(alloc),
            .database_catalog => |*plan| plan.deinit(alloc),
            .tablespace_catalog => |*plan| plan.deinit(alloc),
            .notification_channel => |*plan| plan.deinit(alloc),
            .logical_replication => |*plan| plan.deinit(alloc),
            .type_system_catalog => |*plan| plan.deinit(alloc),
            .maintenance_job => |*plan| plan.deinit(alloc),
            .prepared_statement => |*plan| plan.deinit(alloc),
            .prepared_transaction => |*plan| plan.deinit(alloc),
            .cursor_portal => |*plan| plan.deinit(alloc),
            .savepoint_transaction => |*plan| plan.deinit(alloc),
            .comment_metadata => |*plan| plan.deinit(alloc),
            .transaction_control => |*plan| plan.deinit(alloc),
            .create_index => |*plan| plan.deinit(alloc),
            .drop_index => |*plan| plan.deinit(alloc),
            .drop_table => |*plan| plan.deinit(alloc),
            .alter_table => |*plan| plan.deinit(alloc),
            .create_update_policy => |*plan| plan.deinit(alloc),
        }
        self.* = undefined;
    }
};

pub const DdlPlanParserOptions = struct {
    schema: runtime_schema.TableSchema = .{},
    field_expression_qualifiers: []const []const u8 = &.{},
    returning_expression_qualifiers: []const []const u8 = &.{},
    defer_row_expression_field_validation: bool = false,
    column_definition_options: DdlColumnDefinitionOptions,
    domain_options: DdlDomainOptions,
    create_index_options: CreateIndexOptions,
    row_security_policy_options: RowSecurityPolicyOptions,
};

fn parseLegacyDdlParserPlanAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    options: DdlPlanParserOptions,
) !LegacyDdlParserPlan {
    const cursor = parser.Cursor.init(tokens, pos);
    if (cursor.matchKeyword("call")) {
        return .{ .procedure_call = try parseProcedureCallPlanTailAlloc(alloc, tokens, pos) };
    }
    if (cursor.matchKeyword("create")) {
        if (cursor.matchKeyword("or")) {
            try cursor.expectKeyword("replace");
            if (cursor.peekKeyword("trigger")) return try parseCreateTriggerLegacyDdlPlanTailAlloc(alloc, tokens, pos, true);
            if (cursor.peekKeyword("materialized")) {
                return .{ .materialized_view_catalog = .{ .create = try parseCreateMaterializedViewPlanTailAlloc(alloc, tokens, pos, true) } };
            }
            if (cursor.peekKeyword("view")) {
                return .{ .view_catalog = .{ .create = try parseCreateViewPlanTailAlloc(alloc, tokens, pos, true) } };
            }
            if (cursor.peekKeyword("function") or cursor.peekKeyword("procedure")) {
                return .{ .function_catalog = .{ .create = try parseCreateRoutinePlanTailAlloc(alloc, tokens, pos, true) } };
            }
            if (!cursor.peekKeyword("table")) return error.UnsupportedSqlShape;
            var create_table = try parseCreateTablePlanAlloc(alloc, tokens, pos, options.column_definition_options);
            create_table.replace_existing = true;
            return .{ .create_table = create_table };
        }
        const unique = cursor.matchKeyword("unique");
        if (cursor.peekKeyword("index")) {
            return .{ .create_index = try parseCreateIndexPlanAlloc(alloc, tokens, pos, unique, options.create_index_options) };
        }
        if (cursor.peekKeyword("graph")) {
            if (unique) return error.UnsupportedSqlShape;
            if (pos.* + 1 < tokens.len and tokens[pos.* + 1].matchesKeyword("metric")) {
                return .{ .create_index = try parseCreateGraphMetricPlanAlloc(alloc, tokens, pos) };
            }
            return .{ .create_index = try parseCreateGraphIndexPlanAlloc(alloc, tokens, pos) };
        }
        if (unique) return error.UnsupportedSqlShape;
        if (cursor.peekKeyword("trigger")) return try parseCreateTriggerLegacyDdlPlanTailAlloc(alloc, tokens, pos, false);
        if (cursor.peekKeyword("materialized")) {
            return .{ .materialized_view_catalog = .{ .create = try parseCreateMaterializedViewPlanTailAlloc(alloc, tokens, pos, false) } };
        }
        if (cursor.peekKeyword("view")) {
            return .{ .view_catalog = .{ .create = try parseCreateViewPlanTailAlloc(alloc, tokens, pos, false) } };
        }
        if (cursor.peekKeyword("domain")) {
            return .{ .domain_catalog = .{ .create = try parseCreateDomainPlanAlloc(alloc, tokens, pos, options.domain_options) } };
        }
        if (cursor.peekKeyword("sequence")) return .{ .sequence_catalog = .{ .create = try parseCreateSequencePlanTailAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("type")) {
            return .{ .enum_type_catalog = .{ .create = try parseCreateEnumTypePlanTailAlloc(alloc, tokens, pos) } };
        }
        if (cursor.peekKeyword("schema")) {
            var create_schema = try parseCreateSchemaNamespacePlanTailAlloc(alloc, tokens, pos);
            if (create_schema.if_not_exists and std.ascii.eqlIgnoreCase(create_schema.schema_name, "public")) {
                create_schema.deinit(alloc);
                return .{ .adapter_noop = .{ .reason = .schema_namespace } };
            }
            return .{ .schema_namespace_catalog = .{ .create = create_schema } };
        }
        if (cursor.peekKeyword("extension")) {
            var create_extension = try parseCreateExtensionPlanTailAlloc(alloc, tokens, pos, catalog_resources.default_namespace_name);
            if (create_extension.if_not_exists and isAdapterNoopExtensionName(create_extension.extension_name)) {
                create_extension.deinit(alloc);
                return .{ .adapter_noop = .{ .reason = .extension } };
            }
            return .{ .extension_catalog = .{ .create = create_extension } };
        }
        if (cursor.peekKeyword("function") or cursor.peekKeyword("procedure")) {
            return .{ .function_catalog = .{ .create = try parseCreateRoutinePlanTailAlloc(alloc, tokens, pos, false) } };
        }
        if (isRoleAliasKeywordAt(tokens, pos.*)) {
            return .{ .authorization_catalog = .{ .create_role = try parseCreateRolePlanTailAlloc(alloc, tokens, pos) } };
        }
        if (cursor.peekKeyword("policy")) {
            return .{ .row_security_catalog = .{ .create_policy = try parseCreateRowSecurityPolicyPlanTailAllocWithOptions(alloc, tokens, pos, options.row_security_policy_options) } };
        }
        if (cursor.peekKeyword("database")) return .{ .database_catalog = .{ .create = try parseCreateDatabasePlanTailAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("tablespace")) return .{ .tablespace_catalog = .{ .create = try parseCreateTablespacePlanTailAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("publication")) return .{ .logical_replication = .{ .publication = .{ .create = try parseCreatePublicationPlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("subscription")) return .{ .logical_replication = .{ .subscription = .{ .create = try parseCreateSubscriptionPlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("collation")) return .{ .type_system_catalog = .{ .collation = .{ .create = try parseCreateCollationPlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("operator")) return .{ .type_system_catalog = .{ .operator = .{ .create = try parseCreateOperatorPlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("aggregate")) return .{ .type_system_catalog = .{ .aggregate = .{ .create = try parseCreateAggregatePlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("cast")) return .{ .type_system_catalog = .{ .cast = .{ .create = try parseCreateCastPlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("temporary") or cursor.peekKeyword("temp") or cursor.peekKeyword("unlogged")) {
            return .{ .relation_lifetime = try parseRelationLifetimePlanAlloc(alloc, tokens, pos, options.column_definition_options) };
        }
        const checkpoint = pos.*;
        if (parseIdentityAllocatorPlanAlloc(alloc, tokens, pos, options.column_definition_options)) |identity| {
            return .{ .identity_allocator_catalog = identity };
        } else |err| switch (err) {
            error.UnsupportedSqlShape => pos.* = checkpoint,
            else => return err,
        }
        if (parseCreateTablePartitionPlanTailAlloc(alloc, tokens, pos)) |partition| {
            return .{ .table_partition_catalog = .{ .create_partition = partition } };
        } else |err| switch (err) {
            error.UnsupportedSqlShape => pos.* = checkpoint,
            else => return err,
        }
        if (parseCreatePartitionedTablePlanAlloc(alloc, tokens, pos, options.column_definition_options)) |partitioned| {
            return .{ .table_partition_catalog = .{ .create_partitioned = partitioned } };
        } else |err| switch (err) {
            error.UnsupportedSqlShape => pos.* = checkpoint,
            else => return err,
        }
        if (parseCreateTableClonePlanTailAlloc(alloc, tokens, pos)) |table_clone| {
            return .{ .table_clone = table_clone };
        } else |err| switch (err) {
            error.UnsupportedSqlShape => pos.* = checkpoint,
            else => return err,
        }
        return .{ .create_table = try parseCreateTablePlanAlloc(alloc, tokens, pos, options.column_definition_options) };
    }
    if (cursor.matchKeyword("alter")) {
        if (cursor.peekKeyword("graph")) return .{ .create_index = try parseAlterGraphIndexAddMetricPlanAlloc(alloc, tokens, pos) };
        if (cursor.peekKeyword("domain")) return .{ .domain_catalog = .{ .alter = try parseAlterDomainPlanTailAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("sequence")) return .{ .sequence_catalog = .{ .alter = try parseAlterSequencePlanTailAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("type")) return .{ .enum_type_catalog = .{ .add_value = try parseAlterEnumTypePlanTailAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("extension")) return .{ .extension_catalog = .{ .update = try parseUpdateExtensionPlanTailAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("schema")) return .{ .schema_namespace_catalog = .{ .rename = try parseRenameSchemaNamespacePlanTailAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("database")) return .{ .database_catalog = .{ .alter = try parseAlterDatabasePlanTailAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("tablespace")) return .{ .tablespace_catalog = .{ .rename = try parseRenameTablespacePlanTailAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("publication")) return .{ .logical_replication = .{ .publication = .{ .alter = try parseAlterPublicationPlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("subscription")) return .{ .logical_replication = .{ .subscription = .{ .alter = try parseAlterSubscriptionPlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("collation")) return .{ .type_system_catalog = .{ .collation = .{ .rename = try parseRenameCollationPlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("view")) return .{ .view_catalog = .{ .rename = try parseRenameViewPlanTailAlloc(alloc, tokens, pos) } };
        if (isRoleAliasKeywordAt(tokens, pos.*)) return .{ .authorization_catalog = .{ .alter_role = try parseAlterRolePlanTailAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("policy")) return .{ .row_security_catalog = .{ .alter_policy = try parseAlterRowSecurityPolicyPlanTailAllocWithOptions(alloc, tokens, pos, options.row_security_policy_options) } };
        if (cursor.peekKeyword("table")) {
            const checkpoint = pos.*;
            if (parseAlterRowSecurityPlanTailAlloc(alloc, tokens, pos)) |row_security| {
                return .{ .row_security_catalog = .{ .alter_table = row_security } };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => pos.* = checkpoint,
                else => return err,
            }
        }
        if (cursor.peekKeyword("table")) {
            const checkpoint = pos.*;
            if (parseAlterTablePartitionPlanTailAlloc(alloc, tokens, pos)) |partition| {
                return .{ .table_partition_catalog = partition };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => pos.* = checkpoint,
                else => return err,
            }
        }
        return .{ .alter_table = try parseAlterTablePlanAlloc(alloc, tokens, pos, options.column_definition_options) };
    }
    if (cursor.matchKeyword("drop")) {
        if (cursor.peekKeyword("materialized")) return .{ .materialized_view_catalog = .{ .drop = try parseDropMaterializedViewPlanTailAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("view")) return .{ .view_catalog = .{ .drop = try parseDropViewPlanTailAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("domain")) return .{ .domain_catalog = .{ .drop = try parseDropDomainPlanTailAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("sequence")) return .{ .sequence_catalog = .{ .drop = try parseDropSequencePlanTailAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("type")) return .{ .enum_type_catalog = .{ .drop = try parseDropEnumTypePlanTailAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("schema")) return .{ .schema_namespace_catalog = .{ .drop = try parseDropSchemaNamespacePlanTailAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("extension")) return .{ .extension_catalog = .{ .drop = try parseDropExtensionPlanTailAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("database")) return .{ .database_catalog = .{ .drop = try parseDropDatabasePlanTailAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("tablespace")) return .{ .tablespace_catalog = .{ .drop = try parseDropTablespacePlanTailAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("publication")) return .{ .logical_replication = .{ .publication = .{ .drop = try parseDropPublicationPlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("subscription")) return .{ .logical_replication = .{ .subscription = .{ .drop = try parseDropSubscriptionPlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("collation")) return .{ .type_system_catalog = .{ .collation = .{ .drop = try parseDropCollationPlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("operator")) return .{ .type_system_catalog = .{ .operator = .{ .drop = try parseDropOperatorPlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("aggregate")) return .{ .type_system_catalog = .{ .aggregate = .{ .drop = try parseDropAggregatePlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("cast")) return .{ .type_system_catalog = .{ .cast = .{ .drop = try parseDropCastPlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("function") or cursor.peekKeyword("procedure")) return .{ .function_catalog = .{ .drop = try parseDropRoutinePlanTailAlloc(alloc, tokens, pos) } };
        if (isRoleAliasKeywordAt(tokens, pos.*)) return .{ .authorization_catalog = .{ .drop_role = try parseDropRolePlanTailAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("policy")) return .{ .row_security_catalog = .{ .drop_policy = try parseDropRowSecurityPolicyPlanTailAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("table")) return .{ .drop_table = try parseDropTablePlanTailAlloc(alloc, tokens, pos) };
        if (cursor.peekKeyword("trigger")) return try parseDropTriggerLegacyDdlPlanTailAlloc(alloc, tokens, pos);
        return .{ .drop_index = try parseDropIndexPlanTailAlloc(alloc, tokens, pos) };
    }
    if (cursor.matchKeyword("refresh")) {
        return .{ .materialized_view_catalog = .{ .refresh = try parseRefreshMaterializedViewPlanTailAlloc(alloc, tokens, pos) } };
    }
    if (cursor.matchKeyword("listen")) {
        return .{ .notification_channel = .{ .listen = try parseListenNotificationPlanTailAlloc(alloc, tokens, pos) } };
    }
    if (cursor.matchKeyword("notify")) {
        return .{ .notification_channel = .{ .notify = try parseNotifyNotificationPlanTailAlloc(alloc, tokens, pos) } };
    }
    if (cursor.matchKeyword("unlisten")) {
        return .{ .notification_channel = .{ .unlisten = try parseUnlistenNotificationPlanTailAlloc(alloc, tokens, pos) } };
    }
    if (cursor.matchKeyword("vacuum")) {
        return .{ .maintenance_job = .{ .vacuum = try parseVacuumMaintenancePlanTailAlloc(alloc, tokens, pos) } };
    }
    if (cursor.matchKeyword("analyze")) {
        return .{ .maintenance_job = .{ .analyze = try parseAnalyzeMaintenancePlanTailAlloc(alloc, tokens, pos) } };
    }
    if (cursor.matchKeyword("reindex")) {
        return .{ .maintenance_job = .{ .reindex = try parseReindexMaintenancePlanTailAlloc(alloc, tokens, pos) } };
    }
    if (cursor.matchKeyword("cluster")) {
        return .{ .maintenance_job = .{ .cluster = try parseClusterMaintenancePlanTailAlloc(alloc, tokens, pos) } };
    }
    if (cursor.matchKeyword("copy")) {
        return .{ .bulk_io = try parseBulkIoPlanTailAlloc(
            alloc,
            tokens,
            pos,
            options.schema,
            options.field_expression_qualifiers,
            options.returning_expression_qualifiers,
            options.defer_row_expression_field_validation,
        ) };
    }
    if (cursor.matchKeyword("prepare")) {
        if (cursor.peekKeyword("transaction")) {
            return .{ .prepared_transaction = try grammar.parsePreparedTransactionTailAlloc(alloc, tokens, pos, .prepare) };
        }
        return .{ .prepared_statement = .{ .prepare = try parsePrepareStatementPlanTailAlloc(alloc, tokens, pos) } };
    }
    if (cursor.matchKeyword("execute")) {
        return .{ .prepared_statement = .{ .execute = try parseExecutePreparedStatementPlanTailAlloc(alloc, tokens, pos) } };
    }
    if (cursor.matchKeyword("deallocate")) {
        return .{ .prepared_statement = .{ .deallocate = try parseDeallocatePreparedStatementPlanTailAlloc(alloc, tokens, pos) } };
    }
    if (cursor.matchKeyword("declare")) {
        return .{ .cursor_portal = .{ .declare = try parseDeclareCursorPortalPlanTailAlloc(alloc, tokens, pos) } };
    }
    if (cursor.matchKeyword("fetch")) {
        return .{ .cursor_portal = .{ .fetch = try parseFetchCursorPortalPlanTailAlloc(alloc, tokens, pos) } };
    }
    if (cursor.matchKeyword("move")) {
        return .{ .cursor_portal = .{ .move = try parseFetchCursorPortalPlanTailAlloc(alloc, tokens, pos) } };
    }
    if (cursor.matchKeyword("close")) {
        return .{ .cursor_portal = .{ .close = try parseCloseCursorPortalPlanTailAlloc(alloc, tokens, pos) } };
    }
    if (cursor.matchKeyword("savepoint")) {
        return .{ .savepoint_transaction = .{ .savepoint = try parseSavepointTransactionPlanTailAlloc(alloc, tokens, pos) } };
    }
    if (cursor.matchKeyword("release")) {
        return .{ .savepoint_transaction = .{ .release = try parseReleaseSavepointPlanTailAlloc(alloc, tokens, pos) } };
    }
    if (cursor.matchKeyword("rollback")) {
        if (cursor.peekKeyword("prepared")) {
            return .{ .prepared_transaction = try grammar.parsePreparedTransactionTailAlloc(alloc, tokens, pos, .rollback) };
        }
        if (!cursor.peekKeyword("to") and !cursor.peekKeyword("savepoint")) {
            if (!try grammar.matchAdapterNoopTransactionBoundaryTail(tokens, pos, .{ .work = true, .transaction = true })) return error.UnsupportedSqlShape;
            return .{ .adapter_noop = .{ .reason = .transaction_control } };
        }
        return .{ .savepoint_transaction = .{ .rollback_to = try parseRollbackToSavepointPlanTailAlloc(alloc, tokens, pos) } };
    }
    if (cursor.matchKeyword("commit")) {
        if (cursor.peekKeyword("prepared")) {
            return .{ .prepared_transaction = try grammar.parsePreparedTransactionTailAlloc(alloc, tokens, pos, .commit) };
        }
        if (!try grammar.matchAdapterNoopTransactionBoundaryTail(tokens, pos, .{ .work = true, .transaction = true })) return error.UnsupportedSqlShape;
        return .{ .adapter_noop = .{ .reason = .transaction_control } };
    }
    if (cursor.matchKeyword("comment")) {
        return .{ .comment_metadata = try parseCommentMetadataPlanTailAlloc(alloc, tokens, pos) };
    }
    if (cursor.matchKeyword("grant")) {
        return .{ .authorization_catalog = .{ .grant_privilege = try parsePrivilegeChangePlanTailAlloc(alloc, tokens, pos, .grant) } };
    }
    if (cursor.matchKeyword("revoke")) {
        return .{ .authorization_catalog = .{ .revoke_privilege = try parsePrivilegeChangePlanTailAlloc(alloc, tokens, pos, .revoke) } };
    }
    if (cursor.matchKeyword("lock")) {
        return .{ .transaction_control = .{ .table_lock = try parseTableLockPlanTailAlloc(alloc, tokens, pos) } };
    }
    if (cursor.matchKeyword("set")) {
        if (cursor.peekKeyword("constraints")) return .{ .transaction_control = .{ .constraint_mode = try parseConstraintModePlanTailAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("transaction")) return .{ .transaction_control = .{ .transaction_mode = try parseTransactionModePlanTail(tokens, pos, .set_transaction) } };
        if (cursor.peekKeyword("session")) {
            const checkpoint = pos.*;
            if (parseSetSessionCharacteristicsPlanTailAlloc(alloc, tokens, pos)) |plan| {
                return .{ .session_catalog = .{ .set_setting = plan } };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => pos.* = checkpoint,
                else => return err,
            }
        }
        if (cursor.peekKeyword("local") or cursor.peekKeyword("session") or cursor.peekKeyword("search_path")) {
            const checkpoint = pos.*;
            if (parseSetSearchPathPlanTailAlloc(alloc, tokens, pos)) |plan| {
                return .{ .session_catalog = .{ .set_search_path = plan } };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => pos.* = checkpoint,
                else => return err,
            }
        }
        {
            const checkpoint = pos.*;
            if (grammar.parseSetSessionSettingTailAlloc(alloc, tokens, pos)) |plan| {
                return .{ .session_catalog = .{ .set_setting = plan } };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => pos.* = checkpoint,
                else => return err,
            }
        }
        try grammar.parseAdapterNoopSetStatementTail(tokens, pos);
        return .{ .adapter_noop = .{ .reason = .session_setting } };
    }
    if (cursor.matchKeyword("reset")) {
        if (cursor.peekKeyword("search_path")) {
            try grammar.parseResetSearchPathTail(tokens, pos);
            return .{ .session_catalog = .reset_search_path };
        }
        if (cursor.peekKeyword("all")) {
            try grammar.parseAdapterNoopResetStatementTail(tokens, pos);
            return .{ .session_catalog = .discard_all };
        }
        {
            const checkpoint = pos.*;
            if (grammar.parseResetSessionSettingTailAlloc(alloc, tokens, pos)) |plan| {
                return .{ .session_catalog = .{ .reset_setting = plan } };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => pos.* = checkpoint,
                else => return err,
            }
        }
        try grammar.parseAdapterNoopResetStatementTail(tokens, pos);
        return .{ .adapter_noop = .{ .reason = .session_setting } };
    }
    if (cursor.matchKeyword("show")) {
        if (cursor.peekKeyword("search_path")) {
            try grammar.parseShowSearchPathTail(tokens, pos);
            return .{ .session_catalog = .show_search_path };
        }
        try grammar.parseAdapterNoopShowStatementTail(tokens, pos);
        return .{ .adapter_noop = .{ .reason = .session_setting } };
    }
    if (cursor.matchKeyword("discard")) {
        try grammar.parseDiscardAllTail(tokens, pos);
        return .{ .session_catalog = .discard_all };
    }
    if (cursor.matchKeyword("start")) {
        const checkpoint = pos.*;
        if (cursor.matchKeyword("transaction") and try grammar.matchAdapterNoopTransactionBoundaryTail(tokens, pos, .{})) {
            return .{ .adapter_noop = .{ .reason = .transaction_control } };
        }
        pos.* = checkpoint;
        return .{ .transaction_control = .{ .transaction_mode = try parseTransactionModePlanTail(tokens, pos, .start_transaction) } };
    }
    if (cursor.matchKeyword("begin")) {
        if (try grammar.matchAdapterNoopTransactionBoundaryTail(tokens, pos, .{ .work = true, .transaction = true })) {
            return .{ .adapter_noop = .{ .reason = .transaction_control } };
        }
        return .{ .transaction_control = .{ .transaction_mode = try parseTransactionModePlanTail(tokens, pos, .begin) } };
    }
    if (cursor.matchKeyword("select")) {
        return .{ .transaction_control = .{ .advisory_lock = try parseAdvisoryLockPlanTail(tokens, pos) } };
    }
    return error.UnsupportedSqlShape;
}

pub fn parseLogicalDdlPlanTokensAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    options: DdlPlanParserOptions,
) !binder.LogicalSqlPlan {
    const cursor = parser.Cursor.init(tokens, pos);
    if (cursor.matchKeyword("call")) return .{ .routine = .{ .procedure_call = try parseProcedureCallPlanTailAlloc(alloc, tokens, pos) } };
    if (cursor.matchKeyword("create")) {
        if (cursor.matchKeyword("or")) {
            try cursor.expectKeyword("replace");
            if (cursor.peekKeyword("trigger")) return try parseCreateTriggerLogicalDdlPlanTailAlloc(alloc, tokens, pos, true);
            if (cursor.peekKeyword("materialized")) return .{ .table_ddl = .{ .materialized_view_catalog = .{ .create = try parseCreateMaterializedViewPlanTailAlloc(alloc, tokens, pos, true) } } };
            if (cursor.peekKeyword("view")) return .{ .table_ddl = .{ .view_catalog = .{ .create = try parseCreateViewPlanTailAlloc(alloc, tokens, pos, true) } } };
            if (cursor.peekKeyword("function") or cursor.peekKeyword("procedure")) return .{ .routine = .{ .function_catalog = .{ .create = try parseCreateRoutinePlanTailAlloc(alloc, tokens, pos, true) } } };
            if (!cursor.peekKeyword("table")) return error.UnsupportedSqlShape;
            var create_table = try parseCreateTablePlanAlloc(alloc, tokens, pos, options.column_definition_options);
            create_table.replace_existing = true;
            return .{ .table_ddl = .{ .create_table = create_table } };
        }
        const unique = cursor.matchKeyword("unique");
        if (cursor.peekKeyword("index")) return .{ .table_ddl = .{ .create_index = try parseCreateIndexPlanAlloc(alloc, tokens, pos, unique, options.create_index_options) } };
        if (cursor.peekKeyword("graph")) {
            if (unique) return error.UnsupportedSqlShape;
            if (pos.* + 1 < tokens.len and tokens[pos.* + 1].matchesKeyword("metric")) {
                return .{ .table_ddl = .{ .create_index = try parseCreateGraphMetricPlanAlloc(alloc, tokens, pos) } };
            }
            return .{ .table_ddl = .{ .create_index = try parseCreateGraphIndexPlanAlloc(alloc, tokens, pos) } };
        }
        if (unique) return error.UnsupportedSqlShape;
        if (cursor.peekKeyword("trigger")) return try parseCreateTriggerLogicalDdlPlanTailAlloc(alloc, tokens, pos, false);
        if (cursor.peekKeyword("materialized")) return .{ .table_ddl = .{ .materialized_view_catalog = .{ .create = try parseCreateMaterializedViewPlanTailAlloc(alloc, tokens, pos, false) } } };
        if (cursor.peekKeyword("view")) return .{ .table_ddl = .{ .view_catalog = .{ .create = try parseCreateViewPlanTailAlloc(alloc, tokens, pos, false) } } };
        if (cursor.peekKeyword("domain")) return .{ .catalog_ddl = .{ .domain_catalog = .{ .create = try parseCreateDomainPlanAlloc(alloc, tokens, pos, options.domain_options) } } };
        if (cursor.peekKeyword("sequence")) return .{ .catalog_ddl = .{ .sequence_catalog = .{ .create = try parseCreateSequencePlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("type")) return .{ .catalog_ddl = .{ .enum_type_catalog = .{ .create = try parseCreateEnumTypePlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("schema")) {
            var create_schema = try parseCreateSchemaNamespacePlanTailAlloc(alloc, tokens, pos);
            if (create_schema.if_not_exists and std.ascii.eqlIgnoreCase(create_schema.schema_name, "public")) {
                create_schema.deinit(alloc);
                return .{ .other_ddl = .{ .adapter_noop = .{ .reason = .schema_namespace } } };
            }
            return .{ .catalog_ddl = .{ .schema_namespace_catalog = .{ .create = create_schema } } };
        }
        if (cursor.peekKeyword("extension")) {
            var create_extension = try parseCreateExtensionPlanTailAlloc(alloc, tokens, pos, catalog_resources.default_namespace_name);
            if (create_extension.if_not_exists and isAdapterNoopExtensionName(create_extension.extension_name)) {
                create_extension.deinit(alloc);
                return .{ .other_ddl = .{ .adapter_noop = .{ .reason = .extension } } };
            }
            return .{ .extension = .{ .create = create_extension } };
        }
        if (cursor.peekKeyword("function") or cursor.peekKeyword("procedure")) return .{ .routine = .{ .function_catalog = .{ .create = try parseCreateRoutinePlanTailAlloc(alloc, tokens, pos, false) } } };
        if (isRoleAliasKeywordAt(tokens, pos.*)) return .{ .auth = .{ .authorization_catalog = .{ .create_role = try parseCreateRolePlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("policy")) return .{ .auth = .{ .row_security_catalog = .{ .create_policy = try parseCreateRowSecurityPolicyPlanTailAllocWithOptions(alloc, tokens, pos, options.row_security_policy_options) } } };
        if (cursor.peekKeyword("database")) return .{ .catalog_ddl = .{ .database_catalog = .{ .create = try parseCreateDatabasePlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("tablespace")) return .{ .catalog_ddl = .{ .tablespace_catalog = .{ .create = try parseCreateTablespacePlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("publication")) return .{ .catalog_ddl = .{ .logical_replication = .{ .publication = .{ .create = try parseCreatePublicationPlanTailAlloc(alloc, tokens, pos) } } } };
        if (cursor.peekKeyword("subscription")) return .{ .catalog_ddl = .{ .logical_replication = .{ .subscription = .{ .create = try parseCreateSubscriptionPlanTailAlloc(alloc, tokens, pos) } } } };
        if (cursor.peekKeyword("collation")) return .{ .catalog_ddl = .{ .type_system_catalog = .{ .collation = .{ .create = try parseCreateCollationPlanTailAlloc(alloc, tokens, pos) } } } };
        if (cursor.peekKeyword("operator")) return .{ .catalog_ddl = .{ .type_system_catalog = .{ .operator = .{ .create = try parseCreateOperatorPlanTailAlloc(alloc, tokens, pos) } } } };
        if (cursor.peekKeyword("aggregate")) return .{ .catalog_ddl = .{ .type_system_catalog = .{ .aggregate = .{ .create = try parseCreateAggregatePlanTailAlloc(alloc, tokens, pos) } } } };
        if (cursor.peekKeyword("cast")) return .{ .catalog_ddl = .{ .type_system_catalog = .{ .cast = .{ .create = try parseCreateCastPlanTailAlloc(alloc, tokens, pos) } } } };
        if (cursor.peekKeyword("temporary") or cursor.peekKeyword("temp") or cursor.peekKeyword("unlogged")) {
            return .{ .table_ddl = .{ .relation_lifetime = try parseRelationLifetimePlanAlloc(alloc, tokens, pos, options.column_definition_options) } };
        }
        const checkpoint = pos.*;
        if (parseIdentityAllocatorPlanAlloc(alloc, tokens, pos, options.column_definition_options)) |identity| {
            return .{ .catalog_ddl = .{ .identity_allocator_catalog = identity } };
        } else |err| switch (err) {
            error.UnsupportedSqlShape => pos.* = checkpoint,
            else => return err,
        }
        if (parseCreateTablePartitionPlanTailAlloc(alloc, tokens, pos)) |partition| {
            return .{ .table_ddl = .{ .table_partition_catalog = .{ .create_partition = partition } } };
        } else |err| switch (err) {
            error.UnsupportedSqlShape => pos.* = checkpoint,
            else => return err,
        }
        if (parseCreatePartitionedTablePlanAlloc(alloc, tokens, pos, options.column_definition_options)) |partitioned| {
            return .{ .table_ddl = .{ .table_partition_catalog = .{ .create_partitioned = partitioned } } };
        } else |err| switch (err) {
            error.UnsupportedSqlShape => pos.* = checkpoint,
            else => return err,
        }
        if (parseCreateTableClonePlanTailAlloc(alloc, tokens, pos)) |table_clone| {
            return .{ .table_ddl = .{ .table_clone = table_clone } };
        } else |err| switch (err) {
            error.UnsupportedSqlShape => pos.* = checkpoint,
            else => return err,
        }
        return .{ .table_ddl = .{ .create_table = try parseCreateTablePlanAlloc(alloc, tokens, pos, options.column_definition_options) } };
    }
    if (cursor.matchKeyword("alter")) {
        if (cursor.peekKeyword("graph")) return .{ .table_ddl = .{ .create_index = try parseAlterGraphIndexAddMetricPlanAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("domain")) return .{ .catalog_ddl = .{ .domain_catalog = .{ .alter = try parseAlterDomainPlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("sequence")) return .{ .catalog_ddl = .{ .sequence_catalog = .{ .alter = try parseAlterSequencePlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("type")) return .{ .catalog_ddl = .{ .enum_type_catalog = .{ .add_value = try parseAlterEnumTypePlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("extension")) return .{ .extension = .{ .update = try parseUpdateExtensionPlanTailAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("schema")) return .{ .catalog_ddl = .{ .schema_namespace_catalog = .{ .rename = try parseRenameSchemaNamespacePlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("database")) return .{ .catalog_ddl = .{ .database_catalog = .{ .alter = try parseAlterDatabasePlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("tablespace")) return .{ .catalog_ddl = .{ .tablespace_catalog = .{ .rename = try parseRenameTablespacePlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("publication")) return .{ .catalog_ddl = .{ .logical_replication = .{ .publication = .{ .alter = try parseAlterPublicationPlanTailAlloc(alloc, tokens, pos) } } } };
        if (cursor.peekKeyword("subscription")) return .{ .catalog_ddl = .{ .logical_replication = .{ .subscription = .{ .alter = try parseAlterSubscriptionPlanTailAlloc(alloc, tokens, pos) } } } };
        if (cursor.peekKeyword("collation")) return .{ .catalog_ddl = .{ .type_system_catalog = .{ .collation = .{ .rename = try parseRenameCollationPlanTailAlloc(alloc, tokens, pos) } } } };
        if (cursor.peekKeyword("view")) return .{ .table_ddl = .{ .view_catalog = .{ .rename = try parseRenameViewPlanTailAlloc(alloc, tokens, pos) } } };
        if (isRoleAliasKeywordAt(tokens, pos.*)) return .{ .auth = .{ .authorization_catalog = .{ .alter_role = try parseAlterRolePlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("policy")) return .{ .auth = .{ .row_security_catalog = .{ .alter_policy = try parseAlterRowSecurityPolicyPlanTailAllocWithOptions(alloc, tokens, pos, options.row_security_policy_options) } } };
        if (cursor.peekKeyword("table")) {
            const checkpoint = pos.*;
            if (parseAlterRowSecurityPlanTailAlloc(alloc, tokens, pos)) |row_security| {
                return .{ .auth = .{ .row_security_catalog = .{ .alter_table = row_security } } };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => pos.* = checkpoint,
                else => return err,
            }
        }
        if (cursor.peekKeyword("table")) {
            const checkpoint = pos.*;
            if (parseAlterTablePartitionPlanTailAlloc(alloc, tokens, pos)) |partition| {
                return .{ .table_ddl = .{ .table_partition_catalog = partition } };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => pos.* = checkpoint,
                else => return err,
            }
        }
        return .{ .table_ddl = .{ .alter_table = try parseAlterTablePlanAlloc(alloc, tokens, pos, options.column_definition_options) } };
    }
    if (cursor.matchKeyword("drop")) {
        if (cursor.peekKeyword("materialized")) return .{ .table_ddl = .{ .materialized_view_catalog = .{ .drop = try parseDropMaterializedViewPlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("view")) return .{ .table_ddl = .{ .view_catalog = .{ .drop = try parseDropViewPlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("domain")) return .{ .catalog_ddl = .{ .domain_catalog = .{ .drop = try parseDropDomainPlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("sequence")) return .{ .catalog_ddl = .{ .sequence_catalog = .{ .drop = try parseDropSequencePlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("type")) return .{ .catalog_ddl = .{ .enum_type_catalog = .{ .drop = try parseDropEnumTypePlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("schema")) return .{ .catalog_ddl = .{ .schema_namespace_catalog = .{ .drop = try parseDropSchemaNamespacePlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("extension")) return .{ .extension = .{ .drop = try parseDropExtensionPlanTailAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("database")) return .{ .catalog_ddl = .{ .database_catalog = .{ .drop = try parseDropDatabasePlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("tablespace")) return .{ .catalog_ddl = .{ .tablespace_catalog = .{ .drop = try parseDropTablespacePlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("publication")) return .{ .catalog_ddl = .{ .logical_replication = .{ .publication = .{ .drop = try parseDropPublicationPlanTailAlloc(alloc, tokens, pos) } } } };
        if (cursor.peekKeyword("subscription")) return .{ .catalog_ddl = .{ .logical_replication = .{ .subscription = .{ .drop = try parseDropSubscriptionPlanTailAlloc(alloc, tokens, pos) } } } };
        if (cursor.peekKeyword("collation")) return .{ .catalog_ddl = .{ .type_system_catalog = .{ .collation = .{ .drop = try parseDropCollationPlanTailAlloc(alloc, tokens, pos) } } } };
        if (cursor.peekKeyword("operator")) return .{ .catalog_ddl = .{ .type_system_catalog = .{ .operator = .{ .drop = try parseDropOperatorPlanTailAlloc(alloc, tokens, pos) } } } };
        if (cursor.peekKeyword("aggregate")) return .{ .catalog_ddl = .{ .type_system_catalog = .{ .aggregate = .{ .drop = try parseDropAggregatePlanTailAlloc(alloc, tokens, pos) } } } };
        if (cursor.peekKeyword("cast")) return .{ .catalog_ddl = .{ .type_system_catalog = .{ .cast = .{ .drop = try parseDropCastPlanTailAlloc(alloc, tokens, pos) } } } };
        if (cursor.peekKeyword("function") or cursor.peekKeyword("procedure")) return .{ .routine = .{ .function_catalog = .{ .drop = try parseDropRoutinePlanTailAlloc(alloc, tokens, pos) } } };
        if (isRoleAliasKeywordAt(tokens, pos.*)) return .{ .auth = .{ .authorization_catalog = .{ .drop_role = try parseDropRolePlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("policy")) return .{ .auth = .{ .row_security_catalog = .{ .drop_policy = try parseDropRowSecurityPolicyPlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("table")) return .{ .table_ddl = .{ .drop_table = try parseDropTablePlanTailAlloc(alloc, tokens, pos) } };
        if (cursor.peekKeyword("trigger")) return try parseDropTriggerLogicalDdlPlanTailAlloc(alloc, tokens, pos);
        return .{ .table_ddl = .{ .drop_index = try parseDropIndexPlanTailAlloc(alloc, tokens, pos) } };
    }
    if (cursor.matchKeyword("refresh")) return .{ .table_ddl = .{ .materialized_view_catalog = .{ .refresh = try parseRefreshMaterializedViewPlanTailAlloc(alloc, tokens, pos) } } };
    if (cursor.matchKeyword("listen")) return .{ .notification = .{ .listen = try parseListenNotificationPlanTailAlloc(alloc, tokens, pos) } };
    if (cursor.matchKeyword("notify")) return .{ .notification = .{ .notify = try parseNotifyNotificationPlanTailAlloc(alloc, tokens, pos) } };
    if (cursor.matchKeyword("unlisten")) return .{ .notification = .{ .unlisten = try parseUnlistenNotificationPlanTailAlloc(alloc, tokens, pos) } };
    if (cursor.matchKeyword("vacuum")) return .{ .maintenance = .{ .vacuum = try parseVacuumMaintenancePlanTailAlloc(alloc, tokens, pos) } };
    if (cursor.matchKeyword("analyze")) return .{ .maintenance = .{ .analyze = try parseAnalyzeMaintenancePlanTailAlloc(alloc, tokens, pos) } };
    if (cursor.matchKeyword("reindex")) return .{ .maintenance = .{ .reindex = try parseReindexMaintenancePlanTailAlloc(alloc, tokens, pos) } };
    if (cursor.matchKeyword("cluster")) return .{ .maintenance = .{ .cluster = try parseClusterMaintenancePlanTailAlloc(alloc, tokens, pos) } };
    if (cursor.matchKeyword("copy")) {
        return .{ .bulk_io = try parseBulkIoPlanTailAlloc(
            alloc,
            tokens,
            pos,
            options.schema,
            options.field_expression_qualifiers,
            options.returning_expression_qualifiers,
            options.defer_row_expression_field_validation,
        ) };
    }
    if (cursor.matchKeyword("prepare")) {
        if (cursor.peekKeyword("transaction")) return .{ .transaction = .{ .prepared = try grammar.parsePreparedTransactionTailAlloc(alloc, tokens, pos, .prepare) } };
        return .{ .prepared_statement = .{ .prepare = try parsePrepareStatementPlanTailAlloc(alloc, tokens, pos) } };
    }
    if (cursor.matchKeyword("execute")) return .{ .prepared_statement = .{ .execute = try parseExecutePreparedStatementPlanTailAlloc(alloc, tokens, pos) } };
    if (cursor.matchKeyword("deallocate")) return .{ .prepared_statement = .{ .deallocate = try parseDeallocatePreparedStatementPlanTailAlloc(alloc, tokens, pos) } };
    if (cursor.matchKeyword("declare")) return .{ .cursor = .{ .declare = try parseDeclareCursorPortalPlanTailAlloc(alloc, tokens, pos) } };
    if (cursor.matchKeyword("fetch")) return .{ .cursor = .{ .fetch = try parseFetchCursorPortalPlanTailAlloc(alloc, tokens, pos) } };
    if (cursor.matchKeyword("move")) return .{ .cursor = .{ .move = try parseFetchCursorPortalPlanTailAlloc(alloc, tokens, pos) } };
    if (cursor.matchKeyword("close")) return .{ .cursor = .{ .close = try parseCloseCursorPortalPlanTailAlloc(alloc, tokens, pos) } };
    if (cursor.matchKeyword("savepoint")) return .{ .transaction = .{ .savepoint = .{ .savepoint = try parseSavepointTransactionPlanTailAlloc(alloc, tokens, pos) } } };
    if (cursor.matchKeyword("release")) return .{ .transaction = .{ .savepoint = .{ .release = try parseReleaseSavepointPlanTailAlloc(alloc, tokens, pos) } } };
    if (cursor.matchKeyword("rollback")) {
        if (cursor.peekKeyword("prepared")) return .{ .transaction = .{ .prepared = try grammar.parsePreparedTransactionTailAlloc(alloc, tokens, pos, .rollback) } };
        if (!cursor.peekKeyword("to") and !cursor.peekKeyword("savepoint")) {
            if (!try grammar.matchAdapterNoopTransactionBoundaryTail(tokens, pos, .{ .work = true, .transaction = true })) return error.UnsupportedSqlShape;
            return .{ .other_ddl = .{ .adapter_noop = .{ .reason = .transaction_control } } };
        }
        return .{ .transaction = .{ .savepoint = .{ .rollback_to = try parseRollbackToSavepointPlanTailAlloc(alloc, tokens, pos) } } };
    }
    if (cursor.matchKeyword("commit")) {
        if (cursor.peekKeyword("prepared")) return .{ .transaction = .{ .prepared = try grammar.parsePreparedTransactionTailAlloc(alloc, tokens, pos, .commit) } };
        if (!try grammar.matchAdapterNoopTransactionBoundaryTail(tokens, pos, .{ .work = true, .transaction = true })) return error.UnsupportedSqlShape;
        return .{ .other_ddl = .{ .adapter_noop = .{ .reason = .transaction_control } } };
    }
    if (cursor.matchKeyword("comment")) return .{ .catalog_ddl = .{ .comment_metadata = try parseCommentMetadataPlanTailAlloc(alloc, tokens, pos) } };
    if (cursor.matchKeyword("grant")) return .{ .auth = .{ .authorization_catalog = .{ .grant_privilege = try parsePrivilegeChangePlanTailAlloc(alloc, tokens, pos, .grant) } } };
    if (cursor.matchKeyword("revoke")) return .{ .auth = .{ .authorization_catalog = .{ .revoke_privilege = try parsePrivilegeChangePlanTailAlloc(alloc, tokens, pos, .revoke) } } };
    if (cursor.matchKeyword("lock")) return .{ .transaction = .{ .control = .{ .table_lock = try parseTableLockPlanTailAlloc(alloc, tokens, pos) } } };
    if (cursor.matchKeyword("set")) {
        if (cursor.peekKeyword("constraints")) return .{ .transaction = .{ .control = .{ .constraint_mode = try parseConstraintModePlanTailAlloc(alloc, tokens, pos) } } };
        if (cursor.peekKeyword("transaction")) return .{ .transaction = .{ .control = .{ .transaction_mode = try parseTransactionModePlanTail(tokens, pos, .set_transaction) } } };
        if (cursor.peekKeyword("session")) {
            const checkpoint = pos.*;
            if (parseSetSessionCharacteristicsPlanTailAlloc(alloc, tokens, pos)) |plan| {
                return .{ .session = .{ .set_setting = plan } };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => pos.* = checkpoint,
                else => return err,
            }
        }
        if (cursor.peekKeyword("local") or cursor.peekKeyword("session") or cursor.peekKeyword("search_path")) {
            const checkpoint = pos.*;
            if (parseSetSearchPathPlanTailAlloc(alloc, tokens, pos)) |plan| {
                return .{ .session = .{ .set_search_path = plan } };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => pos.* = checkpoint,
                else => return err,
            }
        }
        {
            const checkpoint = pos.*;
            if (grammar.parseSetSessionSettingTailAlloc(alloc, tokens, pos)) |plan| {
                return .{ .session = .{ .set_setting = plan } };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => pos.* = checkpoint,
                else => return err,
            }
        }
        try grammar.parseAdapterNoopSetStatementTail(tokens, pos);
        return .{ .other_ddl = .{ .adapter_noop = .{ .reason = .session_setting } } };
    }
    if (cursor.matchKeyword("reset")) {
        if (cursor.peekKeyword("search_path")) {
            try grammar.parseResetSearchPathTail(tokens, pos);
            return .{ .session = .reset_search_path };
        }
        if (cursor.peekKeyword("all")) {
            try grammar.parseAdapterNoopResetStatementTail(tokens, pos);
            return .{ .session = .discard_all };
        }
        {
            const checkpoint = pos.*;
            if (grammar.parseResetSessionSettingTailAlloc(alloc, tokens, pos)) |plan| {
                return .{ .session = .{ .reset_setting = plan } };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => pos.* = checkpoint,
                else => return err,
            }
        }
        try grammar.parseAdapterNoopResetStatementTail(tokens, pos);
        return .{ .other_ddl = .{ .adapter_noop = .{ .reason = .session_setting } } };
    }
    if (cursor.matchKeyword("show")) {
        if (cursor.peekKeyword("search_path")) {
            try grammar.parseShowSearchPathTail(tokens, pos);
            return .{ .session = .show_search_path };
        }
        try grammar.parseAdapterNoopShowStatementTail(tokens, pos);
        return .{ .other_ddl = .{ .adapter_noop = .{ .reason = .session_setting } } };
    }
    if (cursor.matchKeyword("discard")) {
        try grammar.parseDiscardAllTail(tokens, pos);
        return .{ .session = .discard_all };
    }
    if (cursor.matchKeyword("start")) {
        const checkpoint = pos.*;
        if (cursor.matchKeyword("transaction") and try grammar.matchAdapterNoopTransactionBoundaryTail(tokens, pos, .{})) {
            return .{ .other_ddl = .{ .adapter_noop = .{ .reason = .transaction_control } } };
        }
        pos.* = checkpoint;
        return .{ .transaction = .{ .control = .{ .transaction_mode = try parseTransactionModePlanTail(tokens, pos, .start_transaction) } } };
    }
    if (cursor.matchKeyword("begin")) {
        if (try grammar.matchAdapterNoopTransactionBoundaryTail(tokens, pos, .{ .work = true, .transaction = true })) {
            return .{ .other_ddl = .{ .adapter_noop = .{ .reason = .transaction_control } } };
        }
        return .{ .transaction = .{ .control = .{ .transaction_mode = try parseTransactionModePlanTail(tokens, pos, .begin) } } };
    }
    if (cursor.matchKeyword("select")) return .{ .transaction = .{ .control = .{ .advisory_lock = try parseAdvisoryLockPlanTail(tokens, pos) } } };
    return error.UnsupportedSqlShape;
}

