        switch (self.*) {
            .create_partitioned => |*plan| plan.deinit(alloc),
            .create_partition => |*plan| plan.deinit(alloc),
            .attach => |*plan| plan.deinit(alloc),
            .detach => |*plan| plan.deinit(alloc),
