pub fn savepointNamePlanFromSyntaxAlloc(alloc: std.mem.Allocator, syntax: grammar.SavepointNameSyntax) !SavepointNamePlan {
    return .{ .savepoint_name = try alloc.dupe(u8, syntax.savepoint_name) };
}

pub fn deallocatePreparedStatementPlanFromSyntaxAlloc(
    alloc: std.mem.Allocator,
    syntax: grammar.NamedOrAllSyntax,
) !DeallocatePreparedStatementPlan {
    if (syntax.all) return .{ .all = true };
    const statement_name = syntax.name orelse return error.UnsupportedSqlShape;
    return .{ .statement_name = try alloc.dupe(u8, statement_name) };
}

pub fn preparedTransactionPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlPreparedTransactionAst,
) !PreparedTransactionPlan {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    if (end != 3 or tokens.len < end) return error.UnsupportedSqlShape;
    if (tokens[0].source_start != ast.command_span.start or tokens[0].source_end != ast.command_span.end) {
        return error.UnsupportedSqlShape;
    }
    const second_expected = switch (ast.kind) {
        .prepare => "transaction",
        .commit, .rollback => "prepared",
    };
    const action: PreparedTransactionAction = switch (ast.kind) {
        .prepare => .prepare,
        .commit => .commit,
        .rollback => .rollback,
    };
    switch (ast.kind) {
        .prepare => if (!tokens[0].matchesKeywordTag(.prepare)) return error.UnsupportedSqlShape,
        .commit => if (!tokens[0].matchesKeywordTag(.commit)) return error.UnsupportedSqlShape,
        .rollback => if (!tokens[0].matchesKeywordTag(.rollback)) return error.UnsupportedSqlShape,
    }
    if (!tokens[1].matchesKeyword(second_expected)) return error.UnsupportedSqlShape;
    const gid_tokens = ast.gid_tokens orelse return error.UnsupportedSqlShape;
    if (gid_tokens.start != 2 or gid_tokens.end != 3) return error.UnsupportedSqlShape;
    if (tokens[2].kind != .string or tokens[2].text.len == 0) return error.UnsupportedSqlShape;
    var pos: usize = 0;
    return try grammar.parsePreparedTransactionTailAlloc(alloc, tokens[1..end], &pos, action);
}

pub fn preparedStatementPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    ast: generated_parser.GeneratedSqlPreparedAst,
) !PreparedStatementPlan {
    const tokens = parsed_sql.items();
    try validateGeneratedPreparedAstRanges(tokens, ast);
    return switch (ast.kind) {
        .prepare => .{ .prepare = try prepareStatementPlanFromGeneratedAstAlloc(alloc, parsed_sql, ast) },
        .execute => .{ .execute = try executePreparedStatementPlanFromGeneratedAstAlloc(alloc, tokens, ast) },
        .deallocate => .{ .deallocate = try deallocatePreparedStatementPlanFromGeneratedAstAlloc(alloc, tokens, ast) },
    };
}

fn validateGeneratedPreparedAstRanges(
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlPreparedAst,
) !void {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    if (tokens[0].source_start != ast.command_span.start or tokens[0].source_end != ast.command_span.end) {
        return error.UnsupportedSqlShape;
    }
    const expected: token_mod.TokenKeyword = switch (ast.kind) {
        .prepare => .prepare,
        .execute => .execute,
        .deallocate => .deallocate,
    };
    if (!tokens[0].matchesKeywordTag(expected)) return error.UnsupportedSqlShape;

    switch (ast.kind) {
        .prepare => {
            try validateGeneratedPreparedRequiredRangeAt(ast.name_tokens, 1, 2, end);
            const inner = ast.inner_statement_tokens orelse return error.UnsupportedSqlShape;
            try validateGeneratedPreparedRange(tokens, inner, 3, end);
            if (inner.start == 0 or !tokens[inner.start - 1].matchesKeywordTag(.as)) return error.UnsupportedSqlShape;
            if (ast.parameter_tokens) |parameter_tokens| {
                if (parameter_tokens.start != 2 or parameter_tokens.end + 1 != inner.start) return error.UnsupportedSqlShape;
                _ = try countGeneratedParenthesizedList(tokens, parameter_tokens);
            } else if (inner.start != 3) {
                return error.UnsupportedSqlShape;
            }
            if (ast.argument_tokens != null) return error.UnsupportedSqlShape;
        },
        .execute => {
            try validateGeneratedPreparedRequiredRangeAt(ast.name_tokens, 1, 2, end);
            if (ast.argument_tokens) |argument_tokens| {
                if (argument_tokens.start != 2 or argument_tokens.end != end) return error.UnsupportedSqlShape;
                _ = try countGeneratedParenthesizedList(tokens, argument_tokens);
            } else if (end != 2) {
                return error.UnsupportedSqlShape;
            }
            if (ast.parameter_tokens != null or ast.inner_statement_tokens != null) return error.UnsupportedSqlShape;
        },
        .deallocate => {
            _ = try generatedDeallocateStatementNameRange(tokens, ast.name_tokens, end);
            if (ast.parameter_tokens != null or ast.argument_tokens != null or ast.inner_statement_tokens != null) return error.UnsupportedSqlShape;
        },
    }
}

fn generatedDeallocateStatementNameRange(
    tokens: []const grammar.Token,
    maybe_range: ?generated_parser.GeneratedSqlTokenRange,
    end: usize,
) !generated_parser.GeneratedSqlTokenRange {
    const range = maybe_range orelse return error.UnsupportedSqlShape;
    if (range.end != end or range.end > tokens.len) return error.UnsupportedSqlShape;
    if (range.start == 1 and range.start + 1 == range.end) return range;
    if (range.start == 2 and range.start + 1 == range.end and tokens.len > 1 and tokens[1].matchesKeywordTag(.prepare)) {
        return range;
    }
    return error.UnsupportedSqlShape;
}

fn validateGeneratedPreparedRange(
    tokens: []const grammar.Token,
    range: generated_parser.GeneratedSqlTokenRange,
    min_start: usize,
    end: usize,
) !void {
    if (range.start < min_start or range.start >= range.end or range.end > end or range.end > tokens.len) return error.UnsupportedSqlShape;
}

fn validateGeneratedPreparedRequiredRangeAt(
    maybe_range: ?generated_parser.GeneratedSqlTokenRange,
    start: usize,
    end: usize,
    statement_end: usize,
) !void {
    const range = maybe_range orelse return error.UnsupportedSqlShape;
    if (range.start != start or range.end != end or range.end > statement_end) return error.UnsupportedSqlShape;
}

pub fn prepareStatementPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    ast: generated_parser.GeneratedSqlPreparedAst,
) !PrepareStatementPlan {
    const tokens = parsed_sql.items();
    const statement_name = try generatedSingleIdentifierText(tokens, ast.name_tokens orelse return error.UnsupportedSqlShape);
    const inner = ast.inner_statement_tokens orelse return error.UnsupportedSqlShape;
    const statement_family = try generatedPreparedStatementFamilyAlloc(alloc, tokens, inner);
    const parameter_count = if (ast.parameter_tokens) |parameter_tokens|
        try countGeneratedParenthesizedList(tokens, parameter_tokens)
    else
        0;
    var plan = PrepareStatementPlan{
        .statement_name = try alloc.dupe(u8, statement_name),
        .parameter_count = parameter_count,
        .statement_kind = preparedStatementSubjectKindFromStatementKind(statement_family),
        .statement_family = statement_family,
    };
    errdefer plan.deinit(alloc);
    plan.subject_parsed_sql = try parsedSqlFromTokenRangeAlloc(alloc, tokens[inner.start..inner.end]);
    return plan;
}

fn generatedPreparedStatementFamilyAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    inner: generated_parser.GeneratedSqlTokenRange,
) !PreparedStatementStatementKind {
    var parsed_inner = try generated_parser.parseTokensAlloc(alloc, tokens[inner.start..inner.end]);
    defer parsed_inner.deinit(alloc);

    return switch (parsed_inner.ast orelse return error.UnsupportedSqlShape) {
        .read => .read,
        .dml => |dml_ast| generatedPreparedStatementFamilyFromDmlKind(dml_ast.kind),
        .ddl => .ddl,
        .extension_index => .ddl,
        else => error.UnsupportedSqlShape,
    };
}

fn generatedPreparedStatementFamilyFromDmlKind(kind: generated_parser.GeneratedSqlDmlKind) PreparedStatementStatementKind {
    return switch (kind) {
        .insert_values => .insert,
        .insert_select => .insert_source,
        .update => .update,
        .delete => .delete,
        .truncate => .truncate,
        .merge => .merge,
    };
}

fn preparedStatementSubjectKindFromStatementKind(kind: PreparedStatementStatementKind) PreparedStatementSubjectKind {
    return switch (kind) {
        .read => .read,
        .insert,
        .insert_source,
        .update,
        .delete,
        .truncate,
        .merge,
        => .write,
        .ddl => .ddl,
    };
}

fn parseExecutePreparedStatementArgumentsAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
) ![]const value_mod.SqlValue {
    if (tokens.len == 0) return &.{};
    var pos: usize = 0;
    if (parser.matchToken(tokens, &pos, .lparen) == null) return error.UnsupportedSqlShape;
    if (parser.matchToken(tokens, &pos, .rparen) != null) {
        if (pos != tokens.len) return error.UnsupportedSqlShape;
        return &.{};
    }
    var values = std.ArrayListUnmanaged(value_mod.SqlValue).empty;
    errdefer {
        for (values.items) |value| value_mod.deinitSqlValue(alloc, value);
        values.deinit(alloc);
    }
    while (true) {
        try values.append(alloc, try value_mod.parseSqlUntypedValueAlloc(alloc, tokens, &pos));
        if (parser.matchToken(tokens, &pos, .comma) != null) continue;
        break;
    }
    _ = parser.matchToken(tokens, &pos, .rparen) orelse return error.UnsupportedSqlShape;
    if (pos != tokens.len) return error.UnsupportedSqlShape;
    return try values.toOwnedSlice(alloc);
}

pub fn executePreparedStatementPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlPreparedAst,
) !ExecutePreparedStatementPlan {
    const statement_name = try generatedSingleIdentifierText(tokens, ast.name_tokens orelse return error.UnsupportedSqlShape);
    const argument_count = if (ast.argument_tokens) |argument_tokens|
        try countGeneratedParenthesizedList(tokens, argument_tokens)
    else
        0;
    var plan = ExecutePreparedStatementPlan{
        .statement_name = try alloc.dupe(u8, statement_name),
        .argument_count = argument_count,
    };
    errdefer plan.deinit(alloc);
    if (ast.argument_tokens) |argument_tokens| {
        plan.arguments = try parseExecutePreparedStatementArgumentsAlloc(alloc, tokens[argument_tokens.start..argument_tokens.end]);
    }
    return plan;
}

pub fn deallocatePreparedStatementPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlPreparedAst,
) !DeallocatePreparedStatementPlan {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    const name_tokens = try generatedDeallocateStatementNameRange(tokens, ast.name_tokens, end);
    if (name_tokens.start + 1 == name_tokens.end and tokens[name_tokens.start].matchesKeywordTag(.all)) {
        return .{ .all = true };
    }
    const statement_name = try generatedSingleIdentifierText(tokens, name_tokens);
    return .{ .statement_name = try alloc.dupe(u8, statement_name) };
}

pub fn cursorPortalPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlCursorAst,
) !LegacyDdlParserPlan {
    const cursor = try cursorPortalLogicalPlanFromGeneratedAstAlloc(alloc, tokens, ast);
    return .{ .cursor_portal = cursor };
}

pub fn cursorPortalLogicalPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlCursorAst,
) !CursorPortalPlan {
    try validateGeneratedCursorAstSpans(tokens, ast);
    const tail = ast.tail_tokens orelse return error.UnsupportedSqlShape;
    var pos: usize = 0;
    var plan: CursorPortalPlan = switch (ast.kind) {
        .declare => .{ .declare = try parseDeclareCursorPortalPlanTailAlloc(alloc, tokens[tail.start..tail.end], &pos) },
        .fetch => .{ .fetch = try parseFetchCursorPortalPlanTailAlloc(alloc, tokens[tail.start..tail.end], &pos) },
        .move => .{ .move = try parseFetchCursorPortalPlanTailAlloc(alloc, tokens[tail.start..tail.end], &pos) },
        .close => .{ .close = try parseCloseCursorPortalPlanTailAlloc(alloc, tokens[tail.start..tail.end], &pos) },
    };
    errdefer plan.deinit(alloc);
    if (pos != tail.end - tail.start) return error.UnsupportedSqlShape;
    return plan;
}

fn validateGeneratedCursorAstSpans(
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlCursorAst,
) !void {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    if (end == 0 or tokens[0].source_start != ast.command_span.start or tokens[0].source_end != ast.command_span.end) {
        return error.UnsupportedSqlShape;
    }
    switch (ast.kind) {
        .declare => if (!tokens[0].matchesKeywordTag(.declare)) return error.UnsupportedSqlShape,
        .fetch => if (!tokens[0].matchesKeywordTag(.fetch)) return error.UnsupportedSqlShape,
        .move => if (!tokens[0].matchesKeywordTag(.move)) return error.UnsupportedSqlShape,
        .close => if (!tokens[0].matchesKeywordTag(.close)) return error.UnsupportedSqlShape,
    }
    const tail = ast.tail_tokens orelse return error.UnsupportedSqlShape;
    if (tail.start != 1 or tail.end != end or tail.start >= tail.end or tail.end > tokens.len) {
        return error.UnsupportedSqlShape;
    }
}

fn generatedSingleIdentifierText(tokens: []const grammar.Token, range: generated_parser.GeneratedSqlTokenRange) ![]const u8 {
    if (range.end != range.start + 1 or range.end > tokens.len) return error.UnsupportedSqlShape;
    if (tokens[range.start].kind != .identifier) return error.UnsupportedSqlShape;
    return tokens[range.start].text;
}

fn countGeneratedParenthesizedList(tokens: []const grammar.Token, range: generated_parser.GeneratedSqlTokenRange) !usize {
    if (range.start >= range.end or range.end > tokens.len) return error.UnsupportedSqlShape;
    if (tokens[range.start].kind != .lparen or tokens[range.end - 1].kind != .rparen) return error.UnsupportedSqlShape;
    if (range.start + 1 == range.end - 1) return 0;

    var count: usize = 1;
    var depth: usize = 0;
    for (tokens[range.start + 1 .. range.end - 1]) |token| {
        switch (token.kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return error.UnsupportedSqlShape;
                depth -= 1;
            },
            .comma => {
                if (depth == 0) count += 1;
            },
            else => {},
        }
    }
    if (depth != 0) return error.UnsupportedSqlShape;
    return count;
}

pub fn sessionCatalogPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlSessionAst,
) !SessionCatalogPlan {
    const end = try validateGeneratedSessionAstRanges(tokens, ast);
    const tail = generatedStatementTail(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    var plan: SessionCatalogPlan = switch (ast.kind) {
        .set => try setSessionCatalogPlanFromGeneratedTailAlloc(alloc, tail),
        .reset => try resetSessionCatalogPlanFromGeneratedTailAlloc(alloc, tail),
        .show => try showSessionCatalogPlanFromGeneratedTail(tail),
        .discard_all => try discardSessionCatalogPlanFromGeneratedTail(tail),
    };
    errdefer plan.deinit(alloc);
    try validateGeneratedSessionCatalogPlanMatchesAst(tokens, end, ast, plan);
    return plan;
}

fn sessionLogicalPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlSessionAst,
) !binder.LogicalSqlPlan {
    const plan = try sessionDdlPlanFromGeneratedAstAlloc(alloc, tokens, ast);
    return switch (plan) {
        .session_catalog => |session| .{ .session = session },
        .adapter_noop => |noop| .{ .other_ddl = .{ .adapter_noop = noop } },
        else => error.UnsupportedSqlShape,
    };
}

pub fn transactionControlPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlTransactionAst,
) !LegacyDdlParserPlan {
    const logical = transactionLogicalPlanFromGeneratedAstAlloc(alloc, tokens, ast) catch |err| switch (err) {
        error.UnsupportedSqlShape => {
            try validateGeneratedTransactionAstSpans(tokens, ast);
            if (ast.name_tokens != null or ast.mode_tokens != null) return err;
            return .{ .adapter_noop = .{ .reason = .transaction_control } };
        },
        else => return err,
    };
    return switch (logical) {
        .control => |payload| .{ .transaction_control = payload },
        .savepoint => |payload| .{ .savepoint_transaction = payload },
        .prepared => |payload| .{ .prepared_transaction = payload },
    };
}

pub fn transactionLogicalPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlTransactionAst,
) !binder.TransactionLogicalPlan {
    try validateGeneratedTransactionAstSpans(tokens, ast);
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    if (ast.name_tokens) |name_tokens| {
        if (name_tokens.end != end) return error.UnsupportedSqlShape;
        var pos: usize = 0;
        var plan: binder.TransactionLogicalPlan = switch (ast.kind) {
            .savepoint => .{ .savepoint = .{ .savepoint = try parseSavepointTransactionPlanTailAlloc(alloc, tokens[1..end], &pos) } },
            .release_savepoint => .{ .savepoint = .{ .release = try parseReleaseSavepointPlanTailAlloc(alloc, tokens[1..end], &pos) } },
            .rollback_to_savepoint => .{ .savepoint = .{ .rollback_to = try parseRollbackToSavepointPlanTailAlloc(alloc, tokens[1..end], &pos) } },
            else => return error.UnsupportedSqlShape,
        };
        errdefer plan.deinit(alloc);
        if (pos != end - 1) return error.UnsupportedSqlShape;
        return plan;
    }
    if (ast.mode_tokens) |mode_tokens| {
        if (mode_tokens.start != 1 or mode_tokens.end != end) return error.UnsupportedSqlShape;
        var pos: usize = 0;
        if (ast.kind == .constraint_mode) {
            var plan = try parseConstraintModePlanTailAlloc(alloc, tokens[mode_tokens.start..mode_tokens.end], &pos);
            errdefer plan.deinit(alloc);
            if (pos != mode_tokens.end - mode_tokens.start) return error.UnsupportedSqlShape;
            return .{ .control = .{ .constraint_mode = plan } };
        }
        const starter: TransactionModeStarter = switch (ast.kind) {
            .set_transaction => .set_transaction,
            .start_transaction => .start_transaction,
            .begin => .begin,
            .commit,
            .rollback,
            .savepoint,
            .release_savepoint,
            .rollback_to_savepoint,
            .constraint_mode,
            => return error.UnsupportedSqlShape,
        };
        const mode = try parseTransactionModePlanTail(tokens[mode_tokens.start..mode_tokens.end], &pos, starter);
        if (pos != mode_tokens.end - mode_tokens.start) return error.UnsupportedSqlShape;
        return .{ .control = .{ .transaction_mode = mode } };
    }
    return error.UnsupportedSqlShape;
}

pub fn transactionBoundaryPlanFromGeneratedAst(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlTransactionAst,
) !LegacyDdlParserPlan {
    const plan = try transactionControlPlanFromGeneratedAstAlloc(alloc, tokens, ast);
    switch (plan) {
        .adapter_noop => return plan,
        else => return error.UnsupportedSqlShape,
    }
}

fn validateGeneratedTransactionAstSpans(
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlTransactionAst,
) !void {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    if (end == 0 or tokens[0].source_start != ast.command_span.start or tokens[0].source_end != ast.command_span.end) {
        return error.UnsupportedSqlShape;
    }
    switch (ast.kind) {
        .set_transaction => if (!tokens[0].matchesKeywordTag(.set)) return error.UnsupportedSqlShape,
        .constraint_mode => if (!tokens[0].matchesKeywordTag(.set)) return error.UnsupportedSqlShape,
        .start_transaction => if (!tokens[0].matchesKeyword("start")) return error.UnsupportedSqlShape,
        .begin => if (!tokens[0].matchesKeywordTag(.begin)) return error.UnsupportedSqlShape,
        .commit => if (!tokens[0].matchesKeywordTag(.commit) and !tokens[0].matchesKeywordTag(.end)) return error.UnsupportedSqlShape,
        .rollback => if (!tokens[0].matchesKeywordTag(.rollback)) return error.UnsupportedSqlShape,
        .savepoint => if (!tokens[0].matchesKeywordTag(.savepoint)) return error.UnsupportedSqlShape,
        .release_savepoint => if (!tokens[0].matchesKeywordTag(.release)) return error.UnsupportedSqlShape,
        .rollback_to_savepoint => if (!tokens[0].matchesKeywordTag(.rollback)) return error.UnsupportedSqlShape,
    }
    if (ast.boundary_tail_tokens != null and ast.mode_tokens != null) return error.UnsupportedSqlShape;
    if (ast.name_tokens != null and (ast.boundary_tail_tokens != null or ast.mode_tokens != null)) return error.UnsupportedSqlShape;
    if (ast.name_tokens) |name| {
        try validateGeneratedSavepointNameRange(tokens, end, ast.kind, name);
        return;
    }
    if (ast.boundary_tail_tokens) |tail| {
        if (tail.start != 1 or tail.end != 2 or tail.end > end) return error.UnsupportedSqlShape;
        switch (ast.kind) {
            .set_transaction,
            .constraint_mode,
            .savepoint,
            .release_savepoint,
            .rollback_to_savepoint,
            => return error.UnsupportedSqlShape,
            .start_transaction => if (!tokens[tail.start].matchesKeyword("transaction")) return error.UnsupportedSqlShape,
            .begin, .commit, .rollback => {
                if (!tokens[tail.start].matchesKeyword("work") and !tokens[tail.start].matchesKeyword("transaction")) {
                    return error.UnsupportedSqlShape;
                }
            },
        }
    } else if (ast.mode_tokens == null and (ast.kind == .set_transaction or ast.kind == .constraint_mode)) {
        return error.UnsupportedSqlShape;
    } else if (ast.mode_tokens == null and end > 1) {
        return error.UnsupportedSqlShape;
    }
}

fn validateGeneratedSavepointNameRange(
    tokens: []const grammar.Token,
    end: usize,
    kind: generated_parser.GeneratedSqlTransactionKind,
    name: generated_parser.GeneratedSqlTokenRange,
) !void {
    const expected_start: usize = switch (kind) {
        .savepoint => 1,
        .release_savepoint => if (end > 1 and tokens[1].matchesKeywordTag(.savepoint)) @as(usize, 2) else 1,
        .rollback_to_savepoint => blk: {
            if (end <= 1 or !tokens[1].matchesKeywordTag(.to)) return error.UnsupportedSqlShape;
            break :blk if (end > 2 and tokens[2].matchesKeywordTag(.savepoint)) @as(usize, 3) else 2;
        },
        else => return error.UnsupportedSqlShape,
    };
    if (name.start != expected_start or name.end != expected_start + 1 or name.end != end) return error.UnsupportedSqlShape;
    if (tokens[name.start].kind != .identifier) return error.UnsupportedSqlShape;
}

pub fn sessionDdlPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlSessionAst,
) !LegacyDdlParserPlan {
    _ = try validateGeneratedSessionAstRanges(tokens, ast);
    const tail = generatedStatementTail(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    var pos: usize = 0;
    return switch (ast.kind) {
        .set => blk: {
            if (tokens.len == 0 or !tokens[0].matchesKeywordTag(.set)) return error.UnsupportedSqlShape;
            if (sessionCatalogPlanFromGeneratedAstAlloc(alloc, tokens, ast)) |plan| {
                break :blk .{ .session_catalog = plan };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => {
                    if (generatedSessionCommandIsCatalogOwned(tokens, ast)) return err;
                    pos = 0;
                },
                else => return err,
            }
            if (grammar.parseAdapterNoopSetStatementTail(tail, &pos)) {
                break :blk .{ .adapter_noop = .{ .reason = .session_setting } };
            } else |err| return err;
        },
        .reset => blk: {
            if (tokens.len == 0 or !tokens[0].matchesKeywordTag(.reset)) return error.UnsupportedSqlShape;
            if (sessionCatalogPlanFromGeneratedAstAlloc(alloc, tokens, ast)) |plan| {
                break :blk .{ .session_catalog = plan };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => {
                    if (generatedSessionCommandIsCatalogOwned(tokens, ast)) return err;
                    pos = 0;
                },
                else => return err,
            }
            try grammar.parseAdapterNoopResetStatementTail(tail, &pos);
            break :blk .{ .adapter_noop = .{ .reason = .session_setting } };
        },
        .show => blk: {
            if (tokens.len == 0 or !tokens[0].matchesKeywordTag(.show)) return error.UnsupportedSqlShape;
            if (sessionCatalogPlanFromGeneratedAstAlloc(alloc, tokens, ast)) |plan| {
                break :blk .{ .session_catalog = plan };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => {
                    if (generatedSessionCommandIsCatalogOwned(tokens, ast)) return err;
                    pos = 0;
                },
                else => return err,
            }
            try grammar.parseAdapterNoopShowStatementTail(tail, &pos);
            break :blk .{ .adapter_noop = .{ .reason = .session_setting } };
        },
        .discard_all => blk: {
            if (tokens.len == 0 or !tokens[0].matchesKeywordTag(.discard)) return error.UnsupportedSqlShape;
            break :blk .{ .session_catalog = try sessionCatalogPlanFromGeneratedAstAlloc(alloc, tokens, ast) };
        },
    };
}

fn generatedSessionCommandIsCatalogOwned(
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlSessionAst,
) bool {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return false;
    if (end <= 1) return ast.kind == .discard_all;
    return switch (ast.kind) {
        .set => generatedSetSessionTailIsCatalogOwned(tokens, end),
        .reset, .show => generatedNamedSessionTailIsCatalogOwned(tokens, 1, end) or
            (ast.kind == .reset and tokens[1].matchesKeyword("all") and end == 2),
        .discard_all => true,
    };
}

fn generatedSetSessionTailIsCatalogOwned(tokens: []const grammar.Token, end: usize) bool {
    var index: usize = 1;
    if (index < end and tokens[index].matchesKeyword("local")) index += 1;
    if (index < end and tokens[index].matchesKeyword("session")) {
        if (index + 1 < end and tokens[index + 1].matchesKeyword("characteristics")) return true;
        index += 1;
    }
    return generatedNamedSessionTailIsCatalogOwned(tokens, index, end);
}

fn generatedNamedSessionTailIsCatalogOwned(tokens: []const grammar.Token, name_index: usize, end: usize) bool {
    if (name_index >= end or tokens[name_index].kind != .identifier) return false;
    const name = tokens[name_index].text;
    return std.ascii.eqlIgnoreCase(name, "search_path") or generatedSessionSettingKindForName(name) != null;
}

fn generatedSessionSettingKindForName(setting: []const u8) ?SessionSettingKind {
    if (std.mem.startsWith(u8, setting, "app.") and setting.len > "app.".len) return .app;
    if (std.ascii.eqlIgnoreCase(setting, "antfly.sync_level")) return .antfly;
    if (std.ascii.eqlIgnoreCase(setting, "statement_timeout") or
        std.ascii.eqlIgnoreCase(setting, "timezone") or
        std.ascii.eqlIgnoreCase(setting, "default_transaction_read_only") or
        std.ascii.eqlIgnoreCase(setting, "transaction_read_only"))
    {
        return .runtime;
    }
    return null;
}

fn validateGeneratedSessionAstRanges(
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlSessionAst,
) !usize {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    if (end == 0) return error.UnsupportedSqlShape;
    if (tokens[0].source_start != ast.command_span.start or tokens[0].source_end != ast.command_span.end) {
        return error.UnsupportedSqlShape;
    }
    switch (ast.kind) {
        .set => {
            const name = ast.name_tokens orelse return error.UnsupportedSqlShape;
            try validateGeneratedOptionalSessionRange(name, 1, end);
            if (ast.value_tokens) |value| {
                try validateGeneratedOptionalSessionRange(value, 1, end);
                if (name.end > value.start) return error.UnsupportedSqlShape;
            }
        },
        .reset, .show => {
            const name = ast.name_tokens orelse return error.UnsupportedSqlShape;
            try validateGeneratedRequiredSessionRange(name, 1, end);
            if (ast.value_tokens != null) return error.UnsupportedSqlShape;
        },
        .discard_all => {
            if (ast.name_tokens != null or ast.value_tokens != null) return error.UnsupportedSqlShape;
        },
    }
    return end;
}

fn validateGeneratedOptionalSessionRange(
    range: generated_parser.GeneratedSqlTokenRange,
    min_start: usize,
    end: usize,
) !void {
    if (range.start < min_start or range.start > range.end or range.end > end) return error.UnsupportedSqlShape;
}

fn validateGeneratedRequiredSessionRange(
    range: generated_parser.GeneratedSqlTokenRange,
    min_start: usize,
    end: usize,
) !void {
    try validateGeneratedOptionalSessionRange(range, min_start, end);
    if (range.start == range.end) return error.UnsupportedSqlShape;
}

fn validateGeneratedSessionCatalogPlanMatchesAst(
    tokens: []const grammar.Token,
    end: usize,
    ast: generated_parser.GeneratedSqlSessionAst,
    plan: SessionCatalogPlan,
) !void {
    switch (plan) {
        .set_search_path => try validateGeneratedSetSessionNameAndValue(tokens, end, ast, "search_path", null),
        .set_setting => |set_setting| {
            if (std.ascii.eqlIgnoreCase(set_setting.name, "default_transaction_read_only") and ast.value_tokens == null) {
                return try validateGeneratedSetSessionCharacteristicsAst(tokens, end, ast);
            }
            try validateGeneratedSetSessionNameAndValue(tokens, end, ast, set_setting.name, set_setting.value);
        },
        .reset_setting => |reset_setting| try validateGeneratedSingleNameSessionAst(tokens, end, ast, .reset, reset_setting.name),
        .reset_search_path => try validateGeneratedSingleNameSessionAst(tokens, end, ast, .reset, "search_path"),
        .show_search_path => try validateGeneratedSingleNameSessionAst(tokens, end, ast, .show, "search_path"),
        .discard_all => switch (ast.kind) {
            .reset => try validateGeneratedSingleNameSessionAst(tokens, end, ast, .reset, "all"),
            .discard_all => {
                if (end != 2 or !tokens[0].matchesKeywordTag(.discard) or !tokens[1].matchesKeyword("all")) return error.UnsupportedSqlShape;
                if (ast.name_tokens != null or ast.value_tokens != null) return error.UnsupportedSqlShape;
            },
            else => return error.UnsupportedSqlShape,
        },
    }
}

fn validateGeneratedSetSessionNameAndValue(
    tokens: []const grammar.Token,
    end: usize,
    ast: generated_parser.GeneratedSqlSessionAst,
    expected_name: []const u8,
    expected_single_value: ?[]const u8,
) !void {
    if (ast.kind != .set or end == 0 or !tokens[0].matchesKeywordTag(.set)) return error.UnsupportedSqlShape;
    const name = ast.name_tokens orelse return error.UnsupportedSqlShape;
    const value = ast.value_tokens orelse return error.UnsupportedSqlShape;
    if (value.start < name.end or value.start >= value.end or value.end != end) return error.UnsupportedSqlShape;
    if (name.start < 1 or name.end <= name.start or name.end > value.start) return error.UnsupportedSqlShape;
    if (!std.ascii.eqlIgnoreCase(tokens[name.end - 1].text, expected_name)) return error.UnsupportedSqlShape;
    if (expected_single_value) |expected_value| {
        if (value.end != value.start + 1) return error.UnsupportedSqlShape;
        if (!std.mem.eql(u8, tokens[value.start].text, expected_value)) return error.UnsupportedSqlShape;
    }
}

fn validateGeneratedSetSessionCharacteristicsAst(
    tokens: []const grammar.Token,
    end: usize,
    ast: generated_parser.GeneratedSqlSessionAst,
) !void {
    if (ast.kind != .set or end < 5 or ast.value_tokens != null) return error.UnsupportedSqlShape;
    const name = ast.name_tokens orelse return error.UnsupportedSqlShape;
    if (name.start != 1 or name.end != end - 1) return error.UnsupportedSqlShape;
    if (!tokens[0].matchesKeywordTag(.set) or
        !tokens[1].matchesKeyword("session") or
        !tokens[2].matchesKeyword("characteristics") or
        !tokens[3].matchesKeywordTag(.as))
    {
        return error.UnsupportedSqlShape;
    }
}

fn validateGeneratedSingleNameSessionAst(
    tokens: []const grammar.Token,
    end: usize,
    ast: generated_parser.GeneratedSqlSessionAst,
    expected_kind: generated_parser.GeneratedSqlSessionKind,
    expected_name: []const u8,
) !void {
    if (ast.kind != expected_kind) return error.UnsupportedSqlShape;
    if (end == 0 or ast.value_tokens != null) return error.UnsupportedSqlShape;
    const name = ast.name_tokens orelse return error.UnsupportedSqlShape;
    if (name.start != 1 or name.end != end or name.start >= name.end) return error.UnsupportedSqlShape;
    if (!std.ascii.eqlIgnoreCase(tokens[name.end - 1].text, expected_name)) return error.UnsupportedSqlShape;
}

pub fn simpleDdlPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
) !LegacyDdlParserPlan {
    try validateGeneratedDdlAstSpans(tokens, ast);
    return switch (ast.kind) {
        .create_database => .{ .database_catalog = .{ .create = try createDatabasePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .create_schema => try createSchemaNamespacePlanOrAdapterNoopFromGeneratedDdlAstAlloc(alloc, tokens, ast),
        .create_extension => try createExtensionPlanOrAdapterNoopFromGeneratedDdlAstAlloc(alloc, tokens, ast),
        .alter_database => .{ .database_catalog = .{ .alter = try alterDatabasePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .alter_extension => .{ .extension_catalog = .{ .update = try updateExtensionPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .alter_schema => .{ .schema_namespace_catalog = .{ .rename = try renameSchemaNamespacePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .drop_database => .{ .database_catalog = .{ .drop = try dropDatabasePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .drop_schema => .{ .schema_namespace_catalog = .{ .drop = try dropSchemaNamespacePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .drop_extension => .{ .extension_catalog = .{ .drop = try dropExtensionPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        else => error.UnsupportedSqlShape,
    };
}

pub fn ddlPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    options: DdlPlanParserOptions,
) !LegacyDdlParserPlan {
    try validateGeneratedDdlAstSpans(tokens, ast);
    const tail = generatedStatementTail(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    var pos: usize = 0;
    return switch (ast.kind) {
        .create_table => blk: {
            if (generatedCreateTableUsesRelationLifetime(tokens, ast)) {
                var lifetime_pos: usize = 1;
                break :blk .{ .relation_lifetime = try parseGeneratedRelationLifetimePlanAlloc(alloc, tokens, &lifetime_pos, ast.statement_span, options.column_definition_options) };
            }
            if (generatedCreateTableMayUseIdentityAllocator(tokens, ast)) {
                break :blk .{ .identity_allocator_catalog = try identityAllocatorPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options.column_definition_options) };
            }
            var clone_pos: usize = 0;
            if (parseCreateTableClonePlanTailAlloc(alloc, tail, &clone_pos)) |table_clone| {
                break :blk .{ .table_clone = table_clone };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => {},
                else => return err,
            }
            var create_partition_pos: usize = 0;
            if (parseGeneratedCreateTablePartitionTailPlanAlloc(alloc, tail, &create_partition_pos)) |partition| {
                break :blk .{ .table_partition_catalog = .{ .create_partition = partition } };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => {},
                else => return err,
            }
            var partitioned_pos: usize = 0;
            if (parseGeneratedCreatePartitionedTableTailPlanAlloc(alloc, tail, &partitioned_pos, options.column_definition_options)) |partitioned| {
                break :blk .{ .table_partition_catalog = .{ .create_partitioned = partitioned } };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => {},
                else => return err,
            }
            break :blk .{ .create_table = try parseGeneratedCreateTableTailPlanAlloc(alloc, tail, &pos, options.column_definition_options) };
        },
        .create_view,
        .alter_view,
        .drop_view,
        => try viewCatalogPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options),
        .create_materialized_view,
        .drop_materialized_view,
        .refresh_materialized_view,
        => try materializedViewCatalogPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options),
        .create_domain,
        .alter_domain,
        .drop_domain,
        => try domainCatalogPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options),
        .create_sequence,
        .alter_sequence,
        .drop_sequence,
        => try sequenceCatalogPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options),
        .create_enum_type,
        .alter_enum_type,
        .drop_enum_type,
        => try enumTypeCatalogPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options),
        .create_tablespace,
        .alter_tablespace,
        .drop_tablespace,
        => try tablespaceCatalogPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options),
        .create_publication,
        .alter_publication,
        .drop_publication,
        .create_subscription,
        .alter_subscription,
        .drop_subscription,
        => try logicalReplicationCatalogPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options),
        .create_policy,
        .alter_policy,
        .drop_policy,
        => try rowSecurityPolicyCatalogPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options),
        .create_function,
        .create_procedure,
        .drop_function,
        .drop_procedure,
        => try routineCatalogPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options),
        .create_role,
        .alter_role,
        .drop_role,
        => try authorizationCatalogPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options),
        .create_collation,
        .alter_collation,
        .drop_collation,
        .create_operator,
        .drop_operator,
        .create_aggregate,
        .drop_aggregate,
        .create_cast,
        .drop_cast,
        => try typeSystemCatalogPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options),
        .create_index => .{ .create_index = try createIndexPlanFromGeneratedAstAlloc(alloc, tokens, ast, options.create_index_options) },
        .alter_table => blk: {
            if (generatedAlterTableUsesRowSecurityRuntimeBoundary(tokens, ast)) {
                break :blk .{ .row_security_catalog = .{ .alter_table = try rowSecurityAlterTablePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } };
            }
            if (tablePartitionPlanFromGeneratedAlterTableAstAlloc(alloc, tokens, ast)) |partition| {
                break :blk .{ .table_partition_catalog = partition };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => {},
                else => return err,
            }
            break :blk .{ .alter_table = try alterTablePlanFromGeneratedAstAlloc(alloc, tokens, ast, options.column_definition_options) };
        },
        .drop_table => .{ .drop_table = try dropTablePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) },
        .drop_index => .{ .drop_index = try dropIndexPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) },
        else => try simpleDdlPlanFromGeneratedAstAlloc(alloc, tokens, ast),
    };
}

pub fn logicalDdlPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    options: DdlPlanParserOptions,
) !binder.LogicalSqlPlan {
    try validateGeneratedDdlAstSpans(tokens, ast);
    const tail = generatedStatementTail(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    var pos: usize = 0;
    return switch (ast.kind) {
        .create_table => blk: {
            if (generatedCreateTableUsesRelationLifetime(tokens, ast)) {
                var lifetime_pos: usize = 1;
                break :blk .{ .table_ddl = .{ .relation_lifetime = try parseGeneratedRelationLifetimePlanAlloc(alloc, tokens, &lifetime_pos, ast.statement_span, options.column_definition_options) } };
            }
            if (generatedCreateTableMayUseIdentityAllocator(tokens, ast)) {
                break :blk .{ .catalog_ddl = .{ .identity_allocator_catalog = try identityAllocatorPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options.column_definition_options) } };
            }
            var clone_pos: usize = 0;
            if (parseCreateTableClonePlanTailAlloc(alloc, tail, &clone_pos)) |table_clone| {
                break :blk .{ .table_ddl = .{ .table_clone = table_clone } };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => {},
                else => return err,
            }
            var create_partition_pos: usize = 0;
            if (parseGeneratedCreateTablePartitionTailPlanAlloc(alloc, tail, &create_partition_pos)) |partition| {
                break :blk .{ .table_ddl = .{ .table_partition_catalog = .{ .create_partition = partition } } };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => {},
                else => return err,
            }
            var partitioned_pos: usize = 0;
            if (parseGeneratedCreatePartitionedTableTailPlanAlloc(alloc, tail, &partitioned_pos, options.column_definition_options)) |partitioned| {
                break :blk .{ .table_ddl = .{ .table_partition_catalog = .{ .create_partitioned = partitioned } } };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => {},
                else => return err,
            }
            break :blk .{ .table_ddl = .{ .create_table = try parseGeneratedCreateTableTailPlanAlloc(alloc, tail, &pos, options.column_definition_options) } };
        },
        .create_view,
        .alter_view,
        .drop_view,
        => blk: {
            try validateGeneratedViewDdlAst(tokens, ast);
            break :blk try parseGeneratedLogicalDdlPlanExpectAlloc(alloc, tokens, options, .{ .table = .view_catalog });
        },
        .create_materialized_view,
        .drop_materialized_view,
        .refresh_materialized_view,
        => blk: {
            try validateGeneratedMaterializedViewDdlAst(tokens, ast);
            break :blk try parseGeneratedLogicalDdlPlanExpectAlloc(alloc, tokens, options, .{ .table = .materialized_view_catalog });
        },
        .create_domain,
        .alter_domain,
        .drop_domain,
        => blk: {
            try validateGeneratedDomainDdlAst(tokens, ast);
            break :blk try parseGeneratedLogicalDdlPlanExpectAlloc(alloc, tokens, options, .{ .catalog = .domain_catalog });
        },
        .create_sequence,
        .alter_sequence,
        .drop_sequence,
        => blk: {
            try validateGeneratedSequenceDdlAst(tokens, ast);
            break :blk try parseGeneratedLogicalDdlPlanExpectAlloc(alloc, tokens, options, .{ .catalog = .sequence_catalog });
        },
        .create_enum_type,
        .alter_enum_type,
        .drop_enum_type,
        => blk: {
            try validateGeneratedEnumTypeDdlAst(tokens, ast);
            break :blk try parseGeneratedLogicalDdlPlanExpectAlloc(alloc, tokens, options, .{ .catalog = .enum_type_catalog });
        },
        .create_tablespace,
        .alter_tablespace,
        .drop_tablespace,
        => blk: {
            try validateGeneratedTablespaceDdlAst(tokens, ast);
            break :blk try parseGeneratedLogicalDdlPlanExpectAlloc(alloc, tokens, options, .{ .catalog = .tablespace_catalog });
        },
        .create_publication,
        .alter_publication,
        .drop_publication,
        .create_subscription,
        .alter_subscription,
        .drop_subscription,
        => blk: {
            try validateGeneratedLogicalReplicationDdlAst(tokens, ast);
            break :blk try parseGeneratedLogicalDdlPlanExpectAlloc(alloc, tokens, options, .{ .catalog = .logical_replication });
        },
        .create_policy,
        .alter_policy,
        .drop_policy,
        => blk: {
            try validateGeneratedRowSecurityPolicyDdlAst(tokens, ast);
            break :blk try parseGeneratedLogicalDdlPlanExpectAlloc(alloc, tokens, options, .{ .auth = .row_security_catalog });
        },
        .create_function,
        .create_procedure,
        .drop_function,
        .drop_procedure,
        => blk: {
            try validateGeneratedRoutineDdlAst(tokens, ast);
            break :blk try parseGeneratedLogicalDdlPlanExpectAlloc(alloc, tokens, options, .{ .routine = .function_catalog });
        },
        .create_role,
        .alter_role,
        .drop_role,
        => blk: {
            try validateGeneratedRoleDdlAst(tokens, ast);
            break :blk try parseGeneratedLogicalDdlPlanExpectAlloc(alloc, tokens, options, .{ .auth = .authorization_catalog });
        },
        .create_collation,
        .alter_collation,
        .drop_collation,
        .create_operator,
        .drop_operator,
        .create_aggregate,
        .drop_aggregate,
        .create_cast,
        .drop_cast,
        => blk: {
            try validateGeneratedTypeSystemDdlAst(tokens, ast);
            break :blk try parseGeneratedLogicalDdlPlanExpectAlloc(alloc, tokens, options, .{ .catalog = .type_system_catalog });
        },
        .create_index => .{ .table_ddl = .{ .create_index = try createIndexPlanFromGeneratedAstAlloc(alloc, tokens, ast, options.create_index_options) } },
        .alter_table => blk: {
            if (generatedAlterTableUsesRowSecurityRuntimeBoundary(tokens, ast)) {
                break :blk .{ .auth = .{ .row_security_catalog = .{ .alter_table = try rowSecurityAlterTablePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } } };
            }
            if (tablePartitionPlanFromGeneratedAlterTableAstAlloc(alloc, tokens, ast)) |partition| {
                break :blk .{ .table_ddl = .{ .table_partition_catalog = partition } };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => {},
                else => return err,
            }
            break :blk .{ .table_ddl = .{ .alter_table = try alterTablePlanFromGeneratedAstAlloc(alloc, tokens, ast, options.column_definition_options) } };
        },
        .drop_table => .{ .table_ddl = .{ .drop_table = try dropTablePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .drop_index => .{ .table_ddl = .{ .drop_index = try dropIndexPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .create_database,
        .create_schema,
        .create_extension,
        .alter_database,
        .alter_extension,
        .alter_schema,
        .drop_database,
        .drop_schema,
        .drop_extension,
        => try simpleLogicalDdlPlanFromGeneratedAstAlloc(alloc, tokens, ast),
        else => error.UnsupportedSqlShape,
