            .row_security_catalog => |catalog| switch (catalog) {
                .drop_policy => {},
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        else => return error.UnsupportedSqlShape,
    }
    return plan;
}

fn validateGeneratedRowSecurityPolicyDdlAst(tokens: []const grammar.Token, ast: generated_parser.GeneratedSqlDdlAst) !void {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    const policy_name = ast.object_name_tokens orelse return error.UnsupportedSqlShape;
    const table_name = ast.index_table_tokens orelse return error.UnsupportedSqlShape;
    if (policy_name.start >= policy_name.end or policy_name.end > end) return error.UnsupportedSqlShape;
    if (table_name.start >= table_name.end or table_name.end > end) return error.UnsupportedSqlShape;
    switch (ast.kind) {
        .create_policy => {
            if (end < 5 or !tokens[0].matchesKeyword("create") or !tokens[1].matchesKeyword("policy")) return error.UnsupportedSqlShape;
            try validateGeneratedRowSecurityPolicyDdlNameAndTable(tokens, end, policy_name, table_name, 2);
            try validateGeneratedRowSecurityPolicyDdlTail(tokens, ast, end, table_name, true);
        },
        .alter_policy => {
            if (end < 6 or !tokens[0].matchesKeyword("alter") or !tokens[1].matchesKeyword("policy")) return error.UnsupportedSqlShape;
            try validateGeneratedRowSecurityPolicyDdlNameAndTable(tokens, end, policy_name, table_name, 2);
            const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
            if (operation.start != table_name.end or operation.end != end or operation.start >= end) return error.UnsupportedSqlShape;
            if (!tokens[operation.start].matchesKeyword("rename") and
                !tokens[operation.start].matchesKeyword("to") and
                !tokens[operation.start].matchesKeyword("using") and
                !tokens[operation.start].matchesKeyword("with"))
            {
                return error.UnsupportedSqlShape;
            }
        },
        .drop_policy => {
            if (end < 5 or !tokens[0].matchesKeyword("drop") or !tokens[1].matchesKeyword("policy")) return error.UnsupportedSqlShape;
            var name_index: usize = 2;
            const if_exists = consumeGeneratedPlanIfExists(tokens, &name_index, end);
            if (if_exists != ast.if_exists) return error.UnsupportedSqlShape;
            try validateGeneratedRowSecurityPolicyDdlNameAndTable(tokens, end, policy_name, table_name, name_index);
            if (ast.alter_table_operation_tokens != null) return error.UnsupportedSqlShape;
            const has_cascade = generatedRangeHasKeyword(tokens, .{ .start = table_name.end, .end = end }, "cascade");
            if (has_cascade != ast.cascade) return error.UnsupportedSqlShape;
            if (table_name.end < end and
                !tokens[table_name.end].matchesKeyword("cascade") and
                !tokens[table_name.end].matchesKeyword("restrict"))
            {
                return error.UnsupportedSqlShape;
            }
        },
        else => return error.UnsupportedSqlShape,
    }
}

fn validateGeneratedRowSecurityPolicyDdlNameAndTable(
    tokens: []const grammar.Token,
    end: usize,
    policy_name: generated_parser.GeneratedSqlTokenRange,
    table_name: generated_parser.GeneratedSqlTokenRange,
    name_index: usize,
) !void {
    if (policy_name.start != name_index) return error.UnsupportedSqlShape;
    if (policy_name.end >= end or !tokens[policy_name.end].matchesKeyword("on")) return error.UnsupportedSqlShape;
    if (table_name.start != policy_name.end + 1) return error.UnsupportedSqlShape;
}

fn validateGeneratedRowSecurityPolicyDdlTail(
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    end: usize,
    table_name: generated_parser.GeneratedSqlTokenRange,
    allow_empty_tail: bool,
) !void {
    if (table_name.end < end) {
        const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
        if (operation.start != table_name.end or operation.end != end or operation.start >= end) return error.UnsupportedSqlShape;
        if (!tokens[operation.start].matchesKeyword("to") and
            !tokens[operation.start].matchesKeyword("using") and
            !tokens[operation.start].matchesKeyword("with"))
        {
            return error.UnsupportedSqlShape;
        }
    } else if (!allow_empty_tail or ast.alter_table_operation_tokens != null) {
        return error.UnsupportedSqlShape;
    }
}

fn generatedCreateIndexUsesRuntimeBoundary(tokens: []const grammar.Token, ast: generated_parser.GeneratedSqlDdlAst) bool {
    return generatedStatementEnd(tokens, ast.statement_span) != null;
}

fn generatedCreateIndexWhereUsesRuntimeBoundary(tokens: []const grammar.Token, range: generated_parser.GeneratedSqlTokenRange) bool {
    if (range.end > tokens.len or range.start > range.end) return false;
    return range.start < range.end;
}

fn generatedAlterTableUsesRuntimeBoundary(tokens: []const grammar.Token, ast: generated_parser.GeneratedSqlDdlAst) bool {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return false;
    const operation_range = ast.alter_table_operation_tokens orelse return false;
    if (!generatedRangeWithinStatement(operation_range, end) or operation_range.start >= operation_range.end) return false;
    validateGeneratedAlterTableOperationItems(tokens, operation_range, &ast.alter_table_operation_items) catch return false;
    return true;
}

fn validateGeneratedAlterTableOperationItems(
    tokens: []const grammar.Token,
    operation_range: generated_parser.GeneratedSqlTokenRange,
    items: *const generated_parser.GeneratedSqlListAst,
) !void {
    if (operation_range.end > tokens.len or operation_range.start >= operation_range.end) return error.UnsupportedSqlShape;
    if (items.count == 0 or items.items.len != items.count) return error.UnsupportedSqlShape;
    if (items.expression_items.len != 0 or
        items.alias_items.len != 0 or
        items.alias_name_items.len != 0 or
        items.direction_items.len != 0 or
        items.directions.len != 0 or
        items.order_using_operator_items.len != 0 or
        items.nulls_order_items.len != 0 or
        items.nulls_orders.len != 0 or
        items.expressions.len != 0)
    {
        return error.UnsupportedSqlShape;
    }

    if (!std.meta.eql(items.first_tokens orelse return error.UnsupportedSqlShape, items.items[0])) return error.UnsupportedSqlShape;
    if (!std.meta.eql(items.last_tokens orelse return error.UnsupportedSqlShape, items.items[items.items.len - 1])) return error.UnsupportedSqlShape;

    var expected_start = operation_range.start;
    for (items.items, 0..) |item, item_index| {
        if (item.start != expected_start or item.start >= item.end or item.end > operation_range.end) return error.UnsupportedSqlShape;
        if (!generatedAlterTableOperationSegmentUsesRuntimeBoundary(tokens, item.start, item.end)) return error.UnsupportedSqlShape;
        if (item_index + 1 < items.items.len) {
            if (item.end >= operation_range.end or tokens[item.end].kind != .comma) return error.UnsupportedSqlShape;
            expected_start = item.end + 1;
        } else {
            expected_start = item.end;
        }
    }
    if (expected_start != operation_range.end) return error.UnsupportedSqlShape;
}

fn generatedAlterTableOperationSegmentUsesRuntimeBoundary(tokens: []const grammar.Token, start: usize, end: usize) bool {
    if (start >= end or end > tokens.len) return false;
    const first = tokens[start];
    if (first.matchesKeywordTag(.add)) {
        if (start + 1 >= end) return false;
        if (tokens[start + 1].matchesKeywordTag(.column)) return true;
        if (tokens[start + 1].matchesKeyword("period")) return true;
        var constraint_kind_index = start + 1;
        if (tokens[constraint_kind_index].matchesKeywordTag(.constraint)) {
            if (constraint_kind_index + 2 >= end) return false;
            constraint_kind_index += 2;
        }
        return generatedAlterTableAddConstraintKindUsesRuntimeBoundary(tokens[constraint_kind_index]);
    }
    if (first.matchesKeywordTag(.drop)) {
        return start + 1 < end and
            (tokens[start + 1].matchesKeywordTag(.column) or
                tokens[start + 1].matchesKeywordTag(.constraint));
    }
    if (first.matchesKeywordTag(.rename)) {
        return start + 1 < end and
            (tokens[start + 1].matchesKeywordTag(.column) or
                tokens[start + 1].matchesKeywordTag(.constraint));
    }
    if (first.matchesKeywordTag(.alter)) {
        return generatedAlterTableAlterColumnSegmentUsesRuntimeBoundary(tokens, start, end);
    }
    if (first.matchesKeywordTag(.validate)) {
        return start + 1 < end and tokens[start + 1].matchesKeywordTag(.constraint);
    }
    if (first.matchesKeyword("attach") or first.matchesKeyword("detach")) {
        return start + 1 < end and tokens[start + 1].matchesKeywordTag(.partition);
    }
    return false;
}

fn generatedAlterTableAlterColumnSegmentUsesRuntimeBoundary(tokens: []const grammar.Token, start: usize, end: usize) bool {
    if (start + 2 >= end) return false;
    var action_index = start + 1;
    if (tokens[action_index].matchesKeywordTag(.column)) action_index += 1;
    if (action_index + 1 >= end) return false;
    action_index += 1;

    if (tokens[action_index].matchesKeywordTag(.type)) return true;
    if (tokens[action_index].matchesKeywordTag(.drop)) {
        return action_index + 1 < end and
            (tokens[action_index + 1].matchesKeywordTag(.default) or
                (action_index + 2 < end and
                    tokens[action_index + 1].matchesKeywordTag(.not) and
                    tokens[action_index + 2].matchesKeywordTag(.null)));
    }
    if (tokens[action_index].matchesKeywordTag(.set)) {
        return action_index + 1 < end and
            (tokens[action_index + 1].matchesKeywordTag(.default) or
                (action_index + 2 < end and
                    tokens[action_index + 1].matchesKeywordTag(.not) and
                    tokens[action_index + 2].matchesKeywordTag(.null)) or
                (action_index + 2 < end and
                    tokens[action_index + 1].matchesKeywordTag(.data) and
                    tokens[action_index + 2].matchesKeywordTag(.type)));
    }
    return false;
}

fn generatedAlterTableAddConstraintKindUsesRuntimeBoundary(token: grammar.Token) bool {
    return token.matchesKeyword("primary") or
        token.matchesKeyword("unique") or
        token.matchesKeyword("foreign") or
        token.matchesKeyword("check");
}

fn generatedAlterTableUsesRowSecurityRuntimeBoundary(tokens: []const grammar.Token, ast: generated_parser.GeneratedSqlDdlAst) bool {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return false;
    if (ast.if_exists) return false;
    const operation_range = ast.alter_table_operation_tokens orelse return false;
    if (!generatedRangeWithinStatement(operation_range, end) or operation_range.start >= operation_range.end) return false;
    if (generatedRangeHasKind(tokens, operation_range, .comma)) return false;
    const enabled = ast.alter_table_row_security_enabled orelse return false;
    return if (enabled)
        generatedRangeMatchesKeywords(tokens, operation_range, &.{ "enable", "row", "level", "security" })
    else
        generatedRangeMatchesKeywords(tokens, operation_range, &.{ "disable", "row", "level", "security" });
}

fn generatedRangeWithinStatement(range: generated_parser.GeneratedSqlTokenRange, end: usize) bool {
    return range.start <= range.end and range.end <= end;
}

fn generatedRangeHasKind(tokens: []const grammar.Token, range: generated_parser.GeneratedSqlTokenRange, kind: token_mod.TokenKind) bool {
    if (range.end > tokens.len or range.start > range.end) return false;
    for (tokens[range.start..range.end]) |token| {
        if (token.kind == kind) return true;
    }
    return false;
}

fn generatedRangeMatchesKeywords(tokens: []const grammar.Token, range: generated_parser.GeneratedSqlTokenRange, keywords: []const []const u8) bool {
    if (range.end > tokens.len or range.start > range.end) return false;
    if (range.end - range.start != keywords.len) return false;
    for (keywords, 0..) |keyword, offset| {
        if (!tokens[range.start + offset].matchesKeyword(keyword)) return false;
    }
    return true;
}

fn generatedRangeHasKeyword(tokens: []const grammar.Token, range: generated_parser.GeneratedSqlTokenRange, keyword: []const u8) bool {
    if (range.end > tokens.len or range.start > range.end) return false;
    for (tokens[range.start..range.end]) |token| {
        if (token.matchesKeyword(keyword)) return true;
    }
    return false;
}

fn generatedRangeContainsText(tokens: []const grammar.Token, range: generated_parser.GeneratedSqlTokenRange, text: []const u8) bool {
    if (range.end > tokens.len or range.start > range.end) return false;
    for (tokens[range.start..range.end]) |token| {
        if (std.ascii.eqlIgnoreCase(token.text, text)) return true;
    }
    return false;
}

pub fn graphDdlPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlGraphAst,
) !LegacyDdlParserPlan {
    try validateGeneratedGraphAstSpans(tokens, ast);
    var plan: LegacyDdlParserPlan = switch (ast.kind) {
        .create_index => .{ .create_index = try createGraphIndexPlanFromGeneratedAstAlloc(alloc, tokens, ast) },
        .create_metric => .{ .create_index = try createGraphMetricPlanFromGeneratedAstAlloc(alloc, tokens, ast) },
        .alter_metric => .{ .create_index = try alterGraphMetricPlanFromGeneratedAstAlloc(alloc, tokens, ast) },
    };
    errdefer plan.deinit(alloc);
    try validateGeneratedGraphPlanMatchesAstAlloc(alloc, tokens, ast, plan);
    return plan;
}

pub fn graphLogicalDdlPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlGraphAst,
) !binder.LogicalSqlPlan {
    try validateGeneratedGraphAstSpans(tokens, ast);
    var create_index: CreateIndexPlan = switch (ast.kind) {
        .create_index => try createGraphIndexPlanFromGeneratedAstAlloc(alloc, tokens, ast),
        .create_metric => try createGraphMetricPlanFromGeneratedAstAlloc(alloc, tokens, ast),
        .alter_metric => try alterGraphMetricPlanFromGeneratedAstAlloc(alloc, tokens, ast),
    };
    errdefer create_index.deinit(alloc);
    try validateGeneratedGraphCreateIndexPlanMatchesAstAlloc(alloc, tokens, ast, create_index);
    return .{ .table_ddl = .{ .create_index = create_index } };
}

fn validateGeneratedGraphAstSpans(
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlGraphAst,
) !void {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    if (tokens[0].source_start != ast.command_span.start or tokens[0].source_end != ast.command_span.end) {
        return error.UnsupportedSqlShape;
    }
    if (end < 2 or !tokens[1].matchesKeywordTag(.graph)) return error.UnsupportedSqlShape;
    try validateGeneratedGraphAstRanges(tokens, end, ast);
}

fn validateGeneratedGraphAstRanges(
    tokens: []const grammar.Token,
    end: usize,
    ast: generated_parser.GeneratedSqlGraphAst,
) !void {
    switch (ast.kind) {
        .create_index, .create_metric => {
            if (end < 6) return error.UnsupportedSqlShape;
            if (!tokens[0].matchesKeywordTag(.create)) return error.UnsupportedSqlShape;
            if (ast.kind == .create_index and !tokens[2].matchesKeywordTag(.index)) return error.UnsupportedSqlShape;
            if (ast.kind == .create_metric and !tokens[2].matchesKeywordTag(.metric)) return error.UnsupportedSqlShape;
            var object_start: usize = 3;
            if (ast.if_not_exists) {
                if (ast.kind != .create_index) return error.UnsupportedSqlShape;
                if (end < 9 or !tokens[3].matchesKeywordTag(.@"if") or !tokens[4].matchesKeywordTag(.not) or !tokens[5].matchesKeywordTag(.exists)) return error.UnsupportedSqlShape;
                object_start = 6;
            }
            _ = try requireGeneratedTokenRangeAt(ast.object_name_tokens, object_start, end);
            const source_range = ast.source_name_tokens orelse return error.UnsupportedSqlShape;
            if (!generatedRangeWithinStatement(source_range, end) or source_range.start == 0 or !tokens[source_range.start - 1].matchesKeywordTag(.on)) {
                return error.UnsupportedSqlShape;
            }
            if (ast.kind == .create_metric) {
                try validateGeneratedGraphNoEdgePayload(ast);
                try validateGeneratedGraphOptions(end, source_range.end, ast.option_tokens);
            } else {
                try validateGeneratedGraphIndexEdgePayload(tokens, end, source_range.end, ast);
            }
        },
        .alter_metric => {
            if (ast.if_not_exists) return error.UnsupportedSqlShape;
            if (end < 8) return error.UnsupportedSqlShape;
            if (!tokens[0].matchesKeywordTag(.alter) or !tokens[2].matchesKeywordTag(.index)) return error.UnsupportedSqlShape;
            _ = try requireGeneratedTokenRangeAt(ast.source_name_tokens, 3, end);
            const metric_range = ast.object_name_tokens orelse return error.UnsupportedSqlShape;
            if (!generatedRangeWithinStatement(metric_range, end) or metric_range.start < 2 or
                !tokens[metric_range.start - 2].matchesKeywordTag(.add) or
                !tokens[metric_range.start - 1].matchesKeywordTag(.metric))
            {
                return error.UnsupportedSqlShape;
            }
            const algorithm_range = ast.algorithm_tokens orelse return error.UnsupportedSqlShape;
            if (!generatedRangeWithinStatement(algorithm_range, end) or algorithm_range.start == 0 or !tokens[algorithm_range.start - 1].matchesKeywordTag(.using)) {
                return error.UnsupportedSqlShape;
            }
            try validateGeneratedGraphOptions(end, algorithm_range.end, ast.option_tokens);
        },
    }
}

fn validateGeneratedGraphOptions(
    end: usize,
    required_end: usize,
    options: ?generated_parser.GeneratedSqlTokenRange,
) !void {
    if (options) |range| {
        if (range.start != required_end or range.end != end or range.start >= range.end) return error.UnsupportedSqlShape;
    } else if (required_end != end) {
        return error.UnsupportedSqlShape;
    }
}

fn validateGeneratedGraphNoEdgePayload(ast: generated_parser.GeneratedSqlGraphAst) !void {
    if (ast.edge_tokens != null or
        ast.edge_source_tokens != null or
        ast.edge_target_tokens != null or
        ast.edge_type_tokens != null or
        ast.edge_weight_tokens != null or
        !generatedGraphExtractionPayloadIsEmpty(ast))
    {
        return error.UnsupportedSqlShape;
    }
}

fn validateGeneratedGraphIndexEdgePayload(
    tokens: []const grammar.Token,
    end: usize,
    source_end: usize,
    ast: generated_parser.GeneratedSqlGraphAst,
) !void {
    if (ast.extraction_enrichment_tokens != null) return validateGeneratedGraphIndexExtractionPayload(tokens, end, source_end, ast);
    const edge = ast.edge_tokens orelse {
        if (ast.edge_source_tokens != null or
            ast.edge_target_tokens != null or
            ast.edge_type_tokens != null or
            ast.edge_weight_tokens != null or
            !generatedGraphExtractionPayloadIsEmpty(ast))
        {
            return error.UnsupportedSqlShape;
        }
        return;
    };
    if (!generatedGraphExtractionPayloadIsEmpty(ast)) return error.UnsupportedSqlShape;
    if (edge.start != source_end or edge.end > end or edge.start + 4 > edge.end) return error.UnsupportedSqlShape;
    if (!tokens[edge.start].matchesKeyword("edge") or tokens[edge.start + 1].kind != .lparen or tokens[edge.end - 1].kind != .rparen) {
        return error.UnsupportedSqlShape;
    }
    const source = ast.edge_source_tokens orelse return error.UnsupportedSqlShape;
    const target = ast.edge_target_tokens orelse return error.UnsupportedSqlShape;
    if (source.start != edge.start + 2 or source.end >= target.start) return error.UnsupportedSqlShape;
    if (target.end != edge.end - 1 or target.start == 0 or tokens[target.start - 1].kind != .arrow_json) return error.UnsupportedSqlShape;
    try validateGeneratedGraphNestedRange(edge, source);
    try validateGeneratedGraphNestedRange(edge, target);
    try validateGeneratedGraphOptionalTailField(edge.end, end, ast.edge_type_tokens);
    try validateGeneratedGraphOptionalTailField(edge.end, end, ast.edge_weight_tokens);
    try validateGeneratedGraphOptions(end, generatedGraphIndexTailEnd(edge.end, ast.edge_type_tokens, ast.edge_weight_tokens), ast.option_tokens);
}

fn validateGeneratedGraphIndexExtractionPayload(
    tokens: []const grammar.Token,
    end: usize,
    source_end: usize,
    ast: generated_parser.GeneratedSqlGraphAst,
) !void {
    if (ast.edge_tokens != null or
        ast.edge_source_tokens != null or
        ast.edge_target_tokens != null or
        ast.edge_type_tokens != null or
        ast.edge_weight_tokens != null)
    {
        return error.UnsupportedSqlShape;
    }
    const enrichment = ast.extraction_enrichment_tokens orelse return error.UnsupportedSqlShape;
    const input = ast.extraction_input_tokens orelse return error.UnsupportedSqlShape;
    const model = ast.extraction_model_tokens orelse return error.UnsupportedSqlShape;
    const path = ast.extraction_edges_path_tokens orelse return error.UnsupportedSqlShape;
    const source = ast.extraction_source_tokens orelse return error.UnsupportedSqlShape;
    const target = ast.extraction_target_tokens orelse return error.UnsupportedSqlShape;
    if (source_end + 2 > enrichment.start) return error.UnsupportedSqlShape;
    if (!tokens[source_end].matchesKeywordTag(.source) or !tokens[source_end + 1].matchesKeyword("enrichment")) return error.UnsupportedSqlShape;
    if (enrichment.end >= input.start or !tokens[input.start - 1].matchesKeywordTag(.from)) return error.UnsupportedSqlShape;
    if (input.end + 3 > model.start) return error.UnsupportedSqlShape;
    if (!tokens[input.end].matchesKeywordTag(.using) or !tokens[input.end + 1].matchesKeyword("extractor") or !tokens[input.end + 2].matchesKeyword("model")) {
        return error.UnsupportedSqlShape;
    }
    if (model.start + 1 != model.end or (tokens[model.start].kind != .string and tokens[model.start].kind != .identifier)) return error.UnsupportedSqlShape;
    if (model.end + 2 > path.start) return error.UnsupportedSqlShape;
    if (!tokens[model.end].matchesKeyword("edges") or !tokens[model.end + 1].matchesKeyword("json_path")) return error.UnsupportedSqlShape;
    if (path.start + 1 != path.end or tokens[path.start].kind != .string) return error.UnsupportedSqlShape;
    if (path.end >= source.start or !tokens[source.start - 1].matchesKeywordTag(.source)) return error.UnsupportedSqlShape;
    if (source.end >= target.start or !tokens[target.start - 1].matchesKeyword("target")) return error.UnsupportedSqlShape;
    try validateGeneratedGraphOptionalTailField(target.end, end, ast.extraction_type_tokens);
    try validateGeneratedGraphOptionalTailField(target.end, end, ast.extraction_weight_tokens);
    try validateGeneratedGraphOptions(end, generatedGraphIndexTailEnd(target.end, ast.extraction_type_tokens, ast.extraction_weight_tokens), ast.option_tokens);
}

fn generatedGraphExtractionPayloadIsEmpty(ast: generated_parser.GeneratedSqlGraphAst) bool {
    return ast.extraction_enrichment_tokens == null and
        ast.extraction_input_tokens == null and
        ast.extraction_model_tokens == null and
        ast.extraction_edges_path_tokens == null and
        ast.extraction_source_tokens == null and
        ast.extraction_target_tokens == null and
        ast.extraction_type_tokens == null and
        ast.extraction_weight_tokens == null;
}

fn validateGeneratedGraphNestedRange(
    outer: generated_parser.GeneratedSqlTokenRange,
    inner: generated_parser.GeneratedSqlTokenRange,
) !void {
    if (inner.start < outer.start or inner.start >= inner.end or inner.end > outer.end) return error.UnsupportedSqlShape;
}

fn validateGeneratedGraphOptionalTailField(
    min_start: usize,
    end: usize,
    range: ?generated_parser.GeneratedSqlTokenRange,
) !void {
    if (range) |value| {
        if (value.start < min_start or value.start >= value.end or value.end > end) return error.UnsupportedSqlShape;
    }
}

fn generatedGraphIndexTailEnd(
    edge_end: usize,
    type_tokens: ?generated_parser.GeneratedSqlTokenRange,
    weight_tokens: ?generated_parser.GeneratedSqlTokenRange,
) usize {
    var tail_end = edge_end;
    if (type_tokens) |value| tail_end = @max(tail_end, value.end);
    if (weight_tokens) |value| tail_end = @max(tail_end, value.end);
    return tail_end;
}

fn createGraphIndexPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlGraphAst,
) !CreateIndexPlan {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    try validateGeneratedGraphIndexEdgePayload(tokens, end, (ast.source_name_tokens orelse return error.UnsupportedSqlShape).end, ast);
    if (ast.extraction_enrichment_tokens != null) return createGraphExtractionIndexPlanFromGeneratedAstAlloc(alloc, tokens, ast, end);

    const index_name = try generatedSqlObjectIdentifierAlloc(alloc, tokens, ast.object_name_tokens orelse return error.UnsupportedSqlShape);
    var index_transferred = false;
    errdefer if (!index_transferred) alloc.free(index_name);

    const table_name = try generatedSqlObjectIdentifierAlloc(alloc, tokens, ast.source_name_tokens orelse return error.UnsupportedSqlShape);
    var table_transferred = false;
    errdefer if (!table_transferred) alloc.free(table_name);

    const source_field = try parseGeneratedDerivedIndexFieldPathRangeAlloc(alloc, tokens, ast.edge_source_tokens orelse return error.UnsupportedSqlShape);
    var source_transferred = false;
    errdefer if (!source_transferred) alloc.free(source_field);

    const target_field = try parseGeneratedDerivedIndexFieldPathRangeAlloc(alloc, tokens, ast.edge_target_tokens orelse return error.UnsupportedSqlShape);
    var target_transferred = false;
    errdefer if (!target_transferred) alloc.free(target_field);

    const type_field = if (ast.edge_type_tokens) |range| try parseGeneratedDerivedIndexFieldPathRangeAlloc(alloc, tokens, range) else null;
