    ast: generated_parser.GeneratedSqlDdlAst,
    options: DdlColumnDefinitionOptions,
) !IdentityAllocatorPlan {
    const end = try requireGeneratedDdlHeader(tokens, ast.statement_span, .create, .table);
    if (ast.if_not_exists) return error.UnsupportedSqlShape;

    var pos: usize = 1;
    var plan = try parseIdentityAllocatorPlanAlloc(alloc, tokens, &pos, options);
    errdefer plan.deinit(alloc);
    if (!generatedStatementConsumedThrough(tokens, end, pos)) return error.UnsupportedSqlShape;
    if (ast.object_name_tokens) |object_name_tokens| {
        const name_range = try requireGeneratedTokenRangeAt(object_name_tokens, 2, end);
        const generated_table_name = try generatedSqlObjectIdentifierAlloc(alloc, tokens, name_range);
        defer alloc.free(@constCast(generated_table_name));
        if (!std.ascii.eqlIgnoreCase(generated_table_name, plan.table_name)) return error.UnsupportedSqlShape;
    }
    return plan;
}

fn createIndexPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    options: CreateIndexOptions,
) !CreateIndexPlan {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    if (end < 4 or !tokens[0].matchesKeywordTag(.create)) return error.UnsupportedSqlShape;

    var index: usize = 1;
    if (ast.unique) {
        if (index >= end or !tokens[index].matchesKeywordTag(.unique)) return error.UnsupportedSqlShape;
        index += 1;
    } else if (index < end and tokens[index].matchesKeywordTag(.unique)) {
        return error.UnsupportedSqlShape;
    }
    const index_keyword = index;
    if (index >= end or !tokens[index].matchesKeywordTag(.index)) return error.UnsupportedSqlShape;
    index += 1;

    if (index < end and tokens[index].matchesKeyword("concurrently")) index += 1;
    if (ast.if_not_exists) try expectGeneratedIfNotExists(tokens, &index, end);
    const name_range = try requireGeneratedTokenRangeAt(ast.object_name_tokens, index, end);
    index = name_range.end;

    if (index >= end or !tokens[index].matchesKeywordTag(.on)) return error.UnsupportedSqlShape;
    index += 1;
    const table_range = ast.index_table_tokens orelse return error.UnsupportedSqlShape;
    if (table_range.start != index or table_range.end <= table_range.start or table_range.end > end) return error.UnsupportedSqlShape;
    index = table_range.end;
    if (table_range.end == table_range.start + 1 and tokens[table_range.start].matchesKeywordTag(.only)) {
        if (index >= end or tokens[index].kind != .identifier) return error.UnsupportedSqlShape;
        index += 1;
    }

    if (index < end and tokens[index].matchesKeywordTag(.using)) {
        index += 1;
        const method_range = try requireGeneratedTokenRangeAt(ast.index_method_tokens, index, end);
        index = method_range.end;
    } else if (ast.index_method_tokens != null) {
        return error.UnsupportedSqlShape;
    }

    if (index >= end or tokens[index].kind != .lparen) return error.UnsupportedSqlShape;
    const elements_close = findGeneratedMatchingParen(tokens, index, end) orelse return error.UnsupportedSqlShape;
    const elements_range = ast.index_elements_tokens orelse {
        var fallback_state = parser_context.ParserState{
            .alloc = alloc,
            .tokens = tokens,
            .pos = index_keyword,
            .schema = options.schema,
            .params = options.params,
            .function_bindings = options.function_bindings,
            .field_expression_qualifiers = options.field_expression_qualifiers,
            .returning_expression_qualifiers = options.returning_expression_qualifiers,
            .defer_row_expression_field_validation = options.defer_row_expression_field_validation,
        };
        return try parseCreateIndexPlanAlloc(alloc, tokens, &fallback_state.pos, ast.unique, parser_context.ParserState.ContextAccessors.createIndexOptions(&fallback_state));
    };
    if (elements_range.start != index + 1 or elements_range.end != elements_close) return error.UnsupportedSqlShape;
    index = elements_close + 1;

    if (index < end and tokens[index].matchesKeywordTag(.nulls)) {
        index += 1;
        if (index < end and tokens[index].matchesKeywordTag(.not)) index += 1;
        if (index >= end or !tokens[index].matchesKeywordTag(.distinct)) return error.UnsupportedSqlShape;
        index += 1;
    }

    if (index < end and tokens[index].matchesKeywordTag(.include)) {
        if (index + 1 >= end or tokens[index + 1].kind != .lparen) return error.UnsupportedSqlShape;
        const include_close = findGeneratedMatchingParen(tokens, index + 1, end) orelse return error.UnsupportedSqlShape;
        const include_range = ast.index_include_tokens orelse return error.UnsupportedSqlShape;
        if (include_range.start != index + 2 or include_range.end != include_close) return error.UnsupportedSqlShape;
        index = include_close + 1;
    } else if (ast.index_include_tokens != null) {
        return error.UnsupportedSqlShape;
    }

    if (index < end and tokens[index].matchesKeywordTag(.with)) {
        if (index + 1 >= end or tokens[index + 1].kind != .lparen) return error.UnsupportedSqlShape;
        const options_close = findGeneratedMatchingParen(tokens, index + 1, end) orelse return error.UnsupportedSqlShape;
        const options_range = ast.index_options_tokens orelse return error.UnsupportedSqlShape;
        if (options_range.start != index or options_range.end != options_close + 1) return error.UnsupportedSqlShape;
        index = options_close + 1;
    } else if (ast.index_options_tokens != null) {
        return error.UnsupportedSqlShape;
    }

    if (index < end and tokens[index].matchesKeywordTag(.where)) {
        const where_range = ast.index_where_tokens orelse return error.UnsupportedSqlShape;
        if (where_range.start != index + 1 or where_range.end != end) return error.UnsupportedSqlShape;
        index = end;
    } else if (ast.index_where_tokens != null) {
        return error.UnsupportedSqlShape;
    }
    if (index != end) return error.UnsupportedSqlShape;

    var state = parser_context.ParserState{
        .alloc = alloc,
        .tokens = tokens,
        .pos = index_keyword,
        .schema = options.schema,
        .params = options.params,
        .function_bindings = options.function_bindings,
        .field_expression_qualifiers = options.field_expression_qualifiers,
        .returning_expression_qualifiers = options.returning_expression_qualifiers,
        .defer_row_expression_field_validation = options.defer_row_expression_field_validation,
    };
    var plan = try parseCreateIndexPlanAlloc(alloc, tokens, &state.pos, ast.unique, parser_context.ParserState.ContextAccessors.createIndexOptions(&state));
    errdefer plan.deinit(alloc);
    if (plan.unique != ast.unique) return error.UnsupportedSqlShape;
    if (!generatedStatementConsumedThrough(tokens, end, state.pos)) return error.UnsupportedSqlShape;
    return plan;
}

fn alterTablePlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    options: DdlColumnDefinitionOptions,
) !AlterTablePlan {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    if (end < 5 or !tokens[0].matchesKeywordTag(.alter) or !tokens[1].matchesKeywordTag(.table)) return error.UnsupportedSqlShape;

    var index: usize = 2;
    if (ast.if_exists) try expectGeneratedIfExists(tokens, &index, end);
    if (index < end and tokens[index].matchesKeywordTag(.only)) index += 1;

    const table_range = ast.object_name_tokens orelse return error.UnsupportedSqlShape;
    if (table_range.start != index or table_range.end <= table_range.start or table_range.end > end) return error.UnsupportedSqlShape;
    index = table_range.end;

    const operation_range = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
    if (operation_range.start != index or operation_range.end != end or operation_range.start >= operation_range.end) return error.UnsupportedSqlShape;
    try validateGeneratedAlterTableOperationItems(tokens, operation_range, &ast.alter_table_operation_items);

    const alter_tokens = tokens[1..end];
    var state = parser_context.ParserState{
        .alloc = alloc,
        .tokens = alter_tokens,
        .schema = options.schema,
        .params = options.params,
        .function_bindings = options.function_bindings,
        .field_expression_qualifiers = options.field_expression_qualifiers,
        .returning_expression_qualifiers = options.returning_expression_qualifiers,
        .defer_row_expression_field_validation = options.defer_row_expression_field_validation,
    };
    var local_options = parser_context.ParserState.ContextAccessors.ddlColumnDefinitionOptions(&state);
    local_options.parse_rewrite_expression = options.parse_rewrite_expression;
    var plan = try parseAlterTablePlanAlloc(alloc, alter_tokens, &state.pos, local_options);
    errdefer plan.deinit(alloc);
    if (plan.if_exists != ast.if_exists) return error.UnsupportedSqlShape;
    if (state.pos != alter_tokens.len) return error.UnsupportedSqlShape;
    return plan;
}

fn advisoryLockPlanFromGeneratedReadAst(
    tokens: []const grammar.Token,
    ast: *const generated_parser.GeneratedSqlReadAst,
) !?AdvisoryLockPlan {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    if (end < 2 or !tokens[0].matchesKeywordTag(.select)) return null;
    if (!tokens[1].matchesKeyword("pg_advisory_lock") and !tokens[1].matchesKeyword("pg_advisory_unlock")) return null;
    if (ast.kind != .query) return error.UnsupportedSqlShape;
    if (tokens[0].source_start != ast.command_span.start or tokens[0].source_end != ast.command_span.end) return error.UnsupportedSqlShape;
    if (ast.cte_tokens != null or ast.source_tokens != null or ast.where_tokens != null or ast.group_tokens != null or ast.having_tokens != null or ast.window_tokens != null or ast.order_tokens != null or ast.limit_tokens != null or ast.offset_tokens != null or ast.fetch_tokens != null or ast.set_operation_tokens != null) {
        return error.UnsupportedSqlShape;
    }
    const projection = ast.projection_tokens orelse return error.UnsupportedSqlShape;
    if (projection.start != 1 or projection.end != end) return error.UnsupportedSqlShape;
    var pos: usize = 1;
    const plan = try parseAdvisoryLockPlanTail(tokens, &pos);
    if (!generatedStatementConsumedThrough(tokens, end, pos)) return error.UnsupportedSqlShape;
    return plan;
}

fn rowSecurityAlterTablePlanFromGeneratedDdlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
) !AlterRowSecurityPlan {
    const end = try requireGeneratedDdlHeader(tokens, ast.statement_span, .alter, .table);
    if (ast.if_exists) return error.UnsupportedSqlShape;

    const table_range = try requireGeneratedTokenRangeAt(ast.object_name_tokens, 2, end);
    const operation_range = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
    if (operation_range.start != table_range.end or operation_range.end != end) return error.UnsupportedSqlShape;
    if (!generatedAlterTableUsesRowSecurityRuntimeBoundary(tokens, ast)) return error.UnsupportedSqlShape;

    var pos: usize = 1;
    var plan = try parseAlterRowSecurityPlanTailAlloc(alloc, tokens, &pos);
    errdefer plan.deinit(alloc);
    if (!generatedStatementConsumedThrough(tokens, end, pos)) return error.UnsupportedSqlShape;

    const generated_table_name = try generatedSqlObjectIdentifierAlloc(alloc, tokens, table_range);
    defer alloc.free(@constCast(generated_table_name));
    if (!std.ascii.eqlIgnoreCase(generated_table_name, plan.table_name)) return error.UnsupportedSqlShape;
    if (ast.alter_table_row_security_enabled != plan.enabled) return error.UnsupportedSqlShape;
    return plan;
}

fn requireGeneratedDdlHeader(
    tokens: []const grammar.Token,
    statement_span: token_mod.SourceSpan,
    first: token_mod.TokenKeyword,
    second: token_mod.TokenKeyword,
) !usize {
    const end = generatedStatementEnd(tokens, statement_span) orelse return error.UnsupportedSqlShape;
    if (end < 3 or !tokens[0].matchesKeywordTag(first) or !tokens[1].matchesKeywordTag(second)) return error.UnsupportedSqlShape;
    return end;
}

fn validateGeneratedDdlAstSpans(
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
) !void {
    _ = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    if (tokens[0].source_start != ast.command_span.start or tokens[0].source_end != ast.command_span.end) {
        return error.UnsupportedSqlShape;
    }
    if (ast.kind == .relation_population) {
        if (!tokens[0].matchesKeywordTag(.select) and !tokens[0].matchesKeywordTag(.create)) return error.UnsupportedSqlShape;
        return;
    }
    const expected: token_mod.TokenKeyword = switch (ast.kind) {
        .create_database,
        .create_schema,
        .create_table,
        .create_view,
        .create_materialized_view,
        .create_domain,
        .create_sequence,
        .create_enum_type,
        .create_tablespace,
        .create_publication,
        .create_subscription,
        .create_policy,
        .create_function,
        .create_procedure,
        .create_role,
        .create_collation,
        .create_operator,
        .create_aggregate,
        .create_cast,
        .create_index,
        .create_extension,
        .create_graph_index,
        .create_graph_metric,
        => .create,
        .relation_population => unreachable,
        .alter_table,
        .alter_database,
        .alter_extension,
        .alter_schema,
        .alter_tablespace,
        .alter_view,
        .alter_domain,
        .alter_sequence,
        .alter_enum_type,
        .alter_publication,
        .alter_subscription,
        .alter_policy,
        .alter_role,
        .alter_collation,
        => .alter,
        .drop_table,
        .drop_view,
        .drop_materialized_view,
        .drop_domain,
        .drop_sequence,
        .drop_enum_type,
        .drop_tablespace,
        .drop_publication,
        .drop_subscription,
        .drop_policy,
        .drop_function,
        .drop_procedure,
        .drop_role,
        .drop_collation,
        .drop_operator,
        .drop_aggregate,
        .drop_cast,
        .drop_index,
        .drop_schema,
        .drop_database,
        .drop_extension,
        => .drop,
        .refresh_materialized_view => .refresh,
    };
    if (!tokens[0].matchesKeywordTag(expected)) return error.UnsupportedSqlShape;
}

fn requireGeneratedTokenRangeAt(
    maybe_range: ?generated_parser.GeneratedSqlTokenRange,
    start: usize,
    end: usize,
) !generated_parser.GeneratedSqlTokenRange {
    const range = maybe_range orelse return error.UnsupportedSqlShape;
    if (range.start != start or range.end != start + 1 or range.end > end) return error.UnsupportedSqlShape;
    return range;
}

fn findGeneratedMatchingParen(tokens: []const grammar.Token, open_index: usize, end: usize) ?usize {
    if (open_index >= end or tokens[open_index].kind != .lparen) return null;
    var depth: usize = 0;
    var index = open_index;
    while (index < end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen => depth += 1,
            .rparen => {
                if (depth == 0) return null;
                depth -= 1;
                if (depth == 0) return index;
            },
            else => {},
        }
    }
    return null;
}

fn expectGeneratedIfNotExists(tokens: []const grammar.Token, index: *usize, end: usize) !void {
    if (index.* + 3 > end or
        !tokens[index.*].matchesKeywordTag(.@"if") or
        !tokens[index.* + 1].matchesKeywordTag(.not) or
        !tokens[index.* + 2].matchesKeywordTag(.exists))
    {
        return error.UnsupportedSqlShape;
    }
    index.* += 3;
}

fn expectGeneratedIfExists(tokens: []const grammar.Token, index: *usize, end: usize) !void {
    if (index.* + 2 > end or
        !tokens[index.*].matchesKeywordTag(.@"if") or
        !tokens[index.* + 1].matchesKeywordTag(.exists))
    {
        return error.UnsupportedSqlShape;
    }
    index.* += 2;
}

fn generatedIdentifierAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    range: generated_parser.GeneratedSqlTokenRange,
) ![]const u8 {
    return try alloc.dupe(u8, try generatedSingleIdentifierText(tokens, range));
}

fn generatedSqlObjectIdentifierAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    range: generated_parser.GeneratedSqlTokenRange,
) ![]const u8 {
    return try grammar.normalizeSqlObjectIdentifierAlloc(alloc, try generatedSingleIdentifierText(tokens, range));
}

fn generatedStringLiteralValueAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    range: generated_parser.GeneratedSqlTokenRange,
) ![]const u8 {
    if (range.end != range.start + 1 or range.end > tokens.len) return error.UnsupportedSqlShape;
    if (tokens[range.start].kind != .string) return error.UnsupportedSqlShape;
    return try alloc.dupe(u8, tokens[range.start].text);
}

fn generatedStatementEnd(tokens: []const grammar.Token, statement_span: token_mod.SourceSpan) ?usize {
    if (tokens.len == 0) return null;
    var end = tokens.len;
    while (end > 0 and tokens[end - 1].kind == .semicolon) end -= 1;
    if (end == 0 or tokens[0].source_start != statement_span.start or tokens[end - 1].source_end != statement_span.end) return null;
    return end;
}

fn generatedStatementTail(tokens: []const grammar.Token, statement_span: token_mod.SourceSpan) ?[]const grammar.Token {
    const end = generatedStatementEnd(tokens, statement_span) orelse return null;
    return tokens[1..end];
}

fn generatedStatementConsumedThrough(tokens: []const grammar.Token, end: usize, pos: usize) bool {
    if (pos == end) return true;
    return end < tokens.len and
        tokens[end].kind == .semicolon and
        pos == end + 1 and
        pos == tokens.len;
}

pub fn closeCursorPortalPlanFromSyntaxAlloc(
    alloc: std.mem.Allocator,
    syntax: grammar.NamedOrAllSyntax,
) !CloseCursorPortalPlan {
    if (syntax.all) return .{ .all = true };
    const portal_name = syntax.name orelse return error.UnsupportedSqlShape;
    return .{ .portal_name = try alloc.dupe(u8, portal_name) };
}

