    return .{
        .name = name,
        .start_column = start_column,
        .end_column = end_column,
    };
}

pub fn parseDdlPeriodConstraintPlanAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
) !runtime_schema.RelationalPeriod {
    var syntax = try grammar.parseDdlPeriodConstraintAlloc(alloc, tokens, pos);
    errdefer syntax.deinit(alloc);
    return ddlPeriodFromSyntax(&syntax);
}

pub fn parseValidatedDdlForeignKeyColumnListAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
) !grammar.DdlForeignKeyColumnListSyntax {
    const columns = try grammar.parseDdlForeignKeyColumnListAlloc(alloc, tokens, pos);
    errdefer columns.deinit(alloc);
    try grammar.validateSqlIdentifierListUnique(columns.columns);
    return columns;
}

pub fn parseDdlForeignKeyConstraintAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    constraint_name: ?[]const u8,
) !runtime_schema.ForeignKey {
    const cursor = parser.Cursor.init(tokens, pos);
    try cursor.expectKeyword("key");
    const child = try parseValidatedDdlForeignKeyColumnListAlloc(alloc, tokens, pos);
    var child_transferred = false;
    errdefer if (!child_transferred) child.deinit(alloc);

    try cursor.expectKeyword("references");
    const parent_table = try grammar.parseSqlObjectIdentifierOwnedAlloc(alloc, tokens, pos);
    var parent_table_transferred = false;
    errdefer if (!parent_table_transferred) alloc.free(parent_table);
    const parent = try parseValidatedDdlForeignKeyColumnListAlloc(alloc, tokens, pos);
    var parent_transferred = false;
    errdefer if (!parent_transferred) parent.deinit(alloc);

    const options = ddlForeignKeyOptionsFromSyntax(try grammar.parseDdlForeignKeyOptions(tokens, pos));
    const foreign_key = try makeDdlForeignKeyAlloc(alloc, constraint_name, child, parent_table, parent, options);

    child_transferred = true;
    parent_table_transferred = true;
    parent_transferred = true;
    return foreign_key;
}

pub fn parseDdlInlineForeignKeyConstraintAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    column_name: []const u8,
    constraint_name: ?[]const u8,
) !runtime_schema.ForeignKey {
    const child_columns = try cloneStringSlice(alloc, &.{column_name});
    var child_transferred = false;
    errdefer if (!child_transferred) freeStringSlice(alloc, child_columns);

    const parent_table = try grammar.parseSqlObjectIdentifierOwnedAlloc(alloc, tokens, pos);
    var parent_table_transferred = false;
    errdefer if (!parent_table_transferred) alloc.free(parent_table);

    const parent_columns = if (parser.peekKind(tokens, pos.*, .lparen))
        try grammar.parseDdlUniqueColumnListAlloc(alloc, tokens, pos)
    else
        try cloneStringSlice(alloc, &.{"id"});
    var parent_transferred = false;
    errdefer if (!parent_transferred) freeStringSlice(alloc, parent_columns);

    const options = ddlForeignKeyOptionsFromSyntax(try grammar.parseDdlForeignKeyOptions(tokens, pos));
    const foreign_key = try makeDdlInlineForeignKeyAlloc(alloc, constraint_name, child_columns, parent_table, parent_columns, options);

    child_transferred = true;
    parent_table_transferred = true;
    parent_transferred = true;
    return foreign_key;
}

pub const DdlRangeColumnDefinition = struct {
    start_column: runtime_schema.RelationalColumn,
    end_column: runtime_schema.RelationalColumn,
    period: runtime_schema.RelationalPeriod,

    pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        freeDdlRelationalColumn(alloc, self.start_column);
        freeDdlRelationalColumn(alloc, self.end_column);
        freeDdlPeriod(alloc, self.period);
        self.* = undefined;
    }
};

pub fn findDdlColumn(columns: []const runtime_schema.RelationalColumn, name: []const u8) ?runtime_schema.RelationalColumn {
    for (columns) |column| {
        if (std.ascii.eqlIgnoreCase(column.name, name)) return column;
    }
    return null;
}

pub fn parseDdlRangeColumnDefinitionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    columns: []const runtime_schema.RelationalColumn,
    periods: []const runtime_schema.RelationalPeriod,
) !DdlRangeColumnDefinition {
    const cursor = parser.Cursor.init(tokens, pos);
    const period_name = try grammar.parseIdentifierOwnedAlloc(alloc, tokens, pos);
    var period_transferred = false;
    errdefer if (!period_transferred) alloc.free(period_name);
    const type_token = cursor.matchToken(.identifier) orelse return error.UnsupportedSqlShape;
    const bound_type = ddlRangeBoundTypeForName(type_token.text) orelse return error.UnsupportedSqlShape;
    const range_type = ddlRangeTypeForName(type_token.text) orelse return error.UnsupportedSqlShape;

    if (findDdlColumn(columns, period_name) != null) return error.UnsupportedSqlShape;
    if (binder.relationalPeriodNameExists(periods, period_name)) return error.UnsupportedSqlShape;

    while (!cursor.atEnd() and !cursor.peekKind(.comma) and !cursor.peekKind(.rparen) and !cursor.peekKind(.semicolon)) {
        if (cursor.matchKeyword("not")) {
            try cursor.expectKeyword("null");
        } else if (cursor.matchKeyword("null")) {} else {
            return error.UnsupportedSqlShape;
        }
    }

    const start_column_name = try std.fmt.allocPrint(alloc, "{s}_start", .{period_name});
    var start_name_transferred = false;
    errdefer if (!start_name_transferred) alloc.free(start_column_name);
    const end_column_name = try std.fmt.allocPrint(alloc, "{s}_end", .{period_name});
    var end_name_transferred = false;
    errdefer if (!end_name_transferred) alloc.free(end_column_name);
    if (findDdlColumn(columns, start_column_name) != null or findDdlColumn(columns, end_column_name) != null) return error.UnsupportedSqlShape;

    const start_path = try alloc.dupe(u8, start_column_name);
    var start_path_transferred = false;
    errdefer if (!start_path_transferred) alloc.free(start_path);
    const end_path = try alloc.dupe(u8, end_column_name);
    var end_path_transferred = false;
    errdefer if (!end_path_transferred) alloc.free(end_path);

    const start_column: runtime_schema.RelationalColumn = .{
        .name = start_column_name,
        .path = start_path,
        .field_type = bound_type,
        .nullable = true,
    };
    var start_column_transferred = false;
    errdefer if (!start_column_transferred) freeDdlRelationalColumn(alloc, start_column);
    const end_column: runtime_schema.RelationalColumn = .{
        .name = end_column_name,
        .path = end_path,
        .field_type = bound_type,
        .nullable = true,
    };
    var end_column_transferred = false;
    errdefer if (!end_column_transferred) freeDdlRelationalColumn(alloc, end_column);
    const period_start = try alloc.dupe(u8, start_column_name);
    var period_start_transferred = false;
    errdefer if (!period_start_transferred) alloc.free(period_start);
    const period_end = try alloc.dupe(u8, end_column_name);
    var period_end_transferred = false;
    errdefer if (!period_end_transferred) alloc.free(period_end);

    period_transferred = true;
    start_name_transferred = true;
    start_path_transferred = true;
    end_name_transferred = true;
    end_path_transferred = true;
    start_column_transferred = true;
    end_column_transferred = true;
    period_start_transferred = true;
    period_end_transferred = true;
    return .{
        .start_column = start_column,
        .end_column = end_column,
        .period = .{
            .name = period_name,
            .start_column = period_start,
            .end_column = period_end,
            .range_type = range_type,
        },
    };
}

pub fn appendDdlRangeColumnDefinitionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    columns: *std.ArrayListUnmanaged(runtime_schema.RelationalColumn),
    periods: *std.ArrayListUnmanaged(runtime_schema.RelationalPeriod),
) !void {
    const definition = try parseDdlRangeColumnDefinitionAlloc(alloc, tokens, pos, columns.items, periods.items);
    var start_transferred = false;
    var end_transferred = false;
    var period_transferred = false;
    errdefer {
        if (!start_transferred) freeDdlRelationalColumn(alloc, definition.start_column);
        if (!end_transferred) freeDdlRelationalColumn(alloc, definition.end_column);
        if (!period_transferred) freeDdlPeriod(alloc, definition.period);
    }
    try columns.append(alloc, definition.start_column);
    start_transferred = true;
    try columns.append(alloc, definition.end_column);
    end_transferred = true;
    try periods.append(alloc, definition.period);
    period_transferred = true;
}

pub fn parseOptionalSupportedDdlCollationAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    field_type: runtime_schema.AntflyType,
    array_item_type: ?runtime_schema.AntflyType,
) !?[]const u8 {
    const collation = try grammar.parseOptionalDdlCollationAlloc(alloc, tokens, pos) orelse return null;
    errdefer alloc.free(collation);
    if (!binder.relationalColumnTypeSupportsCollation(field_type, array_item_type)) return error.UnsupportedSqlShape;
    return collation;
}

pub const DdlColumnDefinitionOptions = struct {
    schema: runtime_schema.TableSchema = .{},
    params: []const value_mod.SqlValue = &.{},
    function_bindings: lower_expr.SqlFunctionBindings = .{},
    field_expression_qualifiers: []const []const u8 = &.{},
    returning_expression_qualifiers: []const []const u8 = &.{},
    defer_row_expression_field_validation: bool = false,
    expression_options: DdlExpressionOptions,
    parse_rewrite_expression: bool = true,
};

pub const DdlDomainOptions = struct {
    params: []const value_mod.SqlValue = &.{},
    realtime_ns: u64,
};

pub const DdlExpressionOptions = struct {
    params: []const value_mod.SqlValue = &.{},
    realtime_ns: u64,
    function_bindings: lower_expr.SqlFunctionBindings = .{},
    context_hooks: lower_expr.SelectParserContextHooks,
    row_expression_hooks: lower_expr.RowExpressionParserHooks,
    arithmetic_hooks: lower_expr.ArithmeticExpressionParserHooks,
    variadic_hooks: lower_expr.VariadicRowExpressionParserHooks,
    routine_expression: lower_expr.RoutineExpressionRowExpressionParserOptions,
    condition_alternatives: lower_expr.ExpressionWhereConditionAlternativesParserOptions,
};

fn parseDdlDefaultValueWithParamsAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    field_type: runtime_schema.AntflyType,
    params: []const value_mod.SqlValue,
    realtime_ns: u64,
) !runtime_schema.RelationalDefaultValue {
    if (try grammar.parseOptionalDdlKnownDefault(tokens, pos)) |known| {
        return try grammar.ddlDefaultValueFromKnownSyntaxAlloc(alloc, known, field_type);
    }
    const value = try value_mod.parseSqlColumnValueAlloc(alloc, tokens, pos, params, .{ .name = "", .path = "", .field_type = field_type }, realtime_ns);
    return .{ .kind = .literal, .value_json = value };
}

pub fn parseDdlDefaultValueAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    field_type: runtime_schema.AntflyType,
    options: DdlExpressionOptions,
) !runtime_schema.RelationalDefaultValue {
    return try parseDdlDefaultValueWithParamsAlloc(alloc, tokens, pos, field_type, options.params, options.realtime_ns);
}

fn parseDdlRowExpressionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    options: DdlExpressionOptions,
    require_routine_expression_binding: bool,
) !db_mod.types.RelationalRowsExpression {
    return try lower_expr.parseRowExpressionWithDeferredFieldValidationAlloc(
        alloc,
        tokens,
        pos,
        .{
            .function_bindings = options.function_bindings,
            .require_routine_expression_binding = require_routine_expression_binding,
            .context_hooks = options.context_hooks,
            .row_expression_hooks = options.row_expression_hooks,
            .arithmetic_hooks = options.arithmetic_hooks,
            .variadic_hooks = options.variadic_hooks,
        },
    );
}

fn parseDdlRoutineRowExpressionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    options: DdlExpressionOptions,
) !db_mod.types.RelationalRowsExpression {
    if (!lower_expr.peekRoutineExpressionCall(tokens, pos.*, options.function_bindings.routine_expressions)) return error.UnsupportedSqlShape;
    const name = tokens[pos.*].text;
    _ = parser.matchToken(tokens, pos, .identifier) orelse return error.UnsupportedSqlShape;
    try parser.expectToken(tokens, pos, .lparen);
    var operands = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpression).empty;
    defer {
        for (operands.items) |operand| runtime_schema.freeRelationalRowsExpression(alloc, operand);
        operands.deinit(alloc);
    }
    if (parser.matchToken(tokens, pos, .rparen) == null) {
        while (true) {
            const arg_start = pos.*;
            const arg_end = ddlRoutineArgumentEnd(tokens, arg_start) orelse return error.UnsupportedSqlShape;
            const operand = try parseDdlRoutineArgumentExpressionAlloc(alloc, tokens[arg_start..arg_end], options);
            var operand_transferred = false;
            errdefer if (!operand_transferred) runtime_schema.freeRelationalRowsExpression(alloc, operand);
            try operands.append(alloc, operand);
            operand_transferred = true;
            pos.* = arg_end;
            if (parser.matchToken(tokens, pos, .comma) != null) continue;
            break;
        }
        try parser.expectToken(tokens, pos, .rparen);
    }
    const binding = try lower_expr.routineExpressionBinding(options.function_bindings.routine_expressions, name, operands.items.len) orelse return error.UnsupportedSqlShape;
    if (binding.null_input == .returns_null) {
        for (operands.items) |operand| {
            if (lower_expr.routineArgumentExpressionIsNullLiteral(operand)) {
                return .{
                    .kind = .value,
                    .value_json = try alloc.dupe(u8, "null"),
                };
            }
        }
        return error.UnsupportedSqlShape;
    }
    return try lower_expr.cloneExpressionSubstitutingRoutineArgsAlloc(alloc, binding.expression, operands.items);
}

fn parseDdlRoutineArgumentExpressionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    options: DdlExpressionOptions,
) !db_mod.types.RelationalRowsExpression {
    var arg_pos: usize = 0;
    if (parseDdlRowExpressionAlloc(alloc, tokens, &arg_pos, options, false)) |expression| {
        if (arg_pos == tokens.len) return expression;
        runtime_schema.freeRelationalRowsExpression(alloc, expression);
    } else |err| switch (err) {
        error.UnsupportedSqlShape, error.InvalidSqlCatalog => {},
        else => return err,
    }

    if (tokens.len == 1 and tokens[0].kind == .identifier and
        !tokens[0].matchesKeywordTag(.null) and
        !tokens[0].matchesKeywordTag(.true) and
        !tokens[0].matchesKeywordTag(.false))
    {
        return .{
            .kind = .field,
            .field = try alloc.dupe(u8, tokens[0].text),
        };
    }

    arg_pos = 0;
    return .{
        .kind = .value,
        .value_json = try value_mod.parseJsonValueAlloc(alloc, tokens, &arg_pos, options.params),
    };
}

fn ddlRoutineArgumentEnd(tokens: []const grammar.Token, start: usize) ?usize {
    var depth: usize = 0;
    var index = start;
    while (index < tokens.len) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen => depth += 1,
            .rparen => {
                if (depth == 0) return index;
                depth -= 1;
            },
            .comma => if (depth == 0) return index,
            else => {},
        }
    }
    return null;
}

fn parseDdlConditionAlternativesAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    alternatives: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
    options: DdlExpressionOptions,
) !void {
    return try lower_expr.parseExpressionWhereConditionAlternativesWithDeferredFieldValidationAlloc(
        alloc,
        tokens,
        pos,
        alternatives,
        .{
            .params = options.params,
            .context_hooks = options.context_hooks,
            .alternatives_hooks = options.condition_alternatives,
        },
    );
}

pub fn parseDdlGeneratedValueAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    options: DdlExpressionOptions,
) !runtime_schema.RelationalGeneratedValue {
    const cursor = parser.Cursor.init(tokens, pos);
    const start = pos.*;
    if (cursor.matchKeyword("always")) {
        try cursor.expectKeyword("as");
        try cursor.expectToken(.lparen);
        const expression = (if (lower_expr.peekRoutineExpressionCall(tokens, pos.*, options.function_bindings.routine_expressions))
            parseDdlRoutineRowExpressionAlloc(alloc, tokens, pos, options)
        else
            parseDdlRowExpressionAlloc(alloc, tokens, pos, options, true)) catch |err| {
            pos.* = start;
            if (err == error.OutOfMemory) return err;
            return try grammar.parseDdlStoredGeneratedValueAlloc(alloc, tokens, pos);
        };
        var expression_transferred = false;
        errdefer if (!expression_transferred) runtime_schema.freeRelationalRowsExpression(alloc, expression);
        try cursor.expectToken(.rparen);
        try cursor.expectKeyword("stored");
        expression_transferred = true;
        return .{
            .op = .expression,
            .expression = expression,
        };
    }
    pos.* = start;
    return try grammar.parseDdlStoredGeneratedValueAlloc(alloc, tokens, pos);
}

pub fn parseDdlCheckConstraintAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    constraint_name: ?[]const u8,
    options: DdlExpressionOptions,
) !runtime_schema.RelationalCheck {
    const cursor = parser.Cursor.init(tokens, pos);
    try cursor.expectToken(.lparen);
    const condition = try parseDdlCheckExpressionConditionAlloc(alloc, tokens, pos, options);
    defer runtime_schema.freeRelationalRowsExpressionCondition(alloc, condition);
    try cursor.expectToken(.rparen);
    return try makeDdlRelationalCheckFromExpressionConditionAlloc(alloc, constraint_name, condition);
}

pub fn parseDdlCheckExpressionConditionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    options: DdlExpressionOptions,
) !db_mod.types.RelationalRowsExpressionCondition {
    var groups = try parseDdlCheckExpressionPredicateGroupsAlloc(alloc, tokens, pos, options);
    defer alloc.free(groups);
    errdefer plan_mod.freeExpressionPredicateGroups(alloc, groups);

    if (groups.len == 1 and groups[0].conditions.len == 1) {
        const conditions = groups[0].conditions;
        const condition = conditions[0];
        groups[0].conditions = &.{};
        alloc.free(conditions);
        return condition;
    }

    const expression = try lower_expr.booleanExpressionFromPredicateGroupsAlloc(alloc, groups);
    var expression_transferred = false;
    errdefer if (!expression_transferred) runtime_schema.freeRelationalRowsExpression(alloc, expression);

    const rhs = try alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
    var rhs_transferred = false;
    errdefer if (!rhs_transferred) alloc.free(rhs);
    rhs[0] = try lower_expr.booleanLiteralExpressionAlloc(alloc, true);
    var rhs_expression_transferred = false;
    errdefer if (!rhs_expression_transferred) runtime_schema.freeRelationalRowsExpression(alloc, rhs[0]);

    expression_transferred = true;
    rhs_expression_transferred = true;
    rhs_transferred = true;
    return .{
        .lhs = expression,
        .op = .eq,
        .rhs = rhs,
    };
}

pub fn parseDdlCheckExpressionPredicateGroupsAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    options: DdlExpressionOptions,
) anyerror![]db_mod.types.RelationalRowsExpressionPredicateGroup {
    const cursor = parser.Cursor.init(tokens, pos);
    var groups = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        plan_mod.freeExpressionPredicateGroups(alloc, groups.items);
        groups.deinit(alloc);
    }

    while (true) {
        var branch_groups = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
        var branch_groups_transferred = false;
        defer branch_groups.deinit(alloc);
        errdefer if (!branch_groups_transferred) plan_mod.freeExpressionPredicateGroups(alloc, branch_groups.items);
        try branch_groups.append(alloc, .{ .conditions = &.{} });

        while (true) {
            var alternatives = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
            defer alternatives.deinit(alloc);
            errdefer plan_mod.freeExpressionPredicateGroups(alloc, alternatives.items);
            try parseDdlCheckExpressionPredicateFactorAlternatives(alloc, tokens, pos, options, &alternatives);
            try andExpressionPredicateAlternatives(alloc, &branch_groups, alternatives.items);
            plan_mod.freeExpressionPredicateGroups(alloc, alternatives.items);
            if (!cursor.matchKeyword("and")) break;
        }

        if (branch_groups.items.len == 0) return error.UnsupportedSqlShape;
        try groups.appendSlice(alloc, branch_groups.items);
        branch_groups_transferred = true;

        if (!cursor.matchKeyword("or")) break;
    }

    return try groups.toOwnedSlice(alloc);
}

fn parseDdlCheckExpressionPredicateFactorAlternatives(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    options: DdlExpressionOptions,
    alternatives: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
) anyerror!void {
    const cursor = parser.Cursor.init(tokens, pos);
    if (cursor.matchKeyword("not")) {
        const groups = try parseDdlCheckNegatedPredicateGroupsAlloc(alloc, tokens, pos, options);
        defer alloc.free(groups);
        errdefer plan_mod.freeExpressionPredicateGroups(alloc, groups);

        const expression = try lower_expr.booleanExpressionFromPredicateGroupsAlloc(alloc, groups);
        var expression_transferred = false;
        errdefer if (!expression_transferred) runtime_schema.freeRelationalRowsExpression(alloc, expression);
        const negated = try lower_expr.booleanNotExpressionAlloc(alloc, expression);
        expression_transferred = true;
        var negated_transferred = false;
        errdefer if (!negated_transferred) runtime_schema.freeRelationalRowsExpression(alloc, negated);
        const condition = try lower_expr.booleanExpressionConditionAlloc(alloc, negated);
        negated_transferred = true;
        try lower_expr.appendExpressionConditionGroup(alloc, alternatives, condition);
        return;
    }

    if (expr_token.parenthesizedPredicateGroupCanStartAt(tokens, pos.*)) {
        try cursor.expectToken(.lparen);
        const groups = try parseDdlCheckExpressionPredicateGroupsAlloc(alloc, tokens, pos, options);
        var groups_transferred = false;
        defer alloc.free(groups);
        errdefer if (!groups_transferred) plan_mod.freeExpressionPredicateGroups(alloc, groups);
        try cursor.expectToken(.rparen);
        try alternatives.appendSlice(alloc, groups);
        groups_transferred = true;
        return;
    }

    if (try parseDdlRoutineExpressionConditionAlternativesAlloc(alloc, tokens, pos, options, alternatives)) return;

    try parseDdlConditionAlternativesAlloc(alloc, tokens, pos, alternatives, options);
}

fn parseDdlRoutineExpressionConditionAlternativesAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    options: DdlExpressionOptions,
    alternatives: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
) !bool {
    if (!lower_expr.peekRoutineExpressionCall(tokens, pos.*, options.function_bindings.routine_expressions)) return false;

    const lhs = try parseDdlRoutineRowExpressionAlloc(alloc, tokens, pos, options);
    var lhs_transferred = false;
    errdefer if (!lhs_transferred) runtime_schema.freeRelationalRowsExpression(alloc, lhs);

    const op = try expr_operator.parseComparisonOp(tokens, pos);
    const rhs = switch (op) {
        .is_null, .is_not_null => &.{},
        else => blk: {
            const out = try alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
            var out_transferred = false;
            errdefer if (!out_transferred) alloc.free(out);
            const rhs_start = pos.*;
            out[0] = (if (lower_expr.peekRoutineExpressionCall(tokens, pos.*, options.function_bindings.routine_expressions))
                parseDdlRoutineRowExpressionAlloc(alloc, tokens, pos, options)
            else
                parseDdlRowExpressionAlloc(alloc, tokens, pos, options, false)) catch |err| switch (err) {
                error.UnsupportedSqlShape => blk_value: {
                    pos.* = rhs_start;
                    break :blk_value .{
                        .kind = .value,
                        .value_json = try value_mod.parseJsonValueAlloc(alloc, tokens, pos, options.params),
                    };
                },
                else => return err,
            };
            var rhs_expression_transferred = false;
            errdefer if (!rhs_expression_transferred) runtime_schema.freeRelationalRowsExpression(alloc, out[0]);
            rhs_expression_transferred = true;
            out_transferred = true;
            break :blk out;
        },
    };
    var rhs_transferred = false;
    errdefer if (!rhs_transferred and rhs.len > 0) {
        for (rhs) |expression| runtime_schema.freeRelationalRowsExpression(alloc, expression);
        alloc.free(rhs);
    };

    const condition: db_mod.types.RelationalRowsExpressionCondition = .{
        .lhs = lhs,
        .op = op,
        .rhs = rhs,
    };
    lhs_transferred = true;
    rhs_transferred = true;
    try lower_expr.appendExpressionConditionGroup(alloc, alternatives, condition);
    return true;
}

fn parseDdlCheckNegatedPredicateGroupsAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    options: DdlExpressionOptions,
) anyerror![]db_mod.types.RelationalRowsExpressionPredicateGroup {
    const cursor = parser.Cursor.init(tokens, pos);
    if (expr_token.parenthesizedPredicateGroupCanStartAt(tokens, pos.*)) {
        try cursor.expectToken(.lparen);
        const groups = try parseDdlCheckExpressionPredicateGroupsAlloc(alloc, tokens, pos, options);
        errdefer {
            plan_mod.freeExpressionPredicateGroups(alloc, groups);
            alloc.free(groups);
        }
        try cursor.expectToken(.rparen);
        return groups;
    }

    var groups = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        plan_mod.freeExpressionPredicateGroups(alloc, groups.items);
        groups.deinit(alloc);
    }
    try parseDdlConditionAlternativesAlloc(alloc, tokens, pos, &groups, options);
    return try groups.toOwnedSlice(alloc);
}

fn andExpressionPredicateAlternatives(
    alloc: std.mem.Allocator,
    groups: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
    alternatives: []const db_mod.types.RelationalRowsExpressionPredicateGroup,
) !void {
    if (groups.items.len == 0 or alternatives.len == 0) return error.UnsupportedSqlShape;
    var combined = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    var combined_transferred = false;
    errdefer {
        if (!combined_transferred) plan_mod.freeExpressionPredicateGroups(alloc, combined.items);
        combined.deinit(alloc);
    }

    for (groups.items) |base| {
        for (alternatives) |alternative| {
            const conditions = try plan_mod.cloneExpressionConditionsConcatAlloc(alloc, base.conditions, alternative.conditions);
            var conditions_transferred = false;
            errdefer if (!conditions_transferred) {
                freeExpressionConditions(alloc, conditions);
                if (conditions.len > 0) alloc.free(conditions);
            };
            try combined.append(alloc, .{ .conditions = conditions });
            conditions_transferred = true;
        }
    }

    plan_mod.freeExpressionPredicateGroups(alloc, groups.items);
    groups.deinit(alloc);
    groups.* = combined;
    combined_transferred = true;
}

pub fn parseDomainCheckConstraintAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    constraint_name: ?[]const u8,
    field_type: runtime_schema.AntflyType,
    options: DdlDomainOptions,
) !runtime_schema.RelationalCheck {
    const cursor = parser.Cursor.init(tokens, pos);
    try cursor.expectToken(.lparen);
    const value_token = cursor.matchToken(.identifier) orelse return error.UnsupportedSqlShape;
    if (!std.ascii.eqlIgnoreCase(value_token.text, "value")) return error.UnsupportedSqlShape;
    const op = try expr_operator.parseComparisonOp(tokens, pos);
    const value_json = if (op == .is_null or op == .is_not_null)
        null
    else
        try value_mod.parseSqlColumnValueAlloc(alloc, tokens, pos, options.params, .{ .name = "VALUE", .path = "VALUE", .field_type = field_type }, options.realtime_ns);
    var value_transferred = false;
    errdefer if (!value_transferred) if (value_json) |value| alloc.free(value);
    try cursor.expectToken(.rparen);
    const name = if (constraint_name) |name|
        try alloc.dupe(u8, name)
    else
        try std.fmt.allocPrint(alloc, "domain_value_{s}_check", .{relationalCheckOpToken(op)});
    var name_transferred = false;
    errdefer if (!name_transferred) alloc.free(name);
    const field = try alloc.dupe(u8, "VALUE");
    var field_transferred = false;
    errdefer if (!field_transferred) alloc.free(field);
    name_transferred = true;
    field_transferred = true;
    value_transferred = true;
    return .{ .name = name, .field = field, .op = op, .value_json = value_json };
}

pub fn parseCreateDomainPlanAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    options: DdlDomainOptions,
) !CreateDomainPlan {
    const cursor = parser.Cursor.init(tokens, pos);
    var header = try grammar.parseCreateDomainHeaderAlloc(alloc, tokens, pos);
    var header_transferred = false;
    errdefer if (!header_transferred) header.deinit(alloc);
    const ddl_type = try grammar.parseDdlType(tokens, pos);
    var not_null = false;
    var default_value: ?runtime_schema.RelationalDefaultValue = null;
    errdefer if (default_value) |default| alloc.free(default.value_json);
    var checks = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    errdefer {
        clearDdlRelationalChecks(alloc, checks.items);
        checks.deinit(alloc);
    }
    while (!cursor.atEnd() and !cursor.peekKind(.semicolon)) {
        if (cursor.matchKeyword("default")) {
            if (default_value != null) return error.UnsupportedSqlShape;
            default_value = try parseDdlDefaultValueWithParamsAlloc(alloc, tokens, pos, ddl_type.field_type, options.params, options.realtime_ns);
        } else if (cursor.matchKeyword("not")) {
            try cursor.expectKeyword("null");
            not_null = true;
        } else if (cursor.matchKeyword("null")) {
            not_null = false;
        } else if (cursor.matchKeyword("constraint")) {
            const constraint_name = try grammar.parseIdentifierOwnedAlloc(alloc, tokens, pos);
            defer alloc.free(constraint_name);
            const check = try parseDomainCheckConstraintAlloc(alloc, tokens, pos, constraint_name, ddl_type.field_type, options);
            var check_transferred = false;
            errdefer if (!check_transferred) freeDdlRelationalCheck(alloc, check);
            try checks.append(alloc, check);
            check_transferred = true;
        } else if (cursor.matchKeyword("check")) {
            const check = try parseDomainCheckConstraintAlloc(alloc, tokens, pos, null, ddl_type.field_type, options);
            var check_transferred = false;
            errdefer if (!check_transferred) freeDdlRelationalCheck(alloc, check);
            try checks.append(alloc, check);
            check_transferred = true;
        } else {
            return error.UnsupportedSqlShape;
        }
    }
    try grammar.parseAdapterNoopStatementEnd(tokens, pos);
    const owned_checks = try checks.toOwnedSlice(alloc);
    var checks_transferred = false;
    errdefer if (!checks_transferred) freeDdlRelationalChecks(alloc, owned_checks);
    const out_default = default_value;
    default_value = null;
    header_transferred = true;
    checks_transferred = true;
    return .{
        .domain_name = header.domain_name,
        .field_type = ddl_type.field_type,
        .array_item_type = ddl_type.array_item_type,
        .not_null = not_null,
        .default_value = out_default,
        .checks = owned_checks,
    };
}

pub fn parseDdlColumnDefinitionStandaloneAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    hooks: DdlColumnDefinitionOptions,
) !runtime_schema.RelationalColumn {
    const cursor = parser.Cursor.init(tokens, pos);
    const name = try grammar.parseIdentifierOwnedAlloc(alloc, tokens, pos);
    var name_transferred = false;
    errdefer if (!name_transferred) alloc.free(name);

    const ddl_type = try grammar.parseDdlType(tokens, pos);
    const path = try alloc.dupe(u8, name);
    var path_transferred = false;
    errdefer if (!path_transferred) alloc.free(path);
    var column: runtime_schema.RelationalColumn = .{
        .name = name,
        .path = path,
        .field_type = ddl_type.field_type,
        .array_item_type = ddl_type.array_item_type,
        .nullable = true,
    };
    var column_transferred = false;
    errdefer if (!column_transferred) freeDdlRelationalColumn(alloc, column);
    name_transferred = true;
    path_transferred = true;

    while (!cursor.atEnd() and !cursor.peekKind(.comma) and !cursor.peekKind(.rparen) and !cursor.peekKind(.semicolon) and !cursor.peekKeyword("primary") and !cursor.peekKeyword("unique") and !cursor.peekKeyword("check") and !cursor.peekKeyword("references") and !cursor.peekKeyword("constraint")) {
        if (try parseOptionalSupportedDdlCollationAlloc(alloc, tokens, pos, column.field_type, column.array_item_type)) |collation| {
            if (column.collation != null) {
                alloc.free(collation);
                return error.UnsupportedSqlShape;
            }
            column.collation = collation;
            continue;
        } else if (cursor.matchKeyword("not")) {
            try cursor.expectKeyword("null");
            column.nullable = false;
        } else if (cursor.matchKeyword("null")) {
            column.nullable = true;
        } else if (cursor.matchKeyword("default")) {
            if (column.default_value != null) return error.UnsupportedSqlShape;
            if (column.generated != null) return error.UnsupportedSqlShape;
            column.default_value = try parseDdlDefaultValueAlloc(alloc, tokens, pos, column.field_type, hooks.expression_options);
        } else if (cursor.matchKeyword("generated")) {
            if (column.default_value != null or column.generated != null) return error.UnsupportedSqlShape;
            column.generated = try parseDdlGeneratedValueAlloc(alloc, tokens, pos, hooks.expression_options);
        } else {
            return error.UnsupportedSqlShape;
        }
    }

    column_transferred = true;
    return column;
}

pub fn parseDdlColumnDefinitionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    hooks: DdlColumnDefinitionOptions,
    columns: *std.ArrayListUnmanaged(runtime_schema.RelationalColumn),
    periods: *std.ArrayListUnmanaged(runtime_schema.RelationalPeriod),
    primary_key: *?runtime_schema.PrimaryKey,
    unique_constraints: *std.ArrayListUnmanaged(runtime_schema.UniqueConstraint),
    foreign_keys: *std.ArrayListUnmanaged(runtime_schema.ForeignKey),
    checks: *std.ArrayListUnmanaged(runtime_schema.RelationalCheck),
) !void {
    const cursor = parser.Cursor.init(tokens, pos);
    if (grammar.peekDdlRangeColumnDefinition(tokens, pos.*)) {
        try appendDdlRangeColumnDefinitionAlloc(alloc, tokens, pos, columns, periods);
        return;
    }

    var column = try parseDdlColumnDefinitionStandaloneAlloc(alloc, tokens, pos, hooks);
    var column_transferred = false;
    errdefer if (!column_transferred) freeDdlRelationalColumn(alloc, column);
    if (findDdlColumn(columns.items, column.name) != null) return error.UnsupportedSqlShape;
    while (!cursor.atEnd() and !cursor.peekKind(.comma) and !cursor.peekKind(.rparen) and !cursor.peekKind(.semicolon)) {
        if (try parseOptionalSupportedDdlCollationAlloc(alloc, tokens, pos, column.field_type, column.array_item_type)) |collation| {
            if (column.collation != null) {
                alloc.free(collation);
                return error.UnsupportedSqlShape;
            }
            column.collation = collation;
            continue;
        } else if (cursor.matchKeyword("not")) {
            try cursor.expectKeyword("null");
            column.nullable = false;
        } else if (cursor.matchKeyword("null")) {
            column.nullable = true;
        } else if (cursor.matchKeyword("default")) {
            if (column.default_value != null) return error.UnsupportedSqlShape;
            if (column.generated != null) return error.UnsupportedSqlShape;
            column.default_value = try parseDdlDefaultValueAlloc(alloc, tokens, pos, column.field_type, hooks.expression_options);
        } else if (cursor.matchKeyword("generated")) {
            if (column.default_value != null or column.generated != null) return error.UnsupportedSqlShape;
            column.generated = try parseDdlGeneratedValueAlloc(alloc, tokens, pos, hooks.expression_options);
        } else {
            var constraint_prefix = try grammar.parseCreateTableColumnConstraintPrefixAlloc(alloc, tokens, pos);
            defer constraint_prefix.deinit(alloc);
            const constraint_name = constraint_prefix.constraint_name;
            if (constraint_prefix.kind == .primary_key and cursor.matchKeyword("primary")) {
                try cursor.expectKeyword("key");
                column.nullable = false;
                const include_columns = try grammar.parseOptionalDdlConstraintIncludeUniqueAlloc(alloc, tokens, pos, &.{column.name});
                defer freeStringSlice(alloc, include_columns);
                const timing = try grammar.parseOptionalDdlConstraintTiming(tokens, pos);
                try installDdlPrimaryKeyAlloc(alloc, primary_key, constraint_name, &.{column.name}, include_columns, null, timing);
            } else if (constraint_prefix.kind == .unique and cursor.matchKeyword("unique")) {
                const nulls_not_distinct = (try grammar.parseOptionalDdlUniqueNullsDistinct(tokens, pos)) orelse false;
                const include_columns = try grammar.parseOptionalDdlConstraintIncludeUniqueAlloc(alloc, tokens, pos, &.{column.name});
                defer freeStringSlice(alloc, include_columns);
                const timing = try grammar.parseOptionalDdlConstraintTiming(tokens, pos);
                try appendDdlUniqueConstraintBuilderAlloc(alloc, unique_constraints, constraint_name, &.{column.name}, include_columns, null, nulls_not_distinct, timing);
            } else if (constraint_prefix.kind == .check and cursor.matchKeyword("check")) {
                const check = try parseDdlCheckConstraintAlloc(alloc, tokens, pos, constraint_name, hooks.expression_options);
                var check_transferred = false;
                errdefer if (!check_transferred) freeDdlRelationalCheck(alloc, check);
                try checks.append(alloc, check);
                check_transferred = true;
            } else if (constraint_prefix.kind == .references and cursor.matchKeyword("references")) {
                const foreign_key = try parseDdlInlineForeignKeyConstraintAlloc(alloc, tokens, pos, column.name, constraint_name);
                var foreign_key_transferred = false;
                errdefer if (!foreign_key_transferred) freeDdlForeignKey(alloc, foreign_key);
                try foreign_keys.append(alloc, foreign_key);
                foreign_key_transferred = true;
            } else {
                return error.UnsupportedSqlShape;
            }
        }
    }

    try columns.append(alloc, column);
    column_transferred = true;
}

pub fn parseDdlTableConstraintAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    hooks: DdlColumnDefinitionOptions,
    constraint_name: ?[]const u8,
    primary_key: *?runtime_schema.PrimaryKey,
    periods: *std.ArrayListUnmanaged(runtime_schema.RelationalPeriod),
    unique_constraints: *std.ArrayListUnmanaged(runtime_schema.UniqueConstraint),
    foreign_keys: *std.ArrayListUnmanaged(runtime_schema.ForeignKey),
    checks: *std.ArrayListUnmanaged(runtime_schema.RelationalCheck),
) !void {
    const cursor = parser.Cursor.init(tokens, pos);
    if (cursor.matchKeyword("primary")) {
        try cursor.expectKeyword("key");
        const columns = try grammar.parseDdlUniqueTemporalColumnListAlloc(alloc, tokens, pos);
        defer columns.deinit(alloc);
        const include_columns = try grammar.parseOptionalDdlConstraintIncludeUniqueAlloc(alloc, tokens, pos, columns.columns);
        defer freeStringSlice(alloc, include_columns);
        const timing = try grammar.parseOptionalDdlConstraintTiming(tokens, pos);
        try installDdlPrimaryKeyAlloc(alloc, primary_key, constraint_name, columns.columns, include_columns, columns.without_overlaps_period, timing);
    } else if (cursor.matchKeyword("unique")) {
        const nulls_not_distinct = (try grammar.parseOptionalDdlUniqueNullsDistinct(tokens, pos)) orelse false;
        const columns = try grammar.parseDdlUniqueTemporalColumnListAlloc(alloc, tokens, pos);
        defer columns.deinit(alloc);
        const include_columns = try grammar.parseOptionalDdlConstraintIncludeUniqueAlloc(alloc, tokens, pos, columns.columns);
        defer freeStringSlice(alloc, include_columns);
        const timing = try grammar.parseOptionalDdlConstraintTiming(tokens, pos);
        try appendDdlUniqueConstraintBuilderAlloc(alloc, unique_constraints, constraint_name, columns.columns, include_columns, columns.without_overlaps_period, nulls_not_distinct, timing);
    } else if (cursor.matchKeyword("foreign")) {
        const foreign_key = try parseDdlForeignKeyConstraintAlloc(alloc, tokens, pos, constraint_name);
        var transferred = false;
        errdefer if (!transferred) freeDdlForeignKey(alloc, foreign_key);
        try foreign_keys.append(alloc, foreign_key);
        transferred = true;
    } else if (cursor.matchKeyword("check")) {
        const check = try parseDdlCheckConstraintAlloc(alloc, tokens, pos, constraint_name, hooks.expression_options);
        var transferred = false;
        errdefer if (!transferred) freeDdlRelationalCheck(alloc, check);
        try checks.append(alloc, check);
        transferred = true;
    } else if (cursor.matchKeyword("period")) {
        if (constraint_name != null) return error.UnsupportedSqlShape;
        const period = try parseDdlPeriodConstraintPlanAlloc(alloc, tokens, pos);
        var transferred = false;
        errdefer if (!transferred) freeDdlPeriod(alloc, period);
        try periods.append(alloc, period);
        transferred = true;
    } else {
        return error.UnsupportedSqlShape;
    }
}

pub fn parseCreateTableDefinitionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    hooks: DdlColumnDefinitionOptions,
) !CreateTablePlan {
    const cursor = parser.Cursor.init(tokens, pos);
    var header = try grammar.parseCreateTableDefinitionHeaderAlloc(alloc, tokens, pos);
    var header_transferred = false;
    errdefer if (!header_transferred) header.deinit(alloc);

    var columns = std.ArrayListUnmanaged(runtime_schema.RelationalColumn).empty;
    errdefer {
        clearDdlRelationalColumns(alloc, columns.items);
        columns.deinit(alloc);
    }
    var primary_key: ?runtime_schema.PrimaryKey = null;
    errdefer if (primary_key) |pk| freeDdlPrimaryKey(alloc, pk);
    var periods = std.ArrayListUnmanaged(runtime_schema.RelationalPeriod).empty;
    errdefer {
        for (periods.items) |period| freeDdlPeriod(alloc, period);
        periods.deinit(alloc);
    }
    var unique_constraints = std.ArrayListUnmanaged(runtime_schema.UniqueConstraint).empty;
    errdefer {
        clearDdlUniqueConstraints(alloc, unique_constraints.items);
        unique_constraints.deinit(alloc);
    }
    var foreign_keys = std.ArrayListUnmanaged(runtime_schema.ForeignKey).empty;
    errdefer {
        clearDdlForeignKeys(alloc, foreign_keys.items);
        foreign_keys.deinit(alloc);
    }
    var checks = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    errdefer {
        clearDdlRelationalChecks(alloc, checks.items);
        checks.deinit(alloc);
    }

    while (true) {
        var element_prefix = try grammar.parseCreateTableElementPrefixAlloc(alloc, tokens, pos);
        defer element_prefix.deinit(alloc);

        if (element_prefix.kind == .column) {
            try parseDdlColumnDefinitionAlloc(alloc, tokens, pos, hooks, &columns, &periods, &primary_key, &unique_constraints, &foreign_keys, &checks);
        } else {
            try parseDdlTableConstraintAlloc(alloc, tokens, pos, hooks, element_prefix.constraint_name, &primary_key, &periods, &unique_constraints, &foreign_keys, &checks);
        }

        if (cursor.matchToken(.comma) == null) break;
    }
    try cursor.expectToken(.rparen);
    const system_versioned = try parseOptionalCreateTableSystemVersioning(tokens, pos);

    const owned_columns = try columns.toOwnedSlice(alloc);
    var columns_transferred = false;
    errdefer if (!columns_transferred) freeDdlRelationalColumns(alloc, owned_columns);
    const owned_periods = try periods.toOwnedSlice(alloc);
    var periods_transferred = false;
    errdefer if (!periods_transferred) freeDdlPeriods(alloc, owned_periods);
    const owned_unique_constraints = try unique_constraints.toOwnedSlice(alloc);
    var unique_transferred = false;
    errdefer if (!unique_transferred) freeDdlUniqueConstraints(alloc, owned_unique_constraints);
    const owned_foreign_keys = try foreign_keys.toOwnedSlice(alloc);
    var foreign_transferred = false;
    errdefer if (!foreign_transferred) freeDdlForeignKeys(alloc, owned_foreign_keys);
    const owned_checks = try checks.toOwnedSlice(alloc);
    var checks_transferred = false;
    errdefer if (!checks_transferred) freeDdlRelationalChecks(alloc, owned_checks);

    header_transferred = true;
    columns_transferred = true;
    periods_transferred = true;
    unique_transferred = true;
    foreign_transferred = true;
    checks_transferred = true;
    return .{
        .table_name = header.table_name,
        .if_not_exists = header.if_not_exists,
        .columns = owned_columns,
        .primary_key = primary_key,
        .periods = owned_periods,
        .unique_constraints = owned_unique_constraints,
        .foreign_keys = owned_foreign_keys,
        .checks = owned_checks,
        .system_versioned = system_versioned,
    };
}

fn parseOptionalCreateTableSystemVersioning(
    tokens: []const grammar.Token,
    pos: *usize,
) !bool {
    const cursor = parser.Cursor.init(tokens, pos);
    if (!cursor.matchKeyword("with")) return false;
    if (!cursor.matchKeyword("system")) return error.UnsupportedSqlShape;
    if (!cursor.matchKeyword("versioning")) return error.UnsupportedSqlShape;
    return true;
}

pub fn parseCreateTablePlanAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    hooks: DdlColumnDefinitionOptions,
) !CreateTablePlan {
    var plan = try parseCreateTableDefinitionAlloc(alloc, tokens, pos, hooks);
    errdefer plan.deinit(alloc);
    try grammar.parseAdapterNoopStatementEnd(tokens, pos);
    return plan;
}

fn parseGeneratedCreateTableTailPlanAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    hooks: DdlColumnDefinitionOptions,
) !CreateTablePlan {
    var state = parser_context.ParserState{
        .alloc = alloc,
        .tokens = tokens,
        .pos = pos.*,
        .schema = hooks.schema,
        .params = hooks.params,
        .function_bindings = hooks.function_bindings,
        .field_expression_qualifiers = hooks.field_expression_qualifiers,
        .returning_expression_qualifiers = hooks.returning_expression_qualifiers,
        .defer_row_expression_field_validation = hooks.defer_row_expression_field_validation,
    };
    var local_hooks = parser_context.ParserState.ContextAccessors.ddlColumnDefinitionOptions(&state);
    local_hooks.parse_rewrite_expression = hooks.parse_rewrite_expression;

    var plan = try parseCreateTablePlanAlloc(alloc, tokens, &state.pos, local_hooks);
    errdefer plan.deinit(alloc);
    pos.* = state.pos;
    if (pos.* != tokens.len) return error.UnsupportedSqlShape;
    return plan;
}

fn parseGeneratedCreateTablePartitionTailPlanAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
) !CreateTablePartitionPlan {
    var plan = try parseCreateTablePartitionPlanTailAlloc(alloc, tokens, pos);
    errdefer plan.deinit(alloc);
    if (pos.* != tokens.len) return error.UnsupportedSqlShape;
    return plan;
}

fn parseGeneratedCreatePartitionedTableTailPlanAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    hooks: DdlColumnDefinitionOptions,
) !CreatePartitionedTablePlan {
    var plan = try parseCreatePartitionedTablePlanAlloc(alloc, tokens, pos, hooks);
    errdefer plan.deinit(alloc);
    if (pos.* != tokens.len) return error.UnsupportedSqlShape;
    return plan;
}

fn tablePartitionPlanFromGeneratedAlterTableAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
) !TablePartitionCatalogPlan {
    const tail = generatedStatementTail(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    var pos: usize = 0;
    var plan = try parseAlterTablePartitionPlanTailAlloc(alloc, tail, &pos);
    errdefer plan.deinit(alloc);
    if (pos != tail.len) return error.UnsupportedSqlShape;
    return plan;
}

pub fn parseRelationLifetimePlanAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    hooks: DdlColumnDefinitionOptions,
) !RelationLifetimePlan {
    const prefix = try grammar.parseRelationLifetimePrefix(tokens, pos);
    var create_table = try parseCreateTablePlanAlloc(alloc, tokens, pos, hooks);
    errdefer create_table.deinit(alloc);
    return .{ .kind = prefix.kind, .create_table = create_table };
}

fn parseGeneratedRelationLifetimePlanAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    statement_span: token_mod.SourceSpan,
    hooks: DdlColumnDefinitionOptions,
) !RelationLifetimePlan {
    const end = generatedStatementEnd(tokens, statement_span) orelse return error.UnsupportedSqlShape;
    var state = parser_context.ParserState{
        .alloc = alloc,
        .tokens = tokens,
        .pos = pos.*,
        .schema = hooks.schema,
        .params = hooks.params,
        .function_bindings = hooks.function_bindings,
        .field_expression_qualifiers = hooks.field_expression_qualifiers,
        .returning_expression_qualifiers = hooks.returning_expression_qualifiers,
        .defer_row_expression_field_validation = hooks.defer_row_expression_field_validation,
    };
    var local_hooks = parser_context.ParserState.ContextAccessors.ddlColumnDefinitionOptions(&state);
    local_hooks.parse_rewrite_expression = hooks.parse_rewrite_expression;

    var plan = try parseRelationLifetimePlanAlloc(alloc, tokens, &state.pos, local_hooks);
    errdefer plan.deinit(alloc);
    pos.* = state.pos;
    if (!generatedStatementConsumedThrough(tokens, end, pos.*)) return error.UnsupportedSqlShape;
    return plan;
}

pub fn makeDdlForeignKeyAlloc(
    alloc: std.mem.Allocator,
    constraint_name: ?[]const u8,
    child: grammar.DdlForeignKeyColumnListSyntax,
    parent_table: []const u8,
    parent: grammar.DdlForeignKeyColumnListSyntax,
    options: DdlForeignKeyOptions,
) !runtime_schema.ForeignKey {
    if ((child.period == null) != (parent.period == null)) return error.UnsupportedSqlShape;
    if (child.period != null and !binder.foreignKeyActionSupportsTemporalUpdate(options.on_update)) return error.UnsupportedSqlShape;
    return try makeDdlForeignKeyFromPartsAlloc(
        alloc,
        constraint_name,
        child.columns,
        child.period,
        parent_table,
        parent.columns,
        parent.period,
        options,
    );
}

pub fn makeDdlInlineForeignKeyAlloc(
    alloc: std.mem.Allocator,
    constraint_name: ?[]const u8,
    child_columns: []const []const u8,
    parent_table: []const u8,
    parent_columns: []const []const u8,
    options: DdlForeignKeyOptions,
) !runtime_schema.ForeignKey {
    return try makeDdlForeignKeyFromPartsAlloc(
        alloc,
        constraint_name,
        child_columns,
        null,
        parent_table,
        parent_columns,
        null,
        options,
    );
}

pub fn makeDdlRelationalCheckFromExpressionConditionAlloc(
    alloc: std.mem.Allocator,
    constraint_name: ?[]const u8,
    condition: db_mod.types.RelationalRowsExpressionCondition,
) !runtime_schema.RelationalCheck {
    const name = try ddlCheckConstraintNameAlloc(alloc, constraint_name, condition);
    var name_transferred = false;
    errdefer if (!name_transferred) alloc.free(name);

    if (try simpleDdlRelationalCheckFromExpressionConditionAlloc(alloc, name, condition)) |check| {
        alloc.free(name);
        return check;
    }

    const field = try alloc.dupe(u8, "");
    var field_transferred = false;
    errdefer if (!field_transferred) alloc.free(field);
    const expression = try plan_mod.cloneExpressionConditionAlloc(alloc, condition);
    var expression_transferred = false;
    errdefer if (!expression_transferred) plan_mod.freeExpressionCondition(alloc, expression);
    name_transferred = true;
    field_transferred = true;
    expression_transferred = true;
    return .{ .name = name, .field = field, .expression = expression };
}

fn ddlCheckConstraintNameAlloc(
    alloc: std.mem.Allocator,
    constraint_name: ?[]const u8,
    condition: db_mod.types.RelationalRowsExpressionCondition,
) ![]const u8 {
    if (constraint_name) |name| return try alloc.dupe(u8, name);
    if (condition.lhs.kind == .field and condition.lhs.field.len > 0) {
        return try std.fmt.allocPrint(alloc, "{s}_{s}_check", .{ condition.lhs.field, relationalCheckOpToken(condition.op) });
    }
    return try std.fmt.allocPrint(alloc, "expression_{s}_check", .{relationalCheckOpToken(condition.op)});
}

fn simpleDdlRelationalCheckFromExpressionConditionAlloc(
    alloc: std.mem.Allocator,
    name: []const u8,
    condition: db_mod.types.RelationalRowsExpressionCondition,
) !?runtime_schema.RelationalCheck {
    if (condition.lhs.kind != .field or condition.lhs.field.len == 0 or condition.lhs.field_source != .row) return null;
    const value_json: ?[]const u8 = switch (condition.op) {
        .is_null, .is_not_null => if (condition.rhs.len == 0) null else return null,
        else => blk: {
            if (condition.rhs.len != 1 or condition.rhs[0].kind != .value or condition.rhs[0].value_json.len == 0) return null;
            break :blk condition.rhs[0].value_json;
        },
    };
    const owned_name = try alloc.dupe(u8, name);
    var name_transferred = false;
    errdefer if (!name_transferred) alloc.free(owned_name);
    const field = try alloc.dupe(u8, condition.lhs.field);
    var field_transferred = false;
    errdefer if (!field_transferred) alloc.free(field);
    const owned_value = if (value_json) |value| try alloc.dupe(u8, value) else null;
    var value_transferred = false;
    errdefer if (!value_transferred) if (owned_value) |value| alloc.free(value);
    name_transferred = true;
    field_transferred = true;
    value_transferred = true;
    return .{
        .name = owned_name,
        .field = field,
        .op = condition.op,
        .value_json = owned_value,
    };
}

fn makeDdlForeignKeyFromPartsAlloc(
    alloc: std.mem.Allocator,
    constraint_name: ?[]const u8,
    child_columns: []const []const u8,
    child_period: ?[]const u8,
    parent_table: []const u8,
    parent_columns: []const []const u8,
    parent_period: ?[]const u8,
    options: DdlForeignKeyOptions,
) !runtime_schema.ForeignKey {
    const name = if (constraint_name) |existing|
        try alloc.dupe(u8, existing)
    else
        try std.fmt.allocPrint(alloc, "{s}_{s}_fkey", .{ parent_table, child_columns[0] });
    errdefer alloc.free(name);
    return .{
        .name = name,
        .child_columns = child_columns,
        .child_period = child_period,
        .parent_table = parent_table,
        .parent_columns = parent_columns,
        .parent_period = parent_period,
        .on_delete = options.on_delete,
        .on_update = options.on_update,
        .deferrable = options.deferrable,
        .timing = options.timing,
        .match = options.match,
    };
}

fn defaultUniqueConstraintNameAlloc(alloc: std.mem.Allocator, columns: []const []const u8) ![]const u8 {
    var buf = std.ArrayListUnmanaged(u8).empty;
    errdefer buf.deinit(alloc);
    try buf.appendSlice(alloc, columns[0]);
    for (columns[1..]) |column| {
        try buf.append(alloc, '_');
        try buf.appendSlice(alloc, column);
    }
    try buf.appendSlice(alloc, "_key");
    return try buf.toOwnedSlice(alloc);
}

pub fn routineKindFromSyntax(syntax: grammar.RoutineKindSyntax) RoutineKind {
    return switch (syntax) {
        .function => .function,
        .procedure => .procedure,
    };
}

pub fn ddlRangeBoundTypeForName(name: []const u8) ?runtime_schema.AntflyType {
    if (std.ascii.eqlIgnoreCase(name, "daterange")) return .datetime;
    if (std.ascii.eqlIgnoreCase(name, "tsrange")) return .datetime;
    if (std.ascii.eqlIgnoreCase(name, "tstzrange")) return .datetime;
    if (std.ascii.eqlIgnoreCase(name, "numrange")) return .numeric;
    return null;
}

pub fn ddlRangeTypeForName(name: []const u8) ?runtime_schema.RelationalPeriodRangeType {
    if (std.ascii.eqlIgnoreCase(name, "numrange")) return .numrange;
    if (std.ascii.eqlIgnoreCase(name, "daterange")) return .daterange;
    if (std.ascii.eqlIgnoreCase(name, "tsrange")) return .tsrange;
    if (std.ascii.eqlIgnoreCase(name, "tstzrange")) return .tstzrange;
    return null;
}

