fn generatedStatementTokenEnd(tokens: []const grammar.Token) usize {
    var end = tokens.len;
    while (end > 0 and tokens[end - 1].kind == .semicolon) : (end -= 1) {}
    return end;
}

fn validateGeneratedUnsupportedCatalogAst(
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlUnsupportedAst,
    boundary: GeneratedUnsupportedCatalogBoundary,
) !void {
    const end = generatedStatementTokenEnd(tokens);
    if (end == 0) return error.UnsupportedSqlShape;
    if (ast.kind != boundary.kind) return error.UnsupportedSqlShape;
    if (ast.reason != generatedUnsupportedExpectedReason(boundary.kind)) return error.UnsupportedSqlShape;
    if (ast.statement_span.start != tokens[0].source_start or ast.statement_span.end != tokens[end - 1].source_end) {
        return error.UnsupportedSqlShape;
    }
    if (ast.command_span.start != tokens[0].source_start or ast.command_span.end != tokens[0].source_end) {
        return error.UnsupportedSqlShape;
    }
    const subject_tokens = ast.subject_tokens orelse return error.UnsupportedSqlShape;
    if (!std.meta.eql(subject_tokens, generatedUnsupportedCatalogSubjectRange(tokens, boundary, end) orelse return error.UnsupportedSqlShape)) {
        return error.UnsupportedSqlShape;
    }
    switch (boundary.family) {
        .authorization => switch (boundary.kind) {
            .grant => {
                if (end < 1 or !tokens[0].matchesKeyword("grant")) {
                    return error.UnsupportedSqlShape;
                }
            },
            .revoke => {
                if (end < 1 or !tokens[0].matchesKeyword("revoke")) {
                    return error.UnsupportedSqlShape;
                }
            },
            else => return error.UnsupportedSqlShape,
        },
        .bulk_io => switch (boundary.kind) {
            .copy => {
                if (end < 1 or !tokens[0].matchesKeyword("copy")) {
                    return error.UnsupportedSqlShape;
                }
            },
            else => return error.UnsupportedSqlShape,
        },
        .comment => switch (boundary.kind) {
            .comment => {
                if (end < 1 or !tokens[0].matchesKeyword("comment")) {
                    return error.UnsupportedSqlShape;
                }
            },
            else => return error.UnsupportedSqlShape,
        },
        .logical_replication => switch (boundary.kind) {
            .alter_publication => {
                if (end < 2 or !tokens[0].matchesKeyword("alter") or !tokens[1].matchesKeyword("publication")) {
                    return error.UnsupportedSqlShape;
                }
            },
            .alter_subscription => {
                if (end < 2 or !tokens[0].matchesKeyword("alter") or !tokens[1].matchesKeyword("subscription")) {
                    return error.UnsupportedSqlShape;
                }
            },
            .create_publication => {
                if (end < 2 or !tokens[0].matchesKeyword("create") or !tokens[1].matchesKeyword("publication")) {
                    return error.UnsupportedSqlShape;
                }
            },
            .create_subscription => {
                if (end < 2 or !tokens[0].matchesKeyword("create") or !tokens[1].matchesKeyword("subscription")) {
                    return error.UnsupportedSqlShape;
                }
            },
            .drop_publication => {
                if (end < 2 or !tokens[0].matchesKeyword("drop") or !tokens[1].matchesKeyword("publication")) {
                    return error.UnsupportedSqlShape;
                }
            },
            .drop_subscription => {
                if (end < 2 or !tokens[0].matchesKeyword("drop") or !tokens[1].matchesKeyword("subscription")) {
                    return error.UnsupportedSqlShape;
                }
            },
            else => return error.UnsupportedSqlShape,
        },
        .maintenance => switch (boundary.kind) {
            .analyze => {
                if (end < 1 or !tokens[0].matchesKeyword("analyze")) {
                    return error.UnsupportedSqlShape;
                }
            },
            .cluster => {
                if (end < 1 or !tokens[0].matchesKeyword("cluster")) {
                    return error.UnsupportedSqlShape;
                }
            },
            .reindex => {
                if (end < 1 or !tokens[0].matchesKeyword("reindex")) {
                    return error.UnsupportedSqlShape;
                }
            },
            .vacuum => {
                if (end < 1 or !tokens[0].matchesKeyword("vacuum")) {
                    return error.UnsupportedSqlShape;
                }
            },
            else => return error.UnsupportedSqlShape,
        },
        .notification => switch (boundary.kind) {
            .listen => {
                if (end < 1 or !tokens[0].matchesKeyword("listen")) {
                    return error.UnsupportedSqlShape;
                }
            },
            .notify => {
                if (end < 1 or !tokens[0].matchesKeyword("notify")) {
                    return error.UnsupportedSqlShape;
                }
            },
            .unlisten => {
                if (end < 1 or !tokens[0].matchesKeyword("unlisten")) {
                    return error.UnsupportedSqlShape;
                }
            },
            else => return error.UnsupportedSqlShape,
        },
        .procedure_call => switch (boundary.kind) {
            .call => {
                if (end < 1 or !tokens[0].matchesKeyword("call")) {
                    return error.UnsupportedSqlShape;
                }
            },
            else => return error.UnsupportedSqlShape,
        },
        .transaction_control => switch (boundary.kind) {
            .lock => {
                if (end < 1 or !tokens[0].matchesKeyword("lock")) {
                    return error.UnsupportedSqlShape;
                }
            },
            else => return error.UnsupportedSqlShape,
        },
        .update_policy_trigger => switch (boundary.kind) {
            .create_trigger => {
                if (end >= 4 and
                    tokens[0].matchesKeyword("create") and
                    tokens[1].matchesKeyword("or") and
                    tokens[2].matchesKeyword("replace") and
                    tokens[3].matchesKeyword("trigger"))
                {
                    return;
                }
                if (end < 2 or !tokens[0].matchesKeyword("create") or !tokens[1].matchesKeyword("trigger")) {
                    return error.UnsupportedSqlShape;
                }
            },
            .drop_trigger => {
                if (end < 2 or !tokens[0].matchesKeyword("drop") or !tokens[1].matchesKeyword("trigger")) {
                    return error.UnsupportedSqlShape;
                }
            },
            else => return error.UnsupportedSqlShape,
        },
    }
}

fn generatedUnsupportedCatalogSubjectRange(
    tokens: []const grammar.Token,
    boundary: GeneratedUnsupportedCatalogBoundary,
    end: usize,
) ?generated_parser.GeneratedSqlTokenRange {
    const start: usize = switch (boundary.family) {
        .update_policy_trigger => switch (boundary.kind) {
            .create_trigger => if (end > 3 and
                tokens[1].matchesKeyword("or") and
                tokens[2].matchesKeyword("replace") and
                tokens[3].matchesKeyword("trigger"))
                4
            else
                2,
            .drop_trigger => 2,
            else => return null,
        },
        else => 1,
    };
    return if (end > start) .{ .start = start, .end = end } else null;
}

fn catalogDdlPlanFromGeneratedUnsupportedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    ast: generated_parser.GeneratedSqlUnsupportedAst,
    boundary: GeneratedUnsupportedCatalogBoundary,
    options: DdlPlanParserOptions,
) !LegacyDdlParserPlan {
    try validateGeneratedUnsupportedCatalogAst(tokens, ast, boundary);
    const start_pos = pos.*;
    var plan = parseLegacyDdlParserPlanAlloc(alloc, tokens, pos, options) catch |err| {
        pos.* = start_pos;
        return err;
    };
    errdefer {
        plan.deinit(alloc);
        pos.* = start_pos;
    }
    if (pos.* != tokens.len) return error.UnsupportedSqlShape;
    switch (boundary.family) {
        .authorization => switch (boundary.kind) {
            .grant => switch (plan) {
                .authorization_catalog => |catalog| switch (catalog) {
                    .grant_privilege => {},
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            .revoke => switch (plan) {
                .authorization_catalog => |catalog| switch (catalog) {
                    .revoke_privilege => {},
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        .bulk_io => switch (boundary.kind) {
            .copy => switch (plan) {
                .bulk_io => {},
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        .comment => switch (boundary.kind) {
            .comment => switch (plan) {
                .comment_metadata => {},
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        .logical_replication => switch (boundary.kind) {
            .alter_publication => switch (plan) {
                .logical_replication => |logical| switch (logical) {
                    .publication => |publication| switch (publication) {
                        .alter => {},
                        else => return error.UnsupportedSqlShape,
                    },
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            .alter_subscription => switch (plan) {
                .logical_replication => |logical| switch (logical) {
                    .subscription => |subscription| switch (subscription) {
                        .alter => {},
                        else => return error.UnsupportedSqlShape,
                    },
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            .create_publication => switch (plan) {
                .logical_replication => |logical| switch (logical) {
                    .publication => |publication| switch (publication) {
                        .create => {},
                        else => return error.UnsupportedSqlShape,
                    },
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            .create_subscription => switch (plan) {
                .logical_replication => |logical| switch (logical) {
                    .subscription => |subscription| switch (subscription) {
                        .create => {},
                        else => return error.UnsupportedSqlShape,
                    },
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            .drop_publication => switch (plan) {
                .logical_replication => |logical| switch (logical) {
                    .publication => |publication| switch (publication) {
                        .drop => {},
                        else => return error.UnsupportedSqlShape,
                    },
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            .drop_subscription => switch (plan) {
                .logical_replication => |logical| switch (logical) {
                    .subscription => |subscription| switch (subscription) {
                        .drop => {},
                        else => return error.UnsupportedSqlShape,
                    },
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        .maintenance => switch (boundary.kind) {
            .analyze => switch (plan) {
                .maintenance_job => |maintenance| switch (maintenance) {
                    .analyze => {},
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            .cluster => switch (plan) {
                .maintenance_job => |maintenance| switch (maintenance) {
                    .cluster => {},
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            .reindex => switch (plan) {
                .maintenance_job => |maintenance| switch (maintenance) {
                    .reindex => {},
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            .vacuum => switch (plan) {
                .maintenance_job => |maintenance| switch (maintenance) {
                    .vacuum => {},
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        .notification => switch (boundary.kind) {
            .listen => switch (plan) {
                .notification_channel => |catalog| switch (catalog) {
                    .listen => {},
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            .notify => switch (plan) {
                .notification_channel => |catalog| switch (catalog) {
                    .notify => {},
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            .unlisten => switch (plan) {
                .notification_channel => |catalog| switch (catalog) {
                    .unlisten => {},
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        .procedure_call => switch (boundary.kind) {
            .call => switch (plan) {
                .procedure_call => {},
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        .transaction_control => switch (boundary.kind) {
            .lock => switch (plan) {
                .transaction_control => |transaction| switch (transaction) {
                    .table_lock => {},
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        .update_policy_trigger => switch (boundary.kind) {
            .create_trigger => switch (plan) {
                .create_update_policy => {},
                .trigger_catalog => |trigger| switch (trigger) {
                    .create => {},
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            .drop_trigger => switch (plan) {
                .alter_table => |alter| {
                    if (alter.operations.len != 1) return error.UnsupportedSqlShape;
                    switch (alter.operations[0]) {
                        .drop_update_policy => {},
                        else => return error.UnsupportedSqlShape,
                    }
                },
                .trigger_catalog => |trigger| switch (trigger) {
                    .drop => {},
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
    }
    return plan;
}

fn logicalDdlPlanFromGeneratedUnsupportedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    ast: generated_parser.GeneratedSqlUnsupportedAst,
    boundary: GeneratedUnsupportedCatalogBoundary,
    options: DdlPlanParserOptions,
) !binder.LogicalSqlPlan {
    try validateGeneratedUnsupportedCatalogAst(tokens, ast, boundary);
    const start_pos = pos.*;
    var plan = parseLogicalDdlPlanTokensAlloc(alloc, tokens, pos, options) catch |err| {
        pos.* = start_pos;
        return err;
    };
    errdefer {
        plan.deinit(alloc);
        pos.* = start_pos;
    }
    if (pos.* != tokens.len) return error.UnsupportedSqlShape;
    try validateGeneratedUnsupportedLogicalPlan(plan, boundary);
    return plan;
}

fn validateGeneratedUnsupportedLogicalPlan(
    plan: binder.LogicalSqlPlan,
    boundary: GeneratedUnsupportedCatalogBoundary,
) !void {
    switch (boundary.family) {
        .authorization => switch (boundary.kind) {
            .grant => switch (plan) {
                .auth => |auth| switch (auth) {
                    .authorization_catalog => |catalog| switch (catalog) {
                        .grant_privilege => {},
                        else => return error.UnsupportedSqlShape,
                    },
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            .revoke => switch (plan) {
                .auth => |auth| switch (auth) {
                    .authorization_catalog => |catalog| switch (catalog) {
                        .revoke_privilege => {},
                        else => return error.UnsupportedSqlShape,
                    },
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        .bulk_io => switch (boundary.kind) {
            .copy => switch (plan) {
                .bulk_io => {},
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        .comment => switch (boundary.kind) {
            .comment => switch (plan) {
                .catalog_ddl => |catalog| switch (catalog) {
                    .comment_metadata => {},
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        .logical_replication => switch (boundary.kind) {
            .alter_publication => try validateLogicalReplicationPlanKind(plan, .publication, .alter),
            .alter_subscription => try validateLogicalReplicationPlanKind(plan, .subscription, .alter),
            .create_publication => try validateLogicalReplicationPlanKind(plan, .publication, .create),
            .create_subscription => try validateLogicalReplicationPlanKind(plan, .subscription, .create),
            .drop_publication => try validateLogicalReplicationPlanKind(plan, .publication, .drop),
            .drop_subscription => try validateLogicalReplicationPlanKind(plan, .subscription, .drop),
            else => return error.UnsupportedSqlShape,
        },
        .maintenance => switch (boundary.kind) {
            .analyze => try validateGeneratedLogicalPlanExpectation(plan, .{ .maintenance = .analyze }),
            .cluster => try validateGeneratedLogicalPlanExpectation(plan, .{ .maintenance = .cluster }),
            .reindex => try validateGeneratedLogicalPlanExpectation(plan, .{ .maintenance = .reindex }),
            .vacuum => try validateGeneratedLogicalPlanExpectation(plan, .{ .maintenance = .vacuum }),
            else => return error.UnsupportedSqlShape,
        },
        .notification => switch (boundary.kind) {
            .listen => try validateGeneratedLogicalPlanExpectation(plan, .{ .notification = .listen }),
            .notify => try validateGeneratedLogicalPlanExpectation(plan, .{ .notification = .notify }),
            .unlisten => try validateGeneratedLogicalPlanExpectation(plan, .{ .notification = .unlisten }),
            else => return error.UnsupportedSqlShape,
        },
        .procedure_call => switch (boundary.kind) {
            .call => try validateGeneratedLogicalPlanExpectation(plan, .{ .routine = .procedure_call }),
            else => return error.UnsupportedSqlShape,
        },
        .transaction_control => switch (boundary.kind) {
            .lock => switch (plan) {
                .transaction => |transaction| switch (transaction) {
                    .control => |control| switch (control) {
                        .table_lock => {},
                        else => return error.UnsupportedSqlShape,
                    },
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        .update_policy_trigger => switch (boundary.kind) {
            .create_trigger => switch (plan) {
                .table_ddl => |table| switch (table) {
                    .create_update_policy => {},
                    else => return error.UnsupportedSqlShape,
                },
                .routine => |routine| switch (routine) {
                    .trigger_catalog => |trigger| switch (trigger) {
                        .create => {},
                        else => return error.UnsupportedSqlShape,
                    },
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            .drop_trigger => switch (plan) {
                .table_ddl => |table| switch (table) {
                    .alter_table => |alter| {
                        if (alter.operations.len != 1) return error.UnsupportedSqlShape;
                        switch (alter.operations[0]) {
                            .drop_update_policy => {},
                            else => return error.UnsupportedSqlShape,
                        }
                    },
                    else => return error.UnsupportedSqlShape,
                },
                .routine => |routine| switch (routine) {
                    .trigger_catalog => |trigger| switch (trigger) {
                        .drop => {},
                        else => return error.UnsupportedSqlShape,
                    },
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
    }
}

fn validateLogicalReplicationPlanKind(
    plan: binder.LogicalSqlPlan,
    expected_family: enum { publication, subscription },
    expected_action: enum { create, alter, drop },
) !void {
    const logical_replication = switch (plan) {
        .catalog_ddl => |catalog| switch (catalog) {
            .logical_replication => |logical| logical,
            else => return error.UnsupportedSqlShape,
        },
        else => return error.UnsupportedSqlShape,
    };
    switch (expected_family) {
        .publication => switch (logical_replication) {
            .publication => |publication| switch (expected_action) {
                .create => switch (publication) {
                    .create => {},
                    else => return error.UnsupportedSqlShape,
                },
                .alter => switch (publication) {
                    .alter => {},
                    else => return error.UnsupportedSqlShape,
                },
                .drop => switch (publication) {
                    .drop => {},
                    else => return error.UnsupportedSqlShape,
                },
            },
            else => return error.UnsupportedSqlShape,
        },
        .subscription => switch (logical_replication) {
            .subscription => |subscription| switch (expected_action) {
                .create => switch (subscription) {
                    .create => {},
                    else => return error.UnsupportedSqlShape,
                },
                .alter => switch (subscription) {
                    .alter => {},
                    else => return error.UnsupportedSqlShape,
                },
                .drop => switch (subscription) {
                    .drop => {},
                    else => return error.UnsupportedSqlShape,
                },
            },
            else => return error.UnsupportedSqlShape,
        },
    }
}

fn legacyDdlParserPlanAlloc(
    alloc: std.mem.Allocator,
    sql: []const u8,
) !LegacyDdlParserPlan {
    return try legacyDdlParserPlanWithFunctionBindingsAlloc(alloc, sql, .{});
}

fn legacyDdlParserPlanWithFunctionBindingsAlloc(
    alloc: std.mem.Allocator,
    sql: []const u8,
    function_bindings: lower_expr.SqlFunctionBindings,
) !LegacyDdlParserPlan {
    var parsed_sql = try tokenized.ParsedSql.initAlloc(alloc, sql);
    defer parsed_sql.deinit(alloc);

    return try legacyDdlParserPlanParsedSqlWithFunctionBindingsAlloc(alloc, &parsed_sql, function_bindings);
}

fn legacyDdlParserPlanParsedSqlAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
) !LegacyDdlParserPlan {
    return try legacyDdlParserPlanParsedSqlWithFunctionBindingsAlloc(alloc, parsed_sql, .{});
}

pub fn planLogicalDdlPlanParsedSqlWithFunctionBindingsAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    function_bindings: lower_expr.SqlFunctionBindings,
) !binder.LogicalSqlPlan {
    return try parseLogicalDdlPlanAlloc(alloc, parsed_sql, function_bindings);
}

pub fn parseLogicalDdlPlanAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    function_bindings: lower_expr.SqlFunctionBindings,
) !binder.LogicalSqlPlan {
    switch (parsed_sql.statement) {
        .unsupported => return error.UnsupportedSqlShape,
        else => {},
    }
    const tokens = parsed_sql.items();
    var state = parser_context.ParserState{
        .alloc = alloc,
        .tokens = tokens,
        .function_bindings = function_bindings,
    };
    const options = DdlPlanParserOptions{
        .schema = state.schema,
        .field_expression_qualifiers = state.field_expression_qualifiers,
        .returning_expression_qualifiers = state.returning_expression_qualifiers,
        .defer_row_expression_field_validation = state.defer_row_expression_field_validation,
        .column_definition_options = parser_context.ParserState.ContextAccessors.ddlColumnDefinitionOptions(&state),
        .domain_options = parser_context.ParserState.ContextAccessors.ddlDomainOptions(&state),
        .create_index_options = parser_context.ParserState.ContextAccessors.createIndexOptions(&state),
        .row_security_policy_options = parser_context.ParserState.ContextAccessors.rowSecurityPolicyOptions(&state),
    };
    if (parsed_sql.generated_statement) |generated_statement| {
        const generated_ast = try generatedAstOrUnsupported(generated_statement);
        return try planGeneratedLogicalDdlAstAlloc(alloc, parsed_sql, tokens, &state, generated_statement, generated_ast, options);
    }
    return try parseLogicalDdlPlanTokensAlloc(alloc, tokens, &state.pos, options);
}

fn generatedAstOrUnsupported(generated_statement: tokenized.GeneratedRawSqlStatement) !generated_parser.GeneratedSqlAst {
    return generated_statement.ast orelse error.UnsupportedSqlShape;
}

pub fn planGeneratedLogicalDdlAstAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    tokens: []const grammar.Token,
    state: *parser_context.ParserState,
    generated_statement: tokenized.GeneratedRawSqlStatement,
    generated_ast: generated_parser.GeneratedSqlAst,
    options: DdlPlanParserOptions,
) !binder.LogicalSqlPlan {
    switch (generated_ast) {
        .session => |session_ast| return try sessionLogicalPlanFromGeneratedAstAlloc(alloc, tokens, session_ast),
        .prepared => |prepared_ast| return .{ .prepared_statement = try preparedStatementPlanFromGeneratedAstAlloc(alloc, parsed_sql, prepared_ast) },
        .prepared_transaction => |prepared_transaction_ast| return .{ .transaction = .{ .prepared = try preparedTransactionPlanFromGeneratedAstAlloc(alloc, tokens, prepared_transaction_ast) } },
        .transaction => |transaction_ast| {
            const transaction = transactionLogicalPlanFromGeneratedAstAlloc(alloc, tokens, transaction_ast) catch |err| switch (err) {
                error.UnsupportedSqlShape => {
                    try validateGeneratedTransactionAstSpans(tokens, transaction_ast);
                    if (transaction_ast.name_tokens != null or transaction_ast.mode_tokens != null) return err;
                    return .{ .other_ddl = .{ .adapter_noop = .{ .reason = .transaction_control } } };
                },
                else => return err,
            };
            return .{ .transaction = transaction };
        },
        .cursor => |cursor_ast| return .{ .cursor = try cursorPortalLogicalPlanFromGeneratedAstAlloc(alloc, tokens, cursor_ast) },
        .ddl, .extension_index => |ddl_ast| {
            if (generatedDdlUsesRuntimeBoundary(tokens, ddl_ast)) {
                return try logicalDdlPlanFromGeneratedAstAlloc(alloc, tokens, ddl_ast, options);
            }
        },
        .graph => |graph_ast| return try graphLogicalDdlPlanFromGeneratedAstAlloc(alloc, tokens, graph_ast),
        .unsupported => |unsupported_ast| {
            if (generatedUnsupportedCatalogBoundary(generated_statement.statement)) |boundary| {
                return logicalDdlPlanFromGeneratedUnsupportedAstAlloc(alloc, tokens, &state.pos, unsupported_ast, boundary, options) catch |err| switch (err) {
                    error.UnsupportedSqlShape => return err,
                    else => return err,
                };
            }
        },
        .read => |read_ast| {
            if (try advisoryLockPlanFromGeneratedReadAst(tokens, read_ast)) |advisory_lock| {
                return .{ .transaction = .{ .control = .{ .advisory_lock = advisory_lock } } };
            }
            return error.UnsupportedSqlShape;
        },
        .dml => return error.UnsupportedSqlShape,
    }
    return error.UnsupportedSqlShape;
}

const RoutineTriggerParser = struct {
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: usize = 0,

    fn parse(self: *@This()) !TriggerCatalogPlan {
        if (self.matchKeywordTag(.create)) {
            var replace_existing = false;
            if (self.matchKeywordTag(.@"or")) {
                try self.expectKeywordTag(.replace);
                replace_existing = true;
            }
            if (!self.matchKeywordTag(.trigger)) return error.NotTriggerDdl;
            return .{ .create = try self.parseCreateTriggerTail(replace_existing) };
        }
        if (self.matchKeywordTag(.drop)) {
            if (!self.matchKeywordTag(.trigger)) return error.NotTriggerDdl;
            return .{ .drop = try self.parseDropTriggerTail() };
        }
        return error.NotTriggerDdl;
    }

    fn parseCreateTriggerTail(self: *@This(), replace_existing: bool) !CreateRoutineTriggerPlan {
        const trigger_name = try self.parseIdentifierOwned();
        var trigger_transferred = false;
        errdefer if (!trigger_transferred) self.alloc.free(trigger_name);

        try self.expectKeywordTag(.before);
        const event = try self.parseTriggerEvent();
        try self.expectKeywordTag(.on);
        const table_name = try self.parseObjectIdentifierOwned();
        var table_transferred = false;
        errdefer if (!table_transferred) self.alloc.free(table_name);

        if (self.matchKeywordTag(.@"for")) {
            try self.expectKeywordTag(.each);
            try self.expectKeywordTag(.row);
        }

        try self.expectKeywordTag(.execute);
        if (!(self.matchKeywordTag(.function) or self.matchKeywordTag(.procedure))) return error.UnsupportedSqlShape;
        const function_name = try self.parseObjectIdentifierOwned();
        var function_transferred = false;
        errdefer if (!function_transferred) self.alloc.free(function_name);
        try self.expect(.lparen);
        try self.expect(.rparen);
        try self.expectStatementEnd();

        trigger_transferred = true;
        table_transferred = true;
        function_transferred = true;
        return .{
            .trigger_name = trigger_name,
            .table_name = table_name,
            .function_name = function_name,
            .event = event,
            .replace_existing = replace_existing,
        };
    }

    fn parseDropTriggerTail(self: *@This()) !DropRoutineTriggerPlan {
        var if_exists = false;
        if (self.matchKeywordTag(.@"if")) {
            try self.expectKeywordTag(.exists);
            if_exists = true;
        }
        const trigger_name = try self.parseIdentifierOwned();
        var trigger_transferred = false;
        errdefer if (!trigger_transferred) self.alloc.free(trigger_name);
        try self.expectKeywordTag(.on);
        _ = self.matchKeywordTag(.only);
        const table_name = try self.parseObjectIdentifierOwned();
        var table_transferred = false;
        errdefer if (!table_transferred) self.alloc.free(table_name);
        var cascade = false;
        if (self.matchKeywordTag(.cascade)) {
            cascade = true;
        } else {
            _ = self.matchKeywordTag(.restrict);
        }
        try self.expectStatementEnd();
        trigger_transferred = true;
        table_transferred = true;
        return .{
            .trigger_name = trigger_name,
            .table_name = table_name,
            .if_exists = if_exists,
            .cascade = cascade,
        };
    }

    fn parseTriggerEvent(self: *@This()) !RoutineTriggerEvent {
        if (self.matchKeywordTag(.insert)) return .insert;
        if (self.matchKeywordTag(.update)) {
            if (self.matchKeywordTag(.of)) return error.UnsupportedSqlShape;
            return .update;
        }
        if (self.matchKeywordTag(.delete)) return .delete;
        return error.UnsupportedSqlShape;
    }

    fn parseIdentifierOwned(self: *@This()) ![]u8 {
        if (self.pos >= self.tokens.len) return error.UnsupportedSqlShape;
        const token = self.tokens[self.pos];
        if (token.kind != .identifier) return error.UnsupportedSqlShape;
        self.pos += 1;
        return try self.alloc.dupe(u8, token.text);
    }

    fn parseObjectIdentifierOwned(self: *@This()) ![]u8 {
        var out: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        var first = true;
        while (true) {
            if (self.pos >= self.tokens.len) return error.UnsupportedSqlShape;
            const token = self.tokens[self.pos];
            if (token.kind != .identifier) return error.UnsupportedSqlShape;
            if (!first) try writer.writeByte('.');
            first = false;
            try writer.writeAll(token.text);
            self.pos += 1;
            if (self.pos >= self.tokens.len) break;
            if (!std.mem.eql(u8, self.tokens[self.pos].text, ".")) break;
            self.pos += 1;
        }
        return try out.toOwnedSlice();
    }

    fn expect(self: *@This(), kind: token_mod.TokenKind) !void {
        if (self.pos >= self.tokens.len or self.tokens[self.pos].kind != kind) return error.UnsupportedSqlShape;
        self.pos += 1;
    }

    fn matchKeywordTag(self: *@This(), keyword: token_mod.TokenKeyword) bool {
        if (self.pos >= self.tokens.len) return false;
        const token = self.tokens[self.pos];
        if (!token.matchesKeywordTag(keyword)) return false;
        self.pos += 1;
        return true;
    }

    fn expectKeywordTag(self: *@This(), keyword: token_mod.TokenKeyword) !void {
        if (!self.matchKeywordTag(keyword)) return error.UnsupportedSqlShape;
    }

    fn expectStatementEnd(self: *@This()) !void {
        if (self.pos < self.tokens.len and self.tokens[self.pos].kind == .semicolon) self.pos += 1;
        if (self.pos != self.tokens.len) return error.UnsupportedSqlShape;
    }
};

fn parseCreateRoutineTriggerCatalogPlanTailAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    replace_existing: bool,
) !TriggerCatalogPlan {
    var routine_trigger_parser = RoutineTriggerParser{ .alloc = alloc, .tokens = tokens, .pos = pos.* };
    if (!routine_trigger_parser.matchKeywordTag(.trigger)) return error.UnsupportedSqlShape;
    const create = try routine_trigger_parser.parseCreateTriggerTail(replace_existing);
    pos.* = routine_trigger_parser.pos;
    return .{ .create = create };
}

fn parseDropRoutineTriggerCatalogPlanTailAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
) !TriggerCatalogPlan {
    var routine_trigger_parser = RoutineTriggerParser{ .alloc = alloc, .tokens = tokens, .pos = pos.* };
    if (!routine_trigger_parser.matchKeywordTag(.trigger)) return error.UnsupportedSqlShape;
    const drop = try routine_trigger_parser.parseDropTriggerTail();
    pos.* = routine_trigger_parser.pos;
    return .{ .drop = drop };
}

fn parseCreateTriggerLegacyDdlPlanTailAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    replace_existing: bool,
) !LegacyDdlParserPlan {
    const checkpoint = pos.*;
    if (parseCreateUpdatePolicyTriggerPlanTailAlloc(alloc, tokens, pos)) |plan| {
        return .{ .create_update_policy = plan };
    } else |err| switch (err) {
        error.UnsupportedSqlShape => pos.* = checkpoint,
        else => return err,
    }
    return .{ .trigger_catalog = try parseCreateRoutineTriggerCatalogPlanTailAlloc(alloc, tokens, pos, replace_existing) };
}

fn parseDropTriggerLegacyDdlPlanTailAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
) !LegacyDdlParserPlan {
    const checkpoint = pos.*;
    if (parseDropUpdatePolicyTriggerPlanTailAlloc(alloc, tokens, pos)) |plan| {
        return .{ .alter_table = plan };
    } else |err| switch (err) {
        error.UnsupportedSqlShape => pos.* = checkpoint,
        else => return err,
    }
    return .{ .trigger_catalog = try parseDropRoutineTriggerCatalogPlanTailAlloc(alloc, tokens, pos) };
}

fn parseCreateTriggerLogicalDdlPlanTailAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    replace_existing: bool,
) !binder.LogicalSqlPlan {
    const checkpoint = pos.*;
    if (parseCreateUpdatePolicyTriggerPlanTailAlloc(alloc, tokens, pos)) |plan| {
        return .{ .table_ddl = .{ .create_update_policy = plan } };
    } else |err| switch (err) {
        error.UnsupportedSqlShape => pos.* = checkpoint,
        else => return err,
    }
    return .{ .routine = .{ .trigger_catalog = try parseCreateRoutineTriggerCatalogPlanTailAlloc(alloc, tokens, pos, replace_existing) } };
}

fn parseDropTriggerLogicalDdlPlanTailAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
) !binder.LogicalSqlPlan {
    const checkpoint = pos.*;
    if (parseDropUpdatePolicyTriggerPlanTailAlloc(alloc, tokens, pos)) |plan| {
        return .{ .table_ddl = .{ .alter_table = plan } };
    } else |err| switch (err) {
        error.UnsupportedSqlShape => pos.* = checkpoint,
        else => return err,
    }
    return .{ .routine = .{ .trigger_catalog = try parseDropRoutineTriggerCatalogPlanTailAlloc(alloc, tokens, pos) } };
}

pub fn lowerRoutineTriggerCatalogPlanParsedSqlAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
) !TriggerCatalogPlan {
    var routine_trigger_parser = RoutineTriggerParser{ .alloc = alloc, .tokens = parsed_sql.items() };
    return try routine_trigger_parser.parse();
}

fn legacyDdlParserPlanParsedSqlWithFunctionBindingsAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    function_bindings: lower_expr.SqlFunctionBindings,
) !LegacyDdlParserPlan {
    switch (parsed_sql.statement) {
        .unsupported => return error.UnsupportedSqlShape,
        else => {},
    }
    const tokens = parsed_sql.items();
    var state = parser_context.ParserState{
        .alloc = alloc,
        .tokens = tokens,
        .function_bindings = function_bindings,
    };
    const options = DdlPlanParserOptions{
        .schema = state.schema,
        .field_expression_qualifiers = state.field_expression_qualifiers,
        .returning_expression_qualifiers = state.returning_expression_qualifiers,
        .defer_row_expression_field_validation = state.defer_row_expression_field_validation,
        .column_definition_options = parser_context.ParserState.ContextAccessors.ddlColumnDefinitionOptions(&state),
        .domain_options = parser_context.ParserState.ContextAccessors.ddlDomainOptions(&state),
        .create_index_options = parser_context.ParserState.ContextAccessors.createIndexOptions(&state),
        .row_security_policy_options = parser_context.ParserState.ContextAccessors.rowSecurityPolicyOptions(&state),
    };
    if (parsed_sql.generated_statement) |generated_statement| {
        const generated_ast = try generatedAstOrUnsupported(generated_statement);
        return try legacyDdlParserPlanFromGeneratedAstAlloc(alloc, parsed_sql, tokens, &state, generated_statement, generated_ast, options);
    }
    return try parseLegacyDdlParserPlanAlloc(alloc, tokens, &state.pos, options);
}

fn legacyDdlParserPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    tokens: []const grammar.Token,
    state: *parser_context.ParserState,
    generated_statement: tokenized.GeneratedRawSqlStatement,
    generated_ast: generated_parser.GeneratedSqlAst,
    options: DdlPlanParserOptions,
) !LegacyDdlParserPlan {
    switch (generated_ast) {
        .session => |session_ast| return try sessionDdlPlanFromGeneratedAstAlloc(alloc, tokens, session_ast),
        .prepared => |prepared_ast| return .{ .prepared_statement = try preparedStatementPlanFromGeneratedAstAlloc(alloc, parsed_sql, prepared_ast) },
        .prepared_transaction => |prepared_transaction_ast| return .{ .prepared_transaction = try preparedTransactionPlanFromGeneratedAstAlloc(alloc, tokens, prepared_transaction_ast) },
        .transaction => |transaction_ast| return try transactionControlPlanFromGeneratedAstAlloc(alloc, tokens, transaction_ast),
        .cursor => |cursor_ast| return try cursorPortalPlanFromGeneratedAstAlloc(alloc, tokens, cursor_ast),
        .ddl, .extension_index => |ddl_ast| {
            if (generatedDdlUsesRuntimeBoundary(tokens, ddl_ast)) {
                return try ddlPlanFromGeneratedAstAlloc(alloc, tokens, ddl_ast, options);
            }
        },
        .graph => |graph_ast| return try graphDdlPlanFromGeneratedAstAlloc(alloc, tokens, graph_ast),
        .unsupported => |unsupported_ast| {
            if (generatedUnsupportedCatalogBoundary(generated_statement.statement)) |boundary| {
                return catalogDdlPlanFromGeneratedUnsupportedAstAlloc(alloc, tokens, &state.pos, unsupported_ast, boundary, options) catch |err| switch (err) {
                    error.UnsupportedSqlShape => return err,
                    else => return err,
                };
            }
        },
        .read => |read_ast| {
            if (try advisoryLockPlanFromGeneratedReadAst(tokens, read_ast)) |advisory_lock| {
                return .{ .transaction_control = .{ .advisory_lock = advisory_lock } };
            }
            return error.UnsupportedSqlShape;
        },
        .dml => return error.UnsupportedSqlShape,
    }
    return error.UnsupportedSqlShape;
}

const legacyDdlParserPlanForTestAlloc = legacyDdlParserPlanAlloc;
