                try std.testing.expectEqual(TransactionAccessMode.read_write, transaction.access_mode.?);
            },
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    }

    const noops = [_][]const u8{
        "BEGIN;",
        "BEGIN WORK;",
        "START TRANSACTION;",
        "COMMIT;",
        "COMMIT TRANSACTION;",
        "END;",
        "END WORK;",
        "END TRANSACTION;",
        "ROLLBACK;",
        "ROLLBACK WORK;",
    };
    for (noops) |sql| {
