test "sql adapter generated utility unsupported AST lowers to typed catalog plans" {
    const alloc = std.testing.allocator;

    const cases = [_]struct {
        sql: []const u8,
        kind: generated_parser.GeneratedSqlUnsupportedKind,
        trigger_replace_existing: bool = false,
    }{
        .{ .sql = "CALL rotate_usage();", .kind = .call },
        .{ .sql = "COMMENT ON TABLE usage_records IS 'usage';", .kind = .comment },
        .{ .sql = "GRANT SELECT ON TABLE usage_records TO app_reader;", .kind = .grant },
        .{ .sql = "REVOKE SELECT ON TABLE usage_records FROM app_reader;", .kind = .revoke },
        .{ .sql = "LOCK TABLE usage_records IN SHARE MODE;", .kind = .lock },
        .{ .sql = "CREATE TRIGGER update_timestamp BEFORE UPDATE ON usage_records EXECUTE FUNCTION touch_updated_at('updated_at_ns');", .kind = .create_trigger },
        .{ .sql = "CREATE OR REPLACE TRIGGER update_timestamp BEFORE UPDATE ON usage_records EXECUTE FUNCTION touch_updated_at('updated_at_ns');", .kind = .create_trigger, .trigger_replace_existing = true },
        .{ .sql = "DROP TRIGGER IF EXISTS update_timestamp ON usage_records;", .kind = .drop_trigger },
    };

    for (cases) |case| {
        var parsed_sql = try tokenized.ParsedSql.initAlloc(alloc, case.sql);
        defer parsed_sql.deinit(alloc);
        var lowered = try legacyDdlParserPlanParsedSqlAlloc(alloc, &parsed_sql);
        defer lowered.deinit(alloc);
        switch (case.kind) {
            .call => switch (lowered) {
                .procedure_call => {},
                else => return error.TestUnexpectedResult,
            },
            .comment => switch (lowered) {
                .comment_metadata => {},
                else => return error.TestUnexpectedResult,
            },
            .grant => switch (lowered) {
                .authorization_catalog => |catalog| switch (catalog) {
                    .grant_privilege => {},
                    else => return error.TestUnexpectedResult,
                },
                else => return error.TestUnexpectedResult,
            },
            .revoke => switch (lowered) {
                .authorization_catalog => |catalog| switch (catalog) {
                    .revoke_privilege => {},
                    else => return error.TestUnexpectedResult,
                },
                else => return error.TestUnexpectedResult,
            },
            .lock => switch (lowered) {
                .transaction_control => |transaction| switch (transaction) {
                    .table_lock => {},
                    else => return error.TestUnexpectedResult,
                },
                else => return error.TestUnexpectedResult,
            },
            .create_trigger => switch (lowered) {
                .create_update_policy => |trigger| {
                    try std.testing.expectEqual(case.trigger_replace_existing, trigger.replace_existing);
                },
                else => return error.TestUnexpectedResult,
            },
            .drop_trigger => switch (lowered) {
                .alter_table => |alter| {
                    try std.testing.expectEqual(@as(usize, 1), alter.operations.len);
                    switch (alter.operations[0]) {
                        .drop_update_policy => {},
                        else => return error.TestUnexpectedResult,
                    }
                },
                else => return error.TestUnexpectedResult,
            },
            else => return error.TestUnexpectedResult,
        }
    }

    var malformed_kind = try tokenized.ParsedSql.initAlloc(
        alloc,
        "CALL rotate_usage();",
    );
    defer malformed_kind.deinit(alloc);
    if (malformed_kind.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| {
            switch (generated_ast.*) {
                .unsupported => |*unsupported| unsupported.kind = .grant,
                else => return error.TestUnexpectedResult,
            }
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    try std.testing.expectError(error.UnsupportedSqlShape, legacyDdlParserPlanParsedSqlAlloc(alloc, &malformed_kind));

    var malformed_subject = try tokenized.ParsedSql.initAlloc(
        alloc,
        "GRANT SELECT ON TABLE usage_records TO app_reader;",
    );
    defer malformed_subject.deinit(alloc);
    if (malformed_subject.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| {
            switch (generated_ast.*) {
                .unsupported => |*unsupported| unsupported.subject_tokens = .{ .start = 0, .end = malformed_subject.items().len },
                else => return error.TestUnexpectedResult,
            }
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    try std.testing.expectError(error.UnsupportedSqlShape, legacyDdlParserPlanParsedSqlAlloc(alloc, &malformed_subject));

    var malformed_trigger_subject = try tokenized.ParsedSql.initAlloc(
        alloc,
        "CREATE TRIGGER update_timestamp BEFORE UPDATE ON usage_records EXECUTE FUNCTION touch_updated_at('updated_at_ns');",
    );
    defer malformed_trigger_subject.deinit(alloc);
    if (malformed_trigger_subject.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| {
            switch (generated_ast.*) {
                .unsupported => |*unsupported| {
                    try std.testing.expectEqual(generated_parser.GeneratedSqlUnsupportedKind.create_trigger, unsupported.kind);
                    try std.testing.expectEqual(generated_parser.GeneratedSqlTokenRange{ .start = 2, .end = malformed_trigger_subject.items().len - 1 }, unsupported.subject_tokens.?);
                    unsupported.subject_tokens = .{ .start = 1, .end = malformed_trigger_subject.items().len - 1 };
                },
                else => return error.TestUnexpectedResult,
            }
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    try std.testing.expectError(error.UnsupportedSqlShape, legacyDdlParserPlanParsedSqlAlloc(alloc, &malformed_trigger_subject));
}

