    conjunction_policy.deinit(alloc);

    var alter_policy: RowSecurityCatalogPlan = .{ .alter_policy = .{
        .policy_name = try alloc.dupe(u8, "tenant_isolation"),
        .table_name = try alloc.dupe(u8, "tenant_events"),
